window.LANG_PACKS.ru.builder = [{"id":1,"vi":"không","note":"'не' đứng ngay trước động từ để phủ định (не говорю = không nói); khi trả lời 'không' thì dùng 'нет'.","pivot":{"t":"не","ph":"nye"},"branches":[{"steps":[{"t":"говорю","ph":"ga-va-RYU","vi":"(tôi) nói","hl":[]},{"t":"не говорю","ph":"nye ga-va-RYU","vi":"không nói","hl":["не"]},{"t":"Я не говорю по-русски.","ph":"ya nye ga-va-RYU pa-RUS-ki","vi":"Tôi không nói tiếng Nga.","hl":["не"],"tokens":["Я","не","говорю","по-русски"]}]},{"steps":[{"t":"понимаю","ph":"pa-ni-MA-yu","vi":"(tôi) hiểu","hl":[]},{"t":"не понимаю","ph":"nye pa-ni-MA-yu","vi":"không hiểu","hl":["не"]},{"t":"Я совсем не понимаю.","ph":"ya sav-SYEM nye pa-ni-MA-yu","vi":"Tôi hoàn toàn không hiểu.","hl":["не"],"tokens":["Я","совсем","не","понимаю"]}]},{"steps":[{"t":"знаю","ph":"ZNA-yu","vi":"(tôi) biết","hl":[]},{"t":"не знаю","ph":"nye ZNA-yu","vi":"không biết","hl":["не"]},{"t":"Я не знаю дорогу.","ph":"ya nye ZNA-yu da-RO-gu","vi":"Tôi không biết đường.","hl":["не"],"tokens":["Я","не","знаю","дорогу"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"не"},{"k":"V","t":"Động từ"},{"k":"O","t":"(Tân ngữ)"}],"points":["\"не\" đứng ngay trước từ bị phủ định, thường là động từ (\"Я не знаю\" = Tôi không biết).","Khi trả lời \"Không.\" cho câu hỏi có/không thì dùng \"нет\", không dùng \"не\" (\"Нет, я не знаю\").","\"не\" đọc lướt nhẹ, dính liền vào động từ phía sau: \"не знаю\" đọc liền thành \"nye ZNA-yu\".","\"не\" cũng phủ định được trạng từ, tính từ: \"не очень\" = không lắm, \"не сейчас\" = không phải bây giờ."],"mistakes":[{"wrong":"Я знаю не.","right":"Я не знаю.","why":"\"не\" phải đứng TRƯỚC động từ, không đặt sau như khi nói 'biết không'."},{"wrong":"Не, я не понимаю.","right":"Нет, я не понимаю.","why":"Chữ 'Không' đứng riêng để trả lời phải là \"нет\"; \"не\" chỉ đi kèm một từ khác."}],"compare":"Giống tiếng Việt: \"не\" đứng trước động từ như chữ 'không' (không biết = не знаю). Khác: 'Không.' đứng một mình phải nói \"Нет\", và động từ vẫn chia theo người nói.","tip":"\"не\" là cái lắc đầu nhỏ dán trước động từ; lắc đầu to cả câu thì là \"нет\".","how":["Bắt đầu với động từ говорю (tôi nói), đặt не ngay trước → не говорю, rồi thêm chủ ngữ Я ở đầu và по-русски (tiếng Nga) ở cuối → Я не говорю по-русски.","Đặt не trước понимаю (tôi hiểu) → не понимаю, rồi thêm Я ở đầu và совсем (hoàn toàn) ngay trước не để nhấn mạnh → Я совсем не понимаю.","Đặt не trước знаю (tôi biết) → не знаю, rồi thêm Я ở đầu và tân ngữ дорогу (con đường, đối cách) ở cuối → Я не знаю дорогу."],"dialog":[{"who":"A","t":"Извините, где вокзал?","ph":"iz-vi-NI-te gdye vag-ZAL","vi":"Xin lỗi, nhà ga ở đâu ạ?","hl":[]},{"who":"B","t":"Простите, я не знаю.","ph":"pras-TI-te ya nye ZNA-yu","vi":"Xin lỗi, tôi không biết.","hl":["не"]},{"who":"A","t":"Вы не говорите по-английски?","ph":"vy nye ga-va-RI-te pa-an-GLIY-ski","vi":"Anh/chị không nói tiếng Anh à?","hl":["не"]},{"who":"B","t":"Нет, не говорю. Извините.","ph":"nyet nye ga-va-RYU iz-vi-NI-te","vi":"Không, tôi không nói được. Xin lỗi nhé.","hl":["не"]}],"more":[{"t":"Я не пью.","ph":"ya nye PYU","vi":"Tôi không uống rượu.","hl":["не"],"tokens":["Я","не","пью"]},{"t":"Он не курит.","ph":"on nye KU-rit","vi":"Anh ấy không hút thuốc.","hl":["не"],"tokens":["Он","не","курит"]},{"t":"Это не мой чемодан.","ph":"E-ta nye moy chi-ma-DAN","vi":"Đây không phải vali của tôi.","hl":["не"],"tokens":["Это","не","мой","чемодан"]},{"t":"Мы сегодня не работаем.","ph":"my si-VOD-nya nye ra-BO-ta-im","vi":"Hôm nay chúng tôi không làm việc.","hl":["не"],"tokens":["Мы","сегодня","не","работаем"]},{"t":"Я не очень люблю острое.","ph":"ya nye O-chen lyub-LYU OS-tra-ye","vi":"Tôi không thích đồ cay lắm.","hl":["не"],"tokens":["Я","не","очень","люблю","острое"]},{"t":"Мой телефон почему-то не работает.","ph":"moy ti-li-FON pa-chi-MU-ta nye ra-BO-ta-yet","vi":"Điện thoại của tôi không hiểu sao không chạy.","hl":["не"],"tokens":["Мой","телефон","почему-то","не","работает"]}]},{"id":2,"vi":"có","note":"Tiếng Nga nói 'có' bằng cấu trúc 'у + sở hữu cách + есть' (у меня есть = tôi có, nghĩa đen 'ở tôi có'), vật sở hữu ở chủ cách; phủ định: 'у меня нет' + sở hữu cách.","pivot":{"t":"у меня есть","ph":"u mi-NYA yest"},"branches":[{"steps":[{"t":"билет","ph":"bi-LYET","vi":"vé","hl":[]},{"t":"у меня есть билет","ph":"u mi-NYA yest bi-LYET","vi":"tôi có vé","hl":["у меня есть"]},{"t":"Теперь у меня есть билет.","ph":"ti-PYER u mi-NYA yest bi-LYET","vi":"Giờ tôi có vé rồi.","hl":["у меня есть"],"tokens":["Теперь","у","меня","есть","билет"]}]},{"steps":[{"t":"время","ph":"VRYE-mya","vi":"thời gian","hl":[]},{"t":"у меня есть время","ph":"u mi-NYA yest VRYE-mya","vi":"tôi có thời gian","hl":["у меня есть"]},{"t":"Сегодня у меня есть время.","ph":"si-VOD-nya u mi-NYA yest VRYE-mya","vi":"Hôm nay tôi có thời gian.","hl":["у меня есть"],"tokens":["Сегодня","у","меня","есть","время"]}]},{"steps":[{"t":"вопрос","ph":"va-PROS","vi":"câu hỏi","hl":[]},{"t":"у меня есть вопрос","ph":"u mi-NYA yest va-PROS","vi":"tôi có câu hỏi","hl":["у меня есть"]},{"t":"А у меня есть вопрос.","ph":"a u mi-NYA yest va-PROS","vi":"À, tôi có một câu hỏi.","hl":["у меня есть"],"tokens":["А","у","меня","есть","вопрос"]}]}],"formula":[{"k":"X","t":"(Thời gian)"},{"k":"P","t":"у меня есть"},{"k":"O","t":"Vật sở hữu"}],"points":["\"Tôi có X\" nói là \"у меня есть X\", nghĩa đen 'ở tôi có X'; X giữ nguyên dạng từ điển (chủ cách).","Đổi người có bằng đại từ sau у: у тебя (bạn), у него (anh ấy), у неё (cô ấy), у нас (chúng tôi), у вас (anh/chị).","Hỏi \"Có ... không?\" chỉ cần lên giọng cuối câu: \"У вас есть вода?\".","\"Không có\" là \"у меня нет\" + sở hữu cách: \"У меня нет времени\"."],"mistakes":[{"wrong":"Я есть билет.","right":"У меня есть билет.","why":"Dịch từng chữ 'tôi có' là sai; tiếng Nga nói 'ở tôi có' bằng у меня есть."},{"wrong":"У меня не есть время.","right":"У меня нет времени.","why":"'Không có' dùng нет (không nói не есть) và vật chuyển sang sở hữu cách: время → времени."}],"compare":"Tiếng Việt nói 'tôi có', người có làm chủ ngữ; tiếng Nga nói 'ở tôi có' (у меня есть), vật được sở hữu mới là chủ ngữ của câu.","tip":"Nhớ \"u mi-NYA yest\" như 'ở mình nè, có': у = ở, меня = mình, есть = có.","how":["Lấy danh từ билет (vé), đặt у меня есть phía trước → у меня есть билет, rồi thêm Теперь (giờ thì) ở đầu → Теперь у меня есть билет.","Lấy время (thời gian), đặt у меня есть phía trước → у меня есть время, rồi thêm Сегодня (hôm nay) ở đầu → Сегодня у меня есть время.","Lấy вопрос (câu hỏi), đặt у меня есть phía trước → у меня есть вопрос, rồi thêm А (à) ở đầu để mở lời → А у меня есть вопрос."],"dialog":[{"who":"A","t":"У вас есть свободный номер?","ph":"u vas yest sva-BOD-ny NO-mir","vi":"Ở đây còn phòng trống không ạ?","hl":["У вас есть"]},{"who":"B","t":"Да, есть. У вас есть паспорт?","ph":"da YEST u vas yest PAS-part","vi":"Còn ạ. Anh/chị có hộ chiếu không?","hl":["У вас есть"]},{"who":"A","t":"Да, у меня есть паспорт.","ph":"da u mi-NYA yest PAS-part","vi":"Có, tôi có hộ chiếu.","hl":["у меня есть"]},{"who":"B","t":"Отлично, вот ваш ключ.","ph":"at-LICH-na vot vash KLYUCH","vi":"Tuyệt, chìa khóa của anh/chị đây.","hl":[]}],"more":[{"t":"У меня есть карта.","ph":"u mi-NYA yest KAR-ta","vi":"Tôi có thẻ ngân hàng.","hl":["У меня есть"],"tokens":["У","меня","есть","карта"]},{"t":"У тебя есть ручка?","ph":"u ti-BYA yest RUCH-ka","vi":"Bạn có bút không?","hl":["У тебя есть"],"tokens":["У","тебя","есть","ручка"]},{"t":"У меня есть брат.","ph":"u mi-NYA yest BRAT","vi":"Tôi có một anh trai.","hl":["У меня есть"],"tokens":["У","меня","есть","брат"]},{"t":"У вас есть меню на английском?","ph":"u vas yest mi-NYU na an-GLIY-skam","vi":"Ở đây có thực đơn tiếng Anh không ạ?","hl":["У вас есть"],"tokens":["У","вас","есть","меню","на","английском"]},{"t":"У меня есть идея получше.","ph":"u mi-NYA yest i-DYE-ya pa-LUCH-she","vi":"Tôi có ý này hay hơn.","hl":["У меня есть"],"tokens":["У","меня","есть","идея","получше"]},{"t":"Сегодня вечером у нас есть свободное время.","ph":"si-VOD-nya VYE-chi-ram u nas yest sva-BOD-na-ye VRYE-mya","vi":"Tối nay chúng ta có thời gian rảnh.","hl":["у нас есть"],"tokens":["Сегодня","вечером","у","нас","есть","свободное","время"]}]},{"id":3,"vi":"là","note":"Ở thì hiện tại tiếng Nga lược bỏ động từ 'là' (Я студент = Tôi là sinh viên); 'это' = 'đây là / đó là', dùng để giới thiệu người hoặc chỉ vật.","pivot":{"t":"это","ph":"E-ta"},"branches":[{"steps":[{"t":"друг","ph":"DRUK","vi":"bạn","hl":[]},{"t":"это мой друг","ph":"E-ta moy DRUK","vi":"đây là bạn tôi","hl":["это"]},{"t":"А это мой друг Иван.","ph":"a E-ta moy DRUK i-VAN","vi":"Còn đây là bạn tôi, Ivan.","hl":["это"],"tokens":["А","это","мой","друг","Иван"]}]},{"steps":[{"t":"сумка","ph":"SUM-ka","vi":"cái túi","hl":[]},{"t":"это моя сумка","ph":"E-ta ma-YA SUM-ka","vi":"đây là túi của tôi","hl":["это"]},{"t":"Вот это моя сумка.","ph":"vot E-ta ma-YA SUM-ka","vi":"Đây chính là túi của tôi.","hl":["это"],"tokens":["Вот","это","моя","сумка"]}]},{"steps":[{"t":"площадь","ph":"PLO-shchad","vi":"quảng trường","hl":[]},{"t":"это Красная площадь","ph":"E-ta KRAS-na-ya PLO-shchad","vi":"đây là Quảng trường Đỏ","hl":["это"]},{"t":"А это Красная площадь?","ph":"a E-ta KRAS-na-ya PLO-shchad","vi":"Còn đây là Quảng trường Đỏ à?","hl":["это"],"tokens":["А","это","Красная","площадь"]}]}],"formula":[{"k":"X","t":"(А / Вот)"},{"k":"P","t":"это"},{"k":"O","t":"Người / Vật"}],"points":["Ở thì hiện tại tiếng Nga bỏ hẳn động từ 'là': \"Я студент\" = Tôi là sinh viên.","\"это\" + danh từ = 'đây là / đó là ...': \"Это мой паспорт\".","Hỏi 'Đây là gì?' là \"Что это?\", 'Đây là ai?' là \"Кто это?\".","\"это\" không đổi dạng dù danh từ sau là giống đực, giống cái hay số nhiều: \"Это моя сумка\", \"Это мои друзья\"."],"mistakes":[{"wrong":"Я есть студент.","right":"Я студент.","why":"Thì hiện tại không thêm động từ 'là' (есть); chỉ cần đặt hai từ cạnh nhau."},{"wrong":"Эта мой друг.","right":"Это мой друг.","why":"Giới thiệu 'đây là...' luôn dùng это không đổi; эта là 'cái... này' đi kèm danh từ giống cái."}],"compare":"Tiếng Việt cần chữ 'là' (Đây là bạn tôi), tiếng Nga bỏ 'là' ở hiện tại: Это мой друг = 'Đây bạn tôi'. Giống tiếng Việt ở chỗ это không đổi hình thức.","tip":"\"это\" như ngón tay chỉ: chỉ vào cái gì thì nói \"E-ta\" + tên của nó, chữ 'là' tự hiểu ngầm.","how":["Từ друг (bạn), thêm это мой phía trước → это мой друг, rồi thêm А (còn) ở đầu và tên Иван ở cuối → А это мой друг Иван.","Từ сумка (túi, giống cái) → это моя сумка (моя hợp giống cái), rồi thêm Вот ở đầu để nhấn 'chính là đây' → Вот это моя сумка.","Từ площадь (quảng trường) → это Красная площадь, thêm А ở đầu và lên giọng cuối câu để hỏi → А это Красная площадь?"],"dialog":[{"who":"A","t":"Смотри, это наш отель.","ph":"smat-RI E-ta nash a-TEL","vi":"Nhìn kìa, đó là khách sạn của chúng ta.","hl":["это"]},{"who":"B","t":"А что это рядом?","ph":"a shto E-ta RYA-dam","vi":"Còn cái bên cạnh là gì?","hl":["это"]},{"who":"A","t":"Это ресторан. Там вкусно.","ph":"E-ta ris-ta-RAN tam FKUS-na","vi":"Đó là nhà hàng. Ở đó ngon lắm.","hl":["Это"]},{"who":"B","t":"Отлично, пойдём туда!","ph":"at-LICH-na pa-DYOM tu-DA","vi":"Tuyệt, mình đến đó đi!","hl":[]}],"more":[{"t":"Это мой паспорт.","ph":"E-ta moy PAS-part","vi":"Đây là hộ chiếu của tôi.","hl":["Это"],"tokens":["Это","мой","паспорт"]},{"t":"Это наш гид.","ph":"E-ta nash GIT","vi":"Đây là hướng dẫn viên của chúng tôi.","hl":["Это"],"tokens":["Это","наш","гид"]},{"t":"Это не моё место.","ph":"E-ta nye ma-YO MYES-ta","vi":"Đây không phải chỗ của tôi.","hl":["Это"],"tokens":["Это","не","моё","место"]},{"t":"Это очень красивый город.","ph":"E-ta O-chen kra-SI-vy GO-rat","vi":"Đây là một thành phố rất đẹp.","hl":["Это"],"tokens":["Это","очень","красивый","город"]},{"t":"Мама, это моя подруга Анна.","ph":"MA-ma E-ta ma-YA pad-RU-ga AN-na","vi":"Mẹ ơi, đây là bạn con, Anna.","hl":["это"],"tokens":["Мама,","это","моя","подруга","Анна"]},{"t":"Извините, это ваш багаж или мой?","ph":"iz-vi-NI-te E-ta vash ba-GASH I-li MOY","vi":"Xin lỗi, đây là hành lý của anh/chị hay của tôi?","hl":["это"],"tokens":["Извините,","это","ваш","багаж","или","мой"]}]},{"id":4,"vi":"muốn","note":"'хотеть' chia: я хочу, ты хочешь, мы хотим; theo sau là động từ nguyên mẫu (muốn làm gì) hoặc danh từ đối cách (muốn cái gì). Lịch sự hơn: 'я хотел(а) бы'.","pivot":{"t":"хочу","ph":"kha-CHU"},"branches":[{"steps":[{"t":"кофе","ph":"KO-fe","vi":"cà phê","hl":[]},{"t":"хочу кофе","ph":"kha-CHU KO-fe","vi":"muốn cà phê","hl":["хочу"]},{"t":"Я хочу кофе с молоком.","ph":"ya kha-CHU KO-fe s ma-la-KOM","vi":"Tôi muốn cà phê sữa.","hl":["хочу"],"tokens":["Я","хочу","кофе","с","молоком"]}]},{"steps":[{"t":"спать","ph":"SPAT","vi":"ngủ","hl":[]},{"t":"хочу спать","ph":"kha-CHU SPAT","vi":"muốn ngủ","hl":["хочу"]},{"t":"Я очень хочу спать.","ph":"ya O-chen kha-CHU SPAT","vi":"Tôi buồn ngủ quá.","hl":["хочу"],"tokens":["Я","очень","хочу","спать"]}]},{"steps":[{"t":"купить","ph":"ku-PIT","vi":"mua","hl":[]},{"t":"хочу купить","ph":"kha-CHU ku-PIT","vi":"muốn mua","hl":["хочу"]},{"t":"Я хочу купить сувенир.","ph":"ya kha-CHU ku-PIT su-vi-NIR","vi":"Tôi muốn mua quà lưu niệm.","hl":["хочу"],"tokens":["Я","хочу","купить","сувенир"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"хочу"},{"k":"O","t":"Động từ nguyên mẫu / Danh từ"}],"points":["\"хочу\" = tôi muốn; chia theo người: ты хочешь, он хочет, мы хотим, вы хотите.","Muốn làm gì: хочу + động từ nguyên mẫu (\"хочу спать\"); muốn cái gì: хочу + danh từ đối cách (\"хочу воду\").","\"Хочу спать\" còn nghĩa là buồn ngủ, \"хочу есть\" = đói bụng, \"хочу пить\" = khát nước.","Khi gọi món hay nhờ vả, nói \"я хотел бы\" (nam) / \"я хотела бы\" (nữ) cho lịch sự hơn."],"mistakes":[{"wrong":"Я хочу вода.","right":"Я хочу воду.","why":"Vật muốn có là tân ngữ nên đổi sang đối cách: вода → воду."},{"wrong":"Я хочу пью чай.","right":"Я хочу пить чай.","why":"Sau хочу động từ phải ở dạng nguyên mẫu (пить), không chia."}],"compare":"Giống tiếng Việt: 'muốn' đứng trước việc/vật muốn (хочу кофе = muốn cà phê). Khác: хочу phải chia theo người và danh từ sau nó đổi đuôi đối cách.","tip":"\"kha-CHU\" nghe như 'khá chu': muốn gì thì 'khá chu' đáo nói ra ngay, Хочу кофе!","how":["Bắt đầu với кофе (cà phê), đặt хочу trước → хочу кофе, thêm Я ở đầu và с молоком (với sữa) ở cuối → Я хочу кофе с молоком.","Đặt хочу trước động từ nguyên mẫu спать (ngủ) → хочу спать, thêm Я ở đầu và очень (rất) trước хочу → Я очень хочу спать.","Đặt хочу trước nguyên mẫu купить (mua) → хочу купить, thêm Я ở đầu và tân ngữ сувенир (quà lưu niệm) ở cuối → Я хочу купить сувенир."],"dialog":[{"who":"A","t":"Что ты хочешь на обед?","ph":"shto ty KHO-chish na a-BYET","vi":"Trưa nay bạn muốn ăn gì?","hl":["хочешь"]},{"who":"B","t":"Я хочу суп и салат.","ph":"ya kha-CHU SUP i sa-LAT","vi":"Mình muốn súp và salad.","hl":["хочу"]},{"who":"A","t":"А пить хочешь?","ph":"a PIT KHO-chish","vi":"Thế bạn có muốn uống gì không?","hl":["хочешь"]},{"who":"B","t":"Да, хочу чай с лимоном.","ph":"da kha-CHU CHAY s li-MO-nam","vi":"Có, mình muốn trà chanh.","hl":["хочу"]}],"more":[{"t":"Я хочу пить.","ph":"ya kha-CHU PIT","vi":"Tôi khát nước.","hl":["хочу"],"tokens":["Я","хочу","пить"]},{"t":"Я хочу домой.","ph":"ya kha-CHU da-MOY","vi":"Tôi muốn về nhà.","hl":["хочу"],"tokens":["Я","хочу","домой"]},{"t":"Ты хочешь мороженое?","ph":"ty KHO-chish ma-RO-zhe-na-ye","vi":"Bạn muốn ăn kem không?","hl":["хочешь"],"tokens":["Ты","хочешь","мороженое"]},{"t":"Мы хотим посмотреть город.","ph":"my kha-TIM pa-smat-RYET GO-rat","vi":"Chúng tôi muốn tham quan thành phố.","hl":["хотим"],"tokens":["Мы","хотим","посмотреть","город"]},{"t":"Я хочу поменять деньги.","ph":"ya kha-CHU pa-mi-NYAT DYEN-gi","vi":"Tôi muốn đổi tiền.","hl":["хочу"],"tokens":["Я","хочу","поменять","деньги"]},{"t":"Я хотела бы заказать столик на двоих.","ph":"ya kha-TYE-la by za-ka-ZAT STO-lik na dva-IKH","vi":"Tôi muốn đặt bàn cho hai người.","hl":["хотела бы"],"tokens":["Я","хотела","бы","заказать","столик","на","двоих"]}]},{"id":5,"vi":"thích","note":"'нравится' dùng với người thích ở tặng cách (мне нравится = tôi thích), vật được thích làm chủ ngữ (số nhiều: нравятся); 'люблю' (rất thích/yêu) + đối cách hoặc động từ nguyên mẫu.","pivot":{"t":"нравится","ph":"NRA-vit-sya"},"branches":[{"steps":[{"t":"Москва","ph":"mask-VA","vi":"Moscow","hl":[]},{"t":"нравится Москва","ph":"NRA-vit-sya mask-VA","vi":"thích Moscow","hl":["нравится"]},{"t":"Мне очень нравится Москва.","ph":"mnye O-chen NRA-vit-sya mask-VA","vi":"Tôi rất thích Moscow.","hl":["нравится"],"tokens":["Мне","очень","нравится","Москва"]}]},{"steps":[{"t":"борщ","ph":"BORSHCH","vi":"súp borsch","hl":[]},{"t":"нравится борщ","ph":"NRA-vit-sya BORSHCH","vi":"thích súp borsch","hl":["нравится"]},{"t":"Тебе нравится борщ?","ph":"ti-BYE NRA-vit-sya BORSHCH","vi":"Bạn có thích súp borsch không?","hl":["нравится"],"tokens":["Тебе","нравится","борщ"]}]},{"steps":[{"t":"гулять","ph":"gu-LYAT","vi":"đi dạo","hl":[]},{"t":"люблю гулять","ph":"lyub-LYU gu-LYAT","vi":"thích đi dạo","hl":["люблю"]},{"t":"Я люблю гулять по городу.","ph":"ya lyub-LYU gu-LYAT pa GO-ra-du","vi":"Tôi thích đi dạo quanh thành phố.","hl":["люблю"],"tokens":["Я","люблю","гулять","по","городу"]}]}],"formula":[{"k":"S","t":"Người thích (tặng cách)"},{"k":"P","t":"нравится"},{"k":"O","t":"Vật được thích"}],"points":["\"Tôi thích X\" = \"Мне нравится X\": người thích ở tặng cách (мне, тебе, ему, ей, нам, вам), X là chủ ngữ.","X số nhiều thì đổi thành \"нравятся\": \"Мне нравятся эти туфли\".","\"люблю\" + đối cách hoặc nguyên mẫu = rất thích, yêu, dùng cho sở thích lâu dài: \"Я люблю чай\".","\"нравится\" hợp với ấn tượng cụ thể vừa gặp: món đang ăn, thành phố đang thăm, người mới quen."],"mistakes":[{"wrong":"Я нравится Москва.","right":"Мне нравится Москва.","why":"Người thích phải ở tặng cách: я → мне."},{"wrong":"Мне нравится эти цветы.","right":"Мне нравятся эти цветы.","why":"Vật được thích số nhiều thì động từ cũng số nhiều: нравятся."}],"compare":"Tiếng Việt: 'Tôi thích Moscow', tôi là chủ ngữ. Tiếng Nga đảo vai: 'Мне нравится Москва' = 'Moscow làm tôi thích', Moscow mới là chủ ngữ.","tip":"\"mnye NRA-vit-sya\" = 'với tôi thì dễ thương': vật dễ thương là chủ ngữ, tôi chỉ là người nhận cảm giác.","how":["Đặt нравится trước Москва → нравится Москва, rồi thêm Мне (tặng cách của я) và очень (rất) ở đầu → Мне очень нравится Москва.","Đặt нравится trước борщ (súp borsch) → нравится борщ, thêm Тебе (với bạn) ở đầu và lên giọng để hỏi → Тебе нравится борщ?","Với hoạt động yêu thích thì dùng люблю + nguyên mẫu: люблю гулять (thích đi dạo), thêm Я ở đầu và по городу (quanh thành phố) ở cuối → Я люблю гулять по городу."],"dialog":[{"who":"A","t":"Тебе нравится Петербург?","ph":"ti-BYE NRA-vit-sya pi-tir-BURK","vi":"Bạn có thích Petersburg không?","hl":["нравится"]},{"who":"B","t":"Очень нравится! Здесь так красиво.","ph":"O-chen NRA-vit-sya zdyes tak kra-SI-va","vi":"Thích lắm! Ở đây đẹp quá.","hl":["нравится"]},{"who":"A","t":"А мне больше нравится Москва.","ph":"a mnye BOL-she NRA-vit-sya mask-VA","vi":"Còn tôi thì thích Moscow hơn.","hl":["нравится"]},{"who":"B","t":"Я тоже люблю Москву.","ph":"ya TO-zhe lyub-LYU mask-VU","vi":"Tôi cũng thích Moscow.","hl":["люблю"]}],"more":[{"t":"Мне нравится этот отель.","ph":"mnye NRA-vit-sya E-tat a-TEL","vi":"Tôi thích khách sạn này.","hl":["нравится"],"tokens":["Мне","нравится","этот","отель"]},{"t":"Вам нравится эта музыка?","ph":"vam NRA-vit-sya E-ta MU-zy-ka","vi":"Anh/chị có thích bản nhạc này không?","hl":["нравится"],"tokens":["Вам","нравится","эта","музыка"]},{"t":"Я люблю русский чай.","ph":"ya lyub-LYU RUS-kiy CHAY","vi":"Tôi thích trà Nga.","hl":["люблю"],"tokens":["Я","люблю","русский","чай"]},{"t":"Нам очень нравится ваш город.","ph":"nam O-chen NRA-vit-sya vash GO-rat","vi":"Chúng tôi rất thích thành phố của các bạn.","hl":["нравится"],"tokens":["Нам","очень","нравится","ваш","город"]},{"t":"Мне нравятся эти красные туфли.","ph":"mnye NRA-vyat-sya E-ti KRAS-ny-ye TUF-li","vi":"Tôi thích đôi giày đỏ này.","hl":["нравятся"],"tokens":["Мне","нравятся","эти","красные","туфли"]},{"t":"Моей маме не нравится холодная погода.","ph":"ma-YEY MA-me nye NRA-vit-sya kha-LOD-na-ya pa-GO-da","vi":"Mẹ tôi không thích thời tiết lạnh.","hl":["нравится"],"tokens":["Моей","маме","не","нравится","холодная","погода"]}]},{"id":6,"vi":"cần","note":"Người cần ở tặng cách (мне, тебе) + 'нужно' + động từ nguyên mẫu; khi cần một vật thì 'нужен / нужна / нужно / нужны' hợp giống và số với vật đó (нужен врач, нужна помощь).","pivot":{"t":"нужно","ph":"NUZH-na"},"branches":[{"steps":[{"t":"помощь","ph":"PO-mashch","vi":"sự giúp đỡ","hl":[]},{"t":"нужна помощь","ph":"nuzh-NA PO-mashch","vi":"cần giúp đỡ","hl":["нужна"]},{"t":"Мне нужна помощь.","ph":"mnye nuzh-NA PO-mashch","vi":"Tôi cần giúp đỡ.","hl":["нужна"],"tokens":["Мне","нужна","помощь"]}]},{"steps":[{"t":"врач","ph":"VRACH","vi":"bác sĩ","hl":[]},{"t":"нужен врач","ph":"NU-zhen VRACH","vi":"cần bác sĩ","hl":["нужен"]},{"t":"Мне срочно нужен врач.","ph":"mnye SROCH-na NU-zhen VRACH","vi":"Tôi cần bác sĩ gấp.","hl":["нужен"],"tokens":["Мне","срочно","нужен","врач"]}]},{"steps":[{"t":"купить","ph":"ku-PIT","vi":"mua","hl":[]},{"t":"нужно купить","ph":"NUZH-na ku-PIT","vi":"cần mua","hl":["нужно"]},{"t":"Мне нужно купить воду.","ph":"mnye NUZH-na ku-PIT VO-du","vi":"Tôi cần mua nước.","hl":["нужно"],"tokens":["Мне","нужно","купить","воду"]}]}],"formula":[{"k":"S","t":"Người cần (tặng cách)"},{"k":"P","t":"нужно / нужен / нужна"},{"k":"O","t":"Động từ nguyên mẫu / Vật"}],"points":["\"Tôi cần (phải)\" = \"Мне нужно\" + động từ nguyên mẫu: \"Мне нужно идти\" (Tôi phải đi).","Cần một vật thì đổi đuôi theo vật: нужен (giống đực: врач), нужна (giống cái: помощь), нужно (giống trung: такси), нужны (số nhiều: деньги).","Người cần ở tặng cách: мне, тебе, ему, ей, нам, вам.","\"Не нужно\" = không cần: \"Спасибо, не нужно\"."],"mistakes":[{"wrong":"Я нужно купить воду.","right":"Мне нужно купить воду.","why":"Người cần phải ở tặng cách мне, không dùng я."},{"wrong":"Мне нужно врач.","right":"Мне нужен врач.","why":"врач là giống đực nên dùng нужен; нужно chỉ đi với động từ hoặc danh từ giống trung."}],"compare":"Tiếng Việt chỉ có một chữ 'cần'; tiếng Nga 'cần' đổi đuôi theo giống của vật cần, và người cần đứng ở tặng cách (мне = 'với tôi').","tip":"Đuôi của нуж- 'bắt chước' vật cần: врач (đực) → нужен, помощь (cái) → нужна, động từ → нужно.","how":["помощь (sự giúp đỡ) là giống cái nên dùng нужна → нужна помощь, rồi thêm Мне (tặng cách của я) ở đầu → Мне нужна помощь.","врач (bác sĩ) là giống đực nên dùng нужен → нужен врач, thêm Мне ở đầu và срочно (gấp) trước нужен → Мне срочно нужен врач.","Với động từ nguyên mẫu купить (mua) dùng нужно → нужно купить, thêm Мне ở đầu và воду (nước, đối cách) ở cuối → Мне нужно купить воду."],"dialog":[{"who":"A","t":"Мне нужно такси до аэропорта.","ph":"mnye NUZH-na tak-SI da a-e-ra-POR-ta","vi":"Tôi cần taxi ra sân bay.","hl":["нужно"]},{"who":"B","t":"Хорошо. Когда вам нужно выехать?","ph":"kha-ra-SHO kag-DA vam NUZH-na VY-ye-khat","vi":"Vâng. Khi nào anh/chị cần đi ạ?","hl":["нужно"]},{"who":"A","t":"Через час. Мне нужно быть там в шесть.","ph":"CHE-ris CHAS mnye NUZH-na byt tam f SHEST","vi":"Một tiếng nữa. Tôi cần có mặt ở đó lúc sáu giờ.","hl":["нужно"]},{"who":"B","t":"Понял, машина будет в пять.","ph":"PO-nyal ma-SHI-na BU-dit f PYAT","vi":"Rõ rồi, xe sẽ đến lúc năm giờ.","hl":[]}],"more":[{"t":"Мне нужна карта.","ph":"mnye nuzh-NA KAR-ta","vi":"Tôi cần một tấm bản đồ.","hl":["нужна"],"tokens":["Мне","нужна","карта"]},{"t":"Тебе нужен зонт?","ph":"ti-BYE NU-zhen ZONT","vi":"Bạn có cần ô không?","hl":["нужен"],"tokens":["Тебе","нужен","зонт"]},{"t":"Спасибо, пакет не нужен.","ph":"spa-SI-ba pa-KYET nye NU-zhen","vi":"Cảm ơn, không cần túi đâu.","hl":["нужен"],"tokens":["Спасибо,","пакет","не","нужен"]},{"t":"Нам нужны два билета.","ph":"nam nuzh-NY dva bi-LYE-ta","vi":"Chúng tôi cần hai vé.","hl":["нужны"],"tokens":["Нам","нужны","два","билета"]},{"t":"Мне нужно позвонить домой.","ph":"mnye NUZH-na pa-zva-NIT da-MOY","vi":"Tôi cần gọi điện về nhà.","hl":["нужно"],"tokens":["Мне","нужно","позвонить","домой"]},{"t":"Завтра нам нужно встать очень рано.","ph":"ZAF-tra nam NUZH-na FSTAT O-chen RA-na","vi":"Mai chúng ta cần dậy rất sớm.","hl":["нужно"],"tokens":["Завтра","нам","нужно","встать","очень","рано"]}]},{"id":7,"vi":"có thể","note":"'можно' (không cần chủ ngữ) + nguyên mẫu = được phép/có thể làm gì, hay dùng để xin phép; 'мочь' (я могу, вы можете) = có khả năng làm gì. Phủ định của 'можно' là 'нельзя' (không được).","pivot":{"t":"можно","ph":"MOZH-na"},"branches":[{"steps":[{"t":"курить","ph":"ku-RIT","vi":"hút thuốc","hl":[]},{"t":"можно курить","ph":"MOZH-na ku-RIT","vi":"được hút thuốc","hl":["можно"]},{"t":"Здесь можно курить?","ph":"zdyes MOZH-na ku-RIT","vi":"Ở đây có được hút thuốc không?","hl":["можно"],"tokens":["Здесь","можно","курить"]}]},{"steps":[{"t":"помочь","ph":"pa-MOCH","vi":"giúp","hl":[]},{"t":"могу помочь","ph":"ma-GU pa-MOCH","vi":"có thể giúp","hl":["могу"]},{"t":"Чем я могу помочь?","ph":"chem ya ma-GU pa-MOCH","vi":"Tôi có thể giúp gì được ạ?","hl":["могу"],"tokens":["Чем","я","могу","помочь"]}]},{"steps":[{"t":"заплатить","ph":"za-pla-TIT","vi":"trả tiền","hl":[]},{"t":"можно заплатить","ph":"MOZH-na za-pla-TIT","vi":"có thể trả tiền","hl":["можно"]},{"t":"Тут можно заплатить картой?","ph":"tut MOZH-na za-pla-TIT KAR-tay","vi":"Ở đây trả bằng thẻ được không?","hl":["можно"],"tokens":["Тут","можно","заплатить","картой"]}]}],"formula":[{"k":"X","t":"(Nơi chốn)"},{"k":"P","t":"можно"},{"k":"V","t":"Động từ nguyên mẫu"}],"points":["\"можно\" + động từ nguyên mẫu = được phép làm gì, không cần chủ ngữ: \"Здесь можно курить?\".","Xin vật gì lịch sự chỉ cần \"Можно + danh từ?\": \"Можно меню?\", hoặc chỉ một chữ \"Можно?\" để xin phép.","Nói về khả năng của một người thì dùng мочь chia theo ngôi: я могу, ты можешь, вы можете + nguyên mẫu.","Không được phép là \"нельзя\": \"Здесь нельзя курить\"."],"mistakes":[{"wrong":"Я можно помочь.","right":"Я могу помочь.","why":"Có chủ ngữ cụ thể thì dùng động từ мочь chia theo ngôi (могу), không dùng можно."},{"wrong":"Здесь не можно фотографировать.","right":"Здесь нельзя фотографировать.","why":"Phủ định của можно là нельзя, không nói 'не можно'."}],"compare":"Giống 'được/có thể' của tiếng Việt đặt trước động từ; nhưng можно không cần chủ ngữ (Можно войти? = Vào được không?) và phủ định lại là một từ khác: нельзя.","tip":"\"MOZH-na?\" kèm nụ cười là chìa khóa vạn năng: chỉ vào thứ gì rồi hỏi \"Можно?\" là xin phép xong.","how":["Đặt можно trước nguyên mẫu курить (hút thuốc) → можно курить, thêm Здесь (ở đây) ở đầu và lên giọng để hỏi → Здесь можно курить?","Nói khả năng của người thì dùng могу (tôi có thể) + помочь (giúp) → могу помочь, rồi thêm Чем я (bằng gì tôi) ở đầu → Чем я могу помочь?","Đặt можно trước заплатить (trả tiền) → можно заплатить, thêm Тут (ở đây) ở đầu và картой (bằng thẻ) ở cuối → Тут можно заплатить картой?"],"dialog":[{"who":"A","t":"Извините, можно войти?","ph":"iz-vi-NI-te MOZH-na vay-TI","vi":"Xin lỗi, tôi vào được không?","hl":["можно"]},{"who":"B","t":"Да, конечно. Проходите.","ph":"da ka-NYESH-na pra-kha-DI-te","vi":"Vâng, tất nhiên. Mời vào.","hl":[]},{"who":"A","t":"А здесь можно фотографировать?","ph":"a zdyes MOZH-na fa-ta-gra-fi-RO-vat","vi":"Ở đây có được chụp ảnh không?","hl":["можно"]},{"who":"B","t":"Нет, здесь нельзя. Но в парке можно.","ph":"nyet zdyes nil-ZYA no f PAR-ke MOZH-na","vi":"Không, ở đây không được. Nhưng trong công viên thì được.","hl":["можно"]}],"more":[{"t":"Можно сесть здесь?","ph":"MOZH-na SYEST zdyes","vi":"Tôi ngồi đây được không?","hl":["Можно"],"tokens":["Можно","сесть","здесь"]},{"t":"Можно меню, пожалуйста?","ph":"MOZH-na mi-NYU pa-ZHA-lus-ta","vi":"Cho tôi xin thực đơn được không?","hl":["Можно"],"tokens":["Можно","меню,","пожалуйста"]},{"t":"Можно это попробовать?","ph":"MOZH-na E-ta pa-PRO-ba-vat","vi":"Tôi thử cái này được không?","hl":["Можно"],"tokens":["Можно","это","попробовать"]},{"t":"Ты можешь подождать минуту?","ph":"ty MO-zhesh pa-dazh-DAT mi-NU-tu","vi":"Bạn đợi một phút được không?","hl":["можешь"],"tokens":["Ты","можешь","подождать","минуту"]},{"t":"Где можно купить сим-карту?","ph":"gdye MOZH-na ku-PIT sim-KAR-tu","vi":"Có thể mua sim ở đâu?","hl":["можно"],"tokens":["Где","можно","купить","сим-карту"]},{"t":"Вы можете забронировать нам номер на завтра?","ph":"vy MO-zhe-te za-bra-NI-ra-vat nam NO-mir na ZAF-tra","vi":"Anh/chị đặt giúp chúng tôi một phòng cho ngày mai được không?","hl":["можете"],"tokens":["Вы","можете","забронировать","нам","номер","на","завтра"]}]},{"id":8,"vi":"đi","note":"'идти' (я иду) = đi bộ, 'ехать' (я еду) = đi bằng xe; nơi đến dùng 'в/на' + đối cách (в музей), phương tiện dùng 'на' + giới cách (на метро); 'пойдём' = mình đi nào.","pivot":{"t":"идти","ph":"it-TI"},"branches":[{"steps":[{"t":"домой","ph":"da-MOY","vi":"về nhà","hl":[]},{"t":"иду домой","ph":"i-DU da-MOY","vi":"đi về nhà","hl":["иду"]},{"t":"Я иду домой.","ph":"ya i-DU da-MOY","vi":"Tôi đang đi về nhà.","hl":["иду"],"tokens":["Я","иду","домой"]}]},{"steps":[{"t":"метро","ph":"mit-RO","vi":"tàu điện ngầm","hl":[]},{"t":"еду на метро","ph":"YE-du na mit-RO","vi":"đi bằng tàu điện ngầm","hl":["еду"]},{"t":"Я еду на метро.","ph":"ya YE-du na mit-RO","vi":"Tôi đi bằng tàu điện ngầm.","hl":["еду"],"tokens":["Я","еду","на","метро"]}]},{"steps":[{"t":"музей","ph":"mu-ZYEY","vi":"bảo tàng","hl":[]},{"t":"пойдём в музей","ph":"pa-DYOM v mu-ZYEY","vi":"đi bảo tàng nào","hl":["пойдём"]},{"t":"Завтра пойдём в музей.","ph":"ZAF-tra pa-DYOM v mu-ZYEY","vi":"Mai chúng ta đi bảo tàng nhé.","hl":["пойдём"],"tokens":["Завтра","пойдём","в","музей"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"иду / еду"},{"k":"O","t":"Nơi đến (в/на + đối cách)"}],"points":["\"идти\" = đi bộ: я иду, ты идёшь, мы идём; \"ехать\" = đi bằng xe: я еду, ты едешь, мы едем.","Nơi đến dùng в/на + đối cách: в музей, в банк, на вокзал; 'về nhà' là домой, không cần giới từ.","Phương tiện dùng на + giới cách: на метро, на автобусе, на такси.","\"Пойдём!\" = Mình đi nào!, dùng để rủ rê."],"mistakes":[{"wrong":"Я иду на автобусе.","right":"Я еду на автобусе.","why":"Đi bằng xe cộ phải dùng ехать (еду); идти chỉ dùng khi đi bộ."},{"wrong":"Я иду в дом.","right":"Я иду домой.","why":"'Về nhà' nói gọn là домой; в дом là 'đi vào bên trong một ngôi nhà'."}],"compare":"Tiếng Việt chỉ có một chữ 'đi' cho mọi cách đi, tiếng Nga tách hẳn: đi bộ là идти, đi xe là ехать. Trật tự 'tôi đi bảo tàng' thì giống: Я иду в музей.","tip":"Chân bước \"i-DU\" (đi bộ), bánh xe lăn \"YE-du\" (đi xe): có bánh xe thì có chữ 'e'.","how":["Từ домой (về nhà), đặt иду (tôi đi bộ) trước → иду домой, rồi thêm Я ở đầu → Я иду домой.","Từ метро, vì đi bằng phương tiện nên dùng еду на (đi bằng) → еду на метро, thêm Я ở đầu → Я еду на метро.","Từ музей (bảo tàng), rủ đi thì dùng пойдём в (mình đi đến) → пойдём в музей, thêm Завтра (ngày mai) ở đầu → Завтра пойдём в музей."],"dialog":[{"who":"A","t":"Ты куда идёшь?","ph":"ty ku-DA i-DYOSH","vi":"Bạn đi đâu đấy?","hl":["идёшь"]},{"who":"B","t":"Иду в магазин. А ты?","ph":"i-DU v ma-ga-ZIN a TY","vi":"Mình đi ra cửa hàng. Còn bạn?","hl":["Иду"]},{"who":"A","t":"Я еду на работу на автобусе.","ph":"ya YE-du na ra-BO-tu na af-TO-bu-se","vi":"Mình đi xe buýt đến chỗ làm.","hl":["еду"]},{"who":"B","t":"Хорошо, увидимся вечером!","ph":"kha-ra-SHO u-VI-dim-sya VYE-chi-ram","vi":"Được, tối gặp nhé!","hl":[]}],"more":[{"t":"Мы идём в парк.","ph":"my i-DYOM f PARK","vi":"Chúng tôi đang đi ra công viên.","hl":["идём"],"tokens":["Мы","идём","в","парк"]},{"t":"Я еду на вокзал.","ph":"ya YE-du na vag-ZAL","vi":"Tôi đang đi ra ga tàu.","hl":["еду"],"tokens":["Я","еду","на","вокзал"]},{"t":"Пойдём в кафе!","ph":"pa-DYOM f ka-FE","vi":"Đi cà phê nào!","hl":["Пойдём"],"tokens":["Пойдём","в","кафе"]},{"t":"Ты едешь на такси?","ph":"ty YE-dish na tak-SI","vi":"Bạn đi taxi à?","hl":["едешь"],"tokens":["Ты","едешь","на","такси"]},{"t":"Сейчас я иду в банк.","ph":"si-CHAS ya i-DU v BANK","vi":"Bây giờ tôi đi ngân hàng.","hl":["иду"],"tokens":["Сейчас","я","иду","в","банк"]},{"t":"Завтра мы едем в Петербург на поезде.","ph":"ZAF-tra my YE-dim f pi-tir-BURK na PO-yez-de","vi":"Mai chúng tôi đi tàu hỏa đến Petersburg.","hl":["едем"],"tokens":["Завтра","мы","едем","в","Петербург","на","поезде"]}]},{"id":9,"vi":"ở đâu","note":"'где' hỏi vị trí, không cần động từ 'là/ở' (Где метро? = Tàu điện ngầm ở đâu?); hỏi đi đâu dùng 'куда', từ đâu đến dùng 'откуда'.","pivot":{"t":"где","ph":"gdye"},"branches":[{"steps":[{"t":"метро","ph":"mit-RO","vi":"tàu điện ngầm","hl":[]},{"t":"где метро","ph":"gdye mit-RO","vi":"tàu điện ngầm ở đâu","hl":["где"]},{"t":"А где метро?","ph":"a gdye mit-RO","vi":"Thế ga tàu điện ngầm ở đâu?","hl":["где"],"tokens":["А","где","метро"]}]},{"steps":[{"t":"ты","ph":"ty","vi":"bạn","hl":[]},{"t":"ты где","ph":"ty GDYE","vi":"bạn ở đâu","hl":["где"]},{"t":"А ты где сейчас?","ph":"a ty gdye si-CHAS","vi":"Thế bây giờ bạn đang ở đâu?","hl":["где"],"tokens":["А","ты","где","сейчас"]}]},{"steps":[{"t":"живёте","ph":"zhi-VYO-te","vi":"(anh/chị) sống","hl":[]},{"t":"где живёте","ph":"gdye zhi-VYO-te","vi":"sống ở đâu","hl":["где"]},{"t":"Вы где живёте?","ph":"vy gdye zhi-VYO-te","vi":"Anh/chị sống ở đâu?","hl":["где"],"tokens":["Вы","где","живёте"]}]}],"formula":[{"k":"P","t":"где"},{"k":"S","t":"Người / Vật"},{"k":"V","t":"(Động từ)"}],"points":["\"где\" = ở đâu, hỏi vị trí; không cần động từ 'ở/là': \"Где туалет?\".","Trong văn nói, где có thể đứng sau chủ ngữ: \"Ты где?\", \"Вы где живёте?\".","Hỏi đi đâu dùng \"куда\" (Куда ты идёшь?), hỏi từ đâu dùng \"откуда\" (Откуда вы?).","Trả lời vị trí dùng в/на + giới cách: \"в центре\", \"на вокзале\"."],"mistakes":[{"wrong":"Где ты идёшь?","right":"Куда ты идёшь?","why":"Hỏi hướng đi (đi đâu) phải dùng куда; где chỉ hỏi vị trí đứng yên."},{"wrong":"Туалет есть где?","right":"Где туалет?","why":"Dịch từng chữ 'nhà vệ sinh ở đâu' là sai; tiếng Nga đặt где lên trước và không cần động từ."}],"compare":"Tiếng Việt đặt 'ở đâu' cuối câu (Nhà ga ở đâu?), tiếng Nga thường đặt где đầu câu (Где вокзал?) và bỏ luôn chữ 'ở'.","tip":"Ba anh em hỏi chỗ: где (ở đâu), куда (đi đâu), откуда (từ đâu); đứng yên một chỗ thì gọi где.","how":["Đặt где trước метро → где метро (tàu điện ngầm ở đâu), rồi thêm А (thế) ở đầu cho tự nhiên → А где метро?","Bắt đầu từ ты (bạn), thêm где phía sau theo kiểu văn nói → ты где, rồi thêm А ở đầu và сейчас (bây giờ) ở cuối → А ты где сейчас?","Đặt где trước động từ живёте (anh/chị sống) → где живёте, rồi thêm chủ ngữ Вы ở đầu → Вы где живёте?"],"dialog":[{"who":"A","t":"Скажите, где здесь аптека?","ph":"SKA-zhi-te gdye zdyes ap-TYE-ka","vi":"Cho hỏi, hiệu thuốc ở đâu ạ?","hl":["где"]},{"who":"B","t":"Аптека? Вон там, за углом.","ph":"ap-TYE-ka von TAM za ug-LOM","vi":"Hiệu thuốc à? Ở đằng kia, chỗ góc đường.","hl":[]},{"who":"A","t":"А где ближайший банкомат?","ph":"a gdye bli-ZHAY-shiy ban-ka-MAT","vi":"Còn cây ATM gần nhất ở đâu ạ?","hl":["где"]},{"who":"B","t":"Тоже там, рядом с аптекой.","ph":"TO-zhe tam RYA-dam s ap-TYE-kay","vi":"Cũng ở đó, cạnh hiệu thuốc.","hl":[]}],"more":[{"t":"Где здесь туалет?","ph":"gdye zdyes tu-a-LYET","vi":"Nhà vệ sinh ở đâu ạ?","hl":["Где"],"tokens":["Где","здесь","туалет"]},{"t":"Где моя сумка?","ph":"gdye ma-YA SUM-ka","vi":"Túi của tôi đâu rồi?","hl":["Где"],"tokens":["Где","моя","сумка"]},{"t":"Где остановка автобуса?","ph":"gdye as-ta-NOF-ka af-TO-bu-sa","vi":"Trạm xe buýt ở đâu?","hl":["Где"],"tokens":["Где","остановка","автобуса"]},{"t":"Мама, где мой телефон?","ph":"MA-ma gdye moy ti-li-FON","vi":"Mẹ ơi, điện thoại của con đâu?","hl":["где"],"tokens":["Мама,","где","мой","телефон"]},{"t":"Где можно поменять деньги?","ph":"gdye MOZH-na pa-mi-NYAT DYEN-gi","vi":"Đổi tiền ở đâu được?","hl":["Где"],"tokens":["Где","можно","поменять","деньги"]},{"t":"Вы не знаете, где находится Эрмитаж?","ph":"vy nye ZNA-ye-te gdye na-KHO-dit-sya er-mi-TASH","vi":"Anh/chị có biết bảo tàng Hermitage ở đâu không?","hl":["где"],"tokens":["Вы","не","знаете,","где","находится","Эрмитаж"]}]},{"id":10,"vi":"bao nhiêu","note":"'сколько' + sở hữu cách (сколько времени, сколько лет); hỏi giá: 'Сколько стоит...?' (với vật số nhiều: 'сколько стоят').","pivot":{"t":"сколько","ph":"SKOL-ka"},"branches":[{"steps":[{"t":"стоит","ph":"STO-it","vi":"có giá","hl":[]},{"t":"сколько стоит","ph":"SKOL-ka STO-it","vi":"giá bao nhiêu","hl":["сколько"]},{"t":"А сколько стоит билет?","ph":"a SKOL-ka STO-it bi-LYET","vi":"Vé giá bao nhiêu vậy?","hl":["сколько"],"tokens":["А","сколько","стоит","билет"]}]},{"steps":[{"t":"времени","ph":"VRYE-mi-ni","vi":"thời gian (giờ)","hl":[]},{"t":"сколько времени","ph":"SKOL-ka VRYE-mi-ni","vi":"mấy giờ","hl":["сколько"]},{"t":"Сейчас сколько времени?","ph":"si-CHAS SKOL-ka VRYE-mi-ni","vi":"Bây giờ là mấy giờ?","hl":["сколько"],"tokens":["Сейчас","сколько","времени"]}]},{"steps":[{"t":"лет","ph":"LYET","vi":"năm (tuổi)","hl":[]},{"t":"сколько лет","ph":"SKOL-ka LYET","vi":"bao nhiêu tuổi","hl":["сколько"]},{"t":"Тебе сколько лет?","ph":"ti-BYE SKOL-ka LYET","vi":"Bạn bao nhiêu tuổi?","hl":["сколько"],"tokens":["Тебе","сколько","лет"]}]}],"formula":[{"k":"P","t":"сколько"},{"k":"V","t":"(стоит)"},{"k":"O","t":"Danh từ (sở hữu cách)"}],"points":["\"сколько\" = bao nhiêu, danh từ theo sau ở sở hữu cách: сколько времени, сколько лет, сколько человек.","Hỏi giá: \"Сколько стоит + vật số ít?\", vật số nhiều dùng \"Сколько стоят...?\".","Hỏi giờ: \"Сколько времени?\" hoặc \"Который час?\".","Hỏi tuổi: người ở tặng cách + сколько лет: \"Вам сколько лет?\" hoặc \"Сколько вам лет?\"."],"mistakes":[{"wrong":"Сколько стоит эти яблоки?","right":"Сколько стоят эти яблоки?","why":"Vật số nhiều thì động từ cũng số nhiều: стоят."},{"wrong":"Ты сколько годы?","right":"Тебе сколько лет?","why":"Hỏi tuổi dùng tặng cách тебе và từ лет (sở hữu cách số nhiều của год)."}],"compare":"Tiếng Việt đặt 'bao nhiêu' cuối (Vé giá bao nhiêu?), tiếng Nga thường đặt сколько lên đầu (Сколько стоит билет?) và danh từ sau nó phải đổi đuôi.","tip":"\"SKOL-ka STO-it?\" là câu thần chú đi chợ: chỉ tay vào món hàng rồi đọc là hỏi được giá.","how":["Đặt сколько trước động từ стоит (có giá) → сколько стоит, thêm А ở đầu và билет (vé) ở cuối → А сколько стоит билет?","Đặt сколько trước времени (sở hữu cách của время) → сколько времени (mấy giờ), rồi thêm Сейчас (bây giờ) ở đầu → Сейчас сколько времени?","Đặt сколько trước лет (năm, sở hữu cách số nhiều) → сколько лет, thêm Тебе (với bạn, tặng cách) ở đầu → Тебе сколько лет?"],"dialog":[{"who":"A","t":"Сколько стоит эта матрёшка?","ph":"SKOL-ka STO-it E-ta mat-RYOSH-ka","vi":"Con búp bê matryoshka này giá bao nhiêu?","hl":["Сколько"]},{"who":"B","t":"Тысяча рублей.","ph":"TY-sya-cha rub-LYEY","vi":"Một nghìn rúp.","hl":[]},{"who":"A","t":"А сколько стоят эти две?","ph":"a SKOL-ka STO-yat E-ti DVYE","vi":"Còn hai con này bao nhiêu?","hl":["сколько"]},{"who":"B","t":"Полторы тысячи за обе.","ph":"pal-ta-RY TY-sya-chi za O-be","vi":"Một nghìn rưỡi cho cả hai.","hl":[]}],"more":[{"t":"Сколько это стоит?","ph":"SKOL-ka E-ta STO-it","vi":"Cái này giá bao nhiêu?","hl":["Сколько"],"tokens":["Сколько","это","стоит"]},{"t":"Сколько у вас детей?","ph":"SKOL-ka u vas di-TYEY","vi":"Anh/chị có mấy con?","hl":["Сколько"],"tokens":["Сколько","у","вас","детей"]},{"t":"Сколько стоят билеты в театр?","ph":"SKOL-ka STO-yat bi-LYE-ty f ti-ATR","vi":"Vé vào nhà hát giá bao nhiêu?","hl":["Сколько"],"tokens":["Сколько","стоят","билеты","в","театр"]},{"t":"Сколько человек в вашей группе?","ph":"SKOL-ka chi-la-VYEK v VA-shey GRU-pe","vi":"Nhóm của anh/chị có bao nhiêu người?","hl":["Сколько"],"tokens":["Сколько","человек","в","вашей","группе"]},{"t":"Сколько времени идти до центра?","ph":"SKOL-ka VRYE-mi-ni it-TI da TSENT-ra","vi":"Đi bộ đến trung tâm mất bao lâu?","hl":["Сколько"],"tokens":["Сколько","времени","идти","до","центра"]},{"t":"Скажите, сколько стоит номер на одну ночь?","ph":"SKA-zhi-te SKOL-ka STO-it NO-mir na ad-NU NOCH","vi":"Cho hỏi, phòng một đêm giá bao nhiêu?","hl":["сколько"],"tokens":["Скажите,","сколько","стоит","номер","на","одну","ночь"]}]},{"id":11,"vi":"cái gì","note":"'что' (đọc 'shto') = cái gì, đứng đầu câu hỏi hoặc sau chủ ngữ trong văn nói; 'что это?' = đây là gì, 'что делать?' = làm gì.","pivot":{"t":"что","ph":"shto"},"branches":[{"steps":[{"t":"это","ph":"E-ta","vi":"cái này","hl":[]},{"t":"что это","ph":"shto E-ta","vi":"cái này là gì","hl":["что"]},{"t":"А что это такое?","ph":"a shto E-ta ta-KO-ye","vi":"Cái này là cái gì vậy?","hl":["что"],"tokens":["А","что","это","такое"]}]},{"steps":[{"t":"будете","ph":"BU-di-te","vi":"(anh/chị) sẽ dùng","hl":[]},{"t":"что будете","ph":"shto BU-di-te","vi":"dùng gì","hl":["что"]},{"t":"А вы что будете?","ph":"a vy shto BU-di-te","vi":"Còn anh/chị dùng gì ạ?","hl":["что"],"tokens":["А","вы","что","будете"]}]},{"steps":[{"t":"значит","ph":"ZNA-chit","vi":"có nghĩa","hl":[]},{"t":"что значит","ph":"shto ZNA-chit","vi":"nghĩa là gì","hl":["что"]},{"t":"А что значит это слово?","ph":"a shto ZNA-chit E-ta SLO-va","vi":"Từ này nghĩa là gì vậy?","hl":["что"],"tokens":["А","что","значит","это","слово"]}]}],"formula":[{"k":"X","t":"(А)"},{"k":"S","t":"(Chủ ngữ)"},{"k":"P","t":"что"},{"k":"V","t":"Động từ / это"}],"points":["\"что\" đọc là \"shto\" (chữ ч ở đây đọc như sh), nghĩa là cái gì.","\"Что это?\" = Đây là gì?; thêm такое cho tự nhiên hơn: \"Что это такое?\".","Hỏi ai đó làm gì: \"Что ты делаешь?\"; trong văn nói chủ ngữ có thể đứng trước: \"Ты что делаешь?\".","\"Что значит...?\" = ...nghĩa là gì?, rất hữu ích khi gặp từ lạ."],"mistakes":[{"wrong":"Это что есть?","right":"Что это?","why":"Không cần thêm động từ 'là' (есть); hỏi 'đây là gì' chỉ cần Что это?"},{"wrong":"Ты делаешь что?","right":"Что ты делаешь?","why":"Không đặt что cuối câu như 'bạn làm gì' của tiếng Việt; từ để hỏi đứng trước động từ."}],"compare":"Tiếng Việt để 'gì' ở cuối câu (Bạn làm gì?), tiếng Nga đặt что trước động từ (Что ты делаешь?).","tip":"Thấy \"что\" đừng đọc 'chto', cứ \"shto\" cho chuẩn giọng người Nga.","how":["Đặt что trước это → что это (đây là gì), thêm А ở đầu và такое ở cuối cho tự nhiên → А что это такое?","Đặt что trước будете (anh/chị sẽ dùng) → что будете, rồi thêm А вы ở đầu (văn nói đặt chủ ngữ trước что) → А вы что будете?","Đặt что trước значит (nghĩa là) → что значит, thêm А ở đầu và это слово (từ này) ở cuối → А что значит это слово?"],"dialog":[{"who":"A","t":"Что ты делаешь вечером?","ph":"shto ty DYE-la-yesh VYE-chi-ram","vi":"Tối nay bạn làm gì?","hl":["Что"]},{"who":"B","t":"Пока не знаю. А что?","ph":"pa-KA nye ZNA-yu a SHTO","vi":"Chưa biết nữa. Sao thế?","hl":["что"]},{"who":"A","t":"Пойдём в кино?","ph":"pa-DYOM f ki-NO","vi":"Đi xem phim không?","hl":[]},{"who":"B","t":"Давай! Что будем смотреть?","ph":"da-VAY shto BU-dim smat-RYET","vi":"Đi chứ! Mình xem phim gì?","hl":["Что"]}],"more":[{"t":"Что вы сказали?","ph":"shto vy ska-ZA-li","vi":"Anh/chị vừa nói gì ạ?","hl":["Что"],"tokens":["Что","вы","сказали"]},{"t":"Что ты будешь пить?","ph":"shto ty BU-dish PIT","vi":"Bạn uống gì?","hl":["Что"],"tokens":["Что","ты","будешь","пить"]},{"t":"Что здесь можно посмотреть?","ph":"shto zdyes MOZH-na pa-smat-RYET","vi":"Ở đây có gì để xem?","hl":["Что"],"tokens":["Что","здесь","можно","посмотреть"]},{"t":"Что ты делаешь в субботу?","ph":"shto ty DYE-la-yesh f su-BO-tu","vi":"Thứ bảy bạn làm gì?","hl":["Что"],"tokens":["Что","ты","делаешь","в","субботу"]},{"t":"Что вы посоветуете на ужин?","ph":"shto vy pa-sa-VYE-tu-ye-te na U-zhin","vi":"Anh/chị gợi ý món gì cho bữa tối?","hl":["Что"],"tokens":["Что","вы","посоветуете","на","ужин"]},{"t":"Я не понял, что вы имеете в виду.","ph":"ya nye PO-nyal shto vy i-MYE-ye-te v vi-DU","vi":"Tôi chưa hiểu ý anh/chị là gì.","hl":["что"],"tokens":["Я","не","понял,","что","вы","имеете","в","виду"]}]},{"id":12,"vi":"ai","note":"'кто' hỏi người, động từ theo sau chia ngôi thứ ba số ít (Кто говорит?); 'кто это?' = đây là ai; các dạng khác: кого (ai – đối cách), кому (cho ai).","pivot":{"t":"кто","ph":"kto"},"branches":[{"steps":[{"t":"это","ph":"E-ta","vi":"đây","hl":[]},{"t":"кто это","ph":"kto E-ta","vi":"đây là ai","hl":["кто"]},{"t":"А кто это?","ph":"a kto E-ta","vi":"Còn đây là ai?","hl":["кто"],"tokens":["А","кто","это"]}]},{"steps":[{"t":"профессии","ph":"pra-FYE-si-i","vi":"nghề nghiệp","hl":[]},{"t":"кто по профессии","ph":"kto pa pra-FYE-si-i","vi":"làm nghề gì","hl":["кто"]},{"t":"Вы кто по профессии?","ph":"vy kto pa pra-FYE-si-i","vi":"Anh/chị làm nghề gì?","hl":["кто"],"tokens":["Вы","кто","по","профессии"]}]},{"steps":[{"t":"последний","ph":"pas-LYED-niy","vi":"cuối cùng","hl":[]},{"t":"кто последний","ph":"kto pas-LYED-niy","vi":"ai là người cuối","hl":["кто"]},{"t":"А кто последний?","ph":"a kto pas-LYED-niy","vi":"Ai là người cuối hàng ạ?","hl":["кто"],"tokens":["А","кто","последний"]}]}],"formula":[{"k":"P","t":"кто"},{"k":"V","t":"Động từ (ngôi 3 số ít) / это"}],"points":["\"кто\" = ai, hỏi về người; động từ theo sau chia ngôi thứ ba số ít: \"Кто знает?\", \"Кто говорит по-английски?\".","\"Кто это?\" = Đây là ai?; \"Кто там?\" = Ai đấy? (khi có người gõ cửa).","\"Кто вы по профессии?\" hỏi nghề nghiệp; trả lời ngắn: \"Я инженер\".","Các dạng khác của кто: кого (ai, làm tân ngữ: Кого вы ждёте?), кому (cho ai), у кого (ai có)."],"mistakes":[{"wrong":"Кто знают?","right":"Кто знает?","why":"Sau кто động từ luôn chia số ít ngôi thứ ba, dù câu trả lời có thể là nhiều người."},{"wrong":"Кто вы ждёте?","right":"Кого вы ждёте?","why":"'Ai' làm tân ngữ (đợi ai) phải đổi thành кого."}],"compare":"Tiếng Việt để 'ai' đúng chỗ của người trong câu (Bạn đợi ai?), tiếng Nga đưa từ hỏi lên đầu và đổi dạng nếu cần: Кого ты ждёшь?","tip":"\"kto\" ngắn như tiếng gõ cửa: cốc cốc, \"Кто там?\" (Ai đấy?).","how":["Đặt кто trước это → кто это (đây là ai), thêm А (còn) ở đầu → А кто это?","Từ профессии (nghề nghiệp, giới cách), thêm кто по phía trước → кто по профессии, rồi thêm Вы ở đầu → Вы кто по профессии?","Đặt кто trước последний (người cuối cùng) → кто последний, thêm А ở đầu → А кто последний? (câu quen thuộc khi xếp hàng ở Nga)."],"dialog":[{"who":"A","t":"Кто там?","ph":"kto TAM","vi":"Ai đấy?","hl":["Кто"]},{"who":"B","t":"Это я, Маша. Открой!","ph":"E-ta YA MA-sha at-KROY","vi":"Mình đây, Masha. Mở cửa đi!","hl":[]},{"who":"A","t":"А кто с тобой?","ph":"a kto s ta-BOY","vi":"Thế ai đi cùng bạn vậy?","hl":["кто"]},{"who":"B","t":"Мой брат. Он приехал из Казани.","ph":"moy BRAT on pri-YE-khal is ka-ZA-ni","vi":"Anh trai mình. Anh ấy từ Kazan đến.","hl":[]}],"more":[{"t":"Кто ваш гид?","ph":"kto vash GIT","vi":"Hướng dẫn viên của các bạn là ai?","hl":["Кто"],"tokens":["Кто","ваш","гид"]},{"t":"Кто это сделал?","ph":"kto E-ta SDYE-lal","vi":"Ai làm việc này?","hl":["Кто"],"tokens":["Кто","это","сделал"]},{"t":"Кто говорит по-английски?","ph":"kto ga-va-RIT pa-an-GLIY-ski","vi":"Ai nói được tiếng Anh?","hl":["Кто"],"tokens":["Кто","говорит","по-английски"]},{"t":"Кто сидит на этом месте?","ph":"kto si-DIT na E-tam MYES-te","vi":"Ai ngồi chỗ này vậy?","hl":["Кто"],"tokens":["Кто","сидит","на","этом","месте"]},{"t":"Кто знает хороший ресторан рядом?","ph":"kto ZNA-yet kha-RO-shiy ris-ta-RAN RYA-dam","vi":"Ai biết nhà hàng nào ngon gần đây không?","hl":["Кто"],"tokens":["Кто","знает","хороший","ресторан","рядом"]},{"t":"Вы не знаете, кто здесь отвечает за билеты?","ph":"vy nye ZNA-ye-te kto zdyes at-vi-CHA-yet za bi-LYE-ty","vi":"Anh/chị có biết ai phụ trách vé ở đây không?","hl":["кто"],"tokens":["Вы","не","знаете,","кто","здесь","отвечает","за","билеты"]}]},{"id":13,"vi":"khi nào","note":"'когда' = khi nào; hỏi giờ cụ thể dùng 'во сколько?' (lúc mấy giờ); trả lời: 'в пять часов' (lúc 5 giờ).","pivot":{"t":"когда","ph":"kag-DA"},"branches":[{"steps":[{"t":"приедем","ph":"pri-YE-dim","vi":"(chúng ta) đến nơi","hl":[]},{"t":"когда приедем","ph":"kag-DA pri-YE-dim","vi":"khi nào đến nơi","hl":["когда"]},{"t":"Мы когда приедем?","ph":"my kag-DA pri-YE-dim","vi":"Khi nào chúng ta đến nơi?","hl":["когда"],"tokens":["Мы","когда","приедем"]}]},{"steps":[{"t":"вернёшься","ph":"vir-NYOSH-sya","vi":"(bạn) quay về","hl":[]},{"t":"когда вернёшься","ph":"kag-DA vir-NYOSH-sya","vi":"khi nào về","hl":["когда"]},{"t":"Ты когда вернёшься?","ph":"ty kag-DA vir-NYOSH-sya","vi":"Khi nào bạn về?","hl":["когда"],"tokens":["Ты","когда","вернёшься"]}]},{"steps":[{"t":"завтрак","ph":"ZAF-trak","vi":"bữa sáng","hl":[]},{"t":"завтрак во сколько","ph":"ZAF-trak va SKOL-ka","vi":"bữa sáng lúc mấy giờ","hl":["во сколько"]},{"t":"А завтрак во сколько?","ph":"a ZAF-trak va SKOL-ka","vi":"Bữa sáng lúc mấy giờ ạ?","hl":["во сколько"],"tokens":["А","завтрак","во","сколько"]}]}],"formula":[{"k":"S","t":"(Chủ ngữ)"},{"k":"P","t":"когда"},{"k":"V","t":"Động từ"}],"points":["\"когда\" = khi nào, đứng đầu câu hoặc sau chủ ngữ trong văn nói: \"Когда ты вернёшься?\" / \"Ты когда вернёшься?\".","Hỏi giờ chính xác dùng \"во сколько?\" (lúc mấy giờ): \"Во сколько поезд?\".","Trả lời giờ: в + số + час/часа/часов: \"в два часа\", \"в пять часов\".","\"когда\" cũng nối hai vế với nghĩa 'khi': \"Когда я приеду, я позвоню\"."],"mistakes":[{"wrong":"Ты вернёшься когда?","right":"Когда ты вернёшься?","why":"Không đặt когда cuối câu như 'bạn về khi nào' trong tiếng Việt; từ hỏi đứng trước động từ."},{"wrong":"Когда часов завтрак?","right":"Во сколько завтрак?","why":"Hỏi 'lúc mấy giờ' dùng cụm cố định во сколько, không ghép когда với часов."}],"compare":"Tiếng Việt có thể nói 'khi nào' ở đầu (Khi nào bạn về?) hoặc 'khi nào' cuối câu (Bạn về khi nào?); tiếng Nga luôn để когда trước động từ.","tip":"\"kag-DA\" một từ hai việc: hỏi 'khi nào?' và kể 'khi...'.","how":["Đặt когда trước động từ приедем (chúng ta sẽ đến) → когда приедем, rồi thêm Мы ở đầu theo kiểu văn nói → Мы когда приедем?","Đặt когда trước вернёшься (bạn sẽ quay về) → когда вернёшься, thêm Ты ở đầu → Ты когда вернёшься?","Hỏi giờ cụ thể thì đặt во сколько (lúc mấy giờ) sau завтрак (bữa sáng) → завтрак во сколько, thêm А ở đầu → А завтрак во сколько?"],"dialog":[{"who":"A","t":"Когда отправляется поезд?","ph":"kag-DA at-prav-LYA-it-sya PO-yezd","vi":"Khi nào tàu chạy?","hl":["Когда"]},{"who":"B","t":"В девять утра.","ph":"v DYE-vyat ut-RA","vi":"Lúc chín giờ sáng.","hl":[]},{"who":"A","t":"А когда он прибывает в Москву?","ph":"a kag-DA on pri-by-VA-yet v mask-VU","vi":"Thế khi nào tàu đến Moscow?","hl":["когда"]},{"who":"B","t":"В шесть вечера, по расписанию.","ph":"f SHEST VYE-chi-ra pa ras-pi-SA-ni-yu","vi":"Theo lịch là sáu giờ tối.","hl":[]}],"more":[{"t":"Когда ты свободен?","ph":"kag-DA ty sva-BO-din","vi":"Khi nào bạn rảnh?","hl":["Когда"],"tokens":["Когда","ты","свободен"]},{"t":"Когда открывается музей?","ph":"kag-DA at-kry-VA-it-sya mu-ZYEY","vi":"Khi nào bảo tàng mở cửa?","hl":["Когда"],"tokens":["Когда","открывается","музей"]},{"t":"Когда начинается концерт?","ph":"kag-DA na-chi-NA-it-sya kan-TSERT","vi":"Khi nào buổi hòa nhạc bắt đầu?","hl":["Когда"],"tokens":["Когда","начинается","концерт"]},{"t":"Во сколько закрывается магазин?","ph":"va SKOL-ka za-kry-VA-it-sya ma-ga-ZIN","vi":"Cửa hàng đóng cửa lúc mấy giờ?","hl":["Во сколько"],"tokens":["Во","сколько","закрывается","магазин"]},{"t":"Когда у вас день рождения?","ph":"kag-DA u vas DYEN razh-DYE-ni-ya","vi":"Sinh nhật anh/chị là khi nào?","hl":["Когда"],"tokens":["Когда","у","вас","день","рождения"]},{"t":"Когда я приеду в отель, я позвоню.","ph":"kag-DA ya pri-YE-du v a-TEL ya pa-zva-NYU","vi":"Khi nào đến khách sạn tôi sẽ gọi điện.","hl":["Когда"],"tokens":["Когда","я","приеду","в","отель,","я","позвоню"]}]},{"id":14,"vi":"tại sao / vì","note":"'почему' = tại sao; trả lời bằng 'потому что' (vì) + mệnh đề (trong câu ghép, trước 'потому что' có dấu phẩy); 'из-за' + sở hữu cách = vì/do (thường là nguyên nhân xấu).","pivot":{"t":"почему","ph":"pa-chi-MU"},"branches":[{"steps":[{"t":"закрыто","ph":"za-KRY-ta","vi":"đóng cửa","hl":[]},{"t":"почему закрыто","ph":"pa-chi-MU za-KRY-ta","vi":"sao lại đóng cửa","hl":["почему"]},{"t":"А почему закрыто?","ph":"a pa-chi-MU za-KRY-ta","vi":"Sao lại đóng cửa vậy?","hl":["почему"],"tokens":["А","почему","закрыто"]}]},{"steps":[{"t":"устал","ph":"u-STAL","vi":"(đã) mệt","hl":[]},{"t":"потому что устал","ph":"pa-ta-MU shta u-STAL","vi":"vì mệt","hl":["потому что"]},{"t":"Просто потому что устал.","ph":"PROS-ta pa-ta-MU shta u-STAL","vi":"Đơn giản là vì mệt thôi.","hl":["потому что"],"tokens":["Просто","потому","что","устал"]}]},{"steps":[{"t":"дождя","ph":"dazh-DYA","vi":"mưa","hl":[]},{"t":"из-за дождя","ph":"iz-za dazh-DYA","vi":"vì trời mưa","hl":["из-за"]},{"t":"Мы дома из-за дождя.","ph":"my DO-ma iz-za dazh-DYA","vi":"Chúng tôi ở nhà vì trời mưa.","hl":["из-за"],"tokens":["Мы","дома","из-за","дождя"]}]}],"formula":[{"k":"P","t":"почему"},{"k":"X","t":"Câu hỏi"},{"k":"P","t":"потому что"},{"k":"X","t":"Lý do"}],"points":["\"почему\" = tại sao, đứng đầu câu hỏi: \"Почему ты молчишь?\".","Trả lời bằng \"потому что\" + một vế câu (vì...); trong câu ghép đặt dấu phẩy trước потому что.","\"из-за\" + sở hữu cách = vì/do (thường là nguyên nhân không hay): \"из-за дождя\", \"из-за пробки\".","\"потому что\" đọc là \"pa-ta-MU shta\", chữ что vẫn đọc 'shta' như thường."],"mistakes":[{"wrong":"Мы дома из-за дождь.","right":"Мы дома из-за дождя.","why":"Sau из-за danh từ phải ở sở hữu cách: дождь → дождя."},{"wrong":"Я не пришёл потому устал.","right":"Я не пришёл, потому что устал.","why":"'Vì' là cả cụm потому что, thiếu что là sai; trước nó có dấu phẩy."}],"compare":"Giống tiếng Việt: hỏi 'tại sao' ở đầu câu, trả lời bằng 'vì'. Khác: 'vì' + câu là потому что, còn 'vì' + danh từ là из-за và danh từ phải đổi đuôi.","tip":"Hỏi \"pa-chi-MU?\" thì đáp \"pa-ta-MU shta...\": câu hỏi và câu đáp như hai anh em sinh đôi.","how":["Từ закрыто (đóng cửa), đặt почему trước → почему закрыто, thêm А ở đầu → А почему закрыто?","Từ устал (mệt), đặt потому что (vì) trước → потому что устал, thêm Просто (đơn giản là) ở đầu → Просто потому что устал.","Từ дождя (sở hữu cách của дождь, mưa), đặt из-за (do) trước → из-за дождя, thêm Мы дома (chúng tôi ở nhà) ở đầu → Мы дома из-за дождя."],"dialog":[{"who":"A","t":"Почему ты опоздал?","ph":"pa-chi-MU ty a-paz-DAL","vi":"Sao bạn đến muộn?","hl":["Почему"]},{"who":"B","t":"Из-за пробки на дороге.","ph":"iz-za PROP-ki na da-RO-ge","vi":"Vì tắc đường.","hl":["Из-за"]},{"who":"A","t":"А почему не позвонил?","ph":"a pa-chi-MU nye pa-zva-NIL","vi":"Thế sao không gọi điện?","hl":["почему"]},{"who":"B","t":"Потому что телефон сел.","ph":"pa-ta-MU shta ti-li-FON SYEL","vi":"Vì điện thoại hết pin.","hl":["Потому что"]}],"more":[{"t":"Почему ты не спишь?","ph":"pa-chi-MU ty nye SPISH","vi":"Sao bạn chưa ngủ?","hl":["Почему"],"tokens":["Почему","ты","не","спишь"]},{"t":"Почему поезд опаздывает?","ph":"pa-chi-MU PO-yezd a-PAZ-dy-va-yet","vi":"Sao tàu lại trễ?","hl":["Почему"],"tokens":["Почему","поезд","опаздывает"]},{"t":"Рейс задержали из-за тумана.","ph":"REYS za-dir-ZHA-li iz-za tu-MA-na","vi":"Chuyến bay bị hoãn vì sương mù.","hl":["из-за"],"tokens":["Рейс","задержали","из-за","тумана"]},{"t":"Почему здесь так много людей?","ph":"pa-chi-MU zdyes tak MNO-ga lyu-DYEY","vi":"Sao ở đây đông người thế?","hl":["Почему"],"tokens":["Почему","здесь","так","много","людей"]},{"t":"Я не пришёл, потому что заболел.","ph":"ya nye pri-SHOL pa-ta-MU shta za-ba-LYEL","vi":"Tôi không đến được vì bị ốm.","hl":["потому что"],"tokens":["Я","не","пришёл,","потому","что","заболел"]},{"t":"Мы выбрали этот отель, потому что он рядом.","ph":"my VY-bra-li E-tat a-TEL pa-ta-MU shta on RYA-dam","vi":"Chúng tôi chọn khách sạn này vì nó ở gần.","hl":["потому что"],"tokens":["Мы","выбрали","этот","отель,","потому","что","он","рядом"]}]},{"id":15,"vi":"làm ơn","note":"Cách nhờ lịch sự: 'Вы не могли бы + động từ nguyên mẫu?' (Anh/chị làm ơn... được không?); cách thông dụng khác là mệnh lệnh + 'пожалуйста' (Помогите, пожалуйста! — luôn có dấu phẩy).","pivot":{"t":"не могли бы","ph":"nye MOG-li by"},"branches":[{"steps":[{"t":"показать","ph":"pa-ka-ZAT","vi":"chỉ","hl":[]},{"t":"не могли бы показать","ph":"nye MOG-li by pa-ka-ZAT","vi":"làm ơn chỉ","hl":["не могли бы"]},{"t":"Вы не могли бы показать дорогу?","ph":"vy nye MOG-li by pa-ka-ZAT da-RO-gu","vi":"Làm ơn chỉ đường giúp tôi được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","показать","дорогу"]}]},{"steps":[{"t":"повторить","ph":"paf-ta-RIT","vi":"nhắc lại","hl":[]},{"t":"не могли бы повторить","ph":"nye MOG-li by paf-ta-RIT","vi":"làm ơn nhắc lại","hl":["не могли бы"]},{"t":"Вы не могли бы повторить?","ph":"vy nye MOG-li by paf-ta-RIT","vi":"Anh/chị làm ơn nhắc lại được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","повторить"]}]},{"steps":[{"t":"вызвать","ph":"VYZ-vat","vi":"gọi (xe)","hl":[]},{"t":"не могли бы вызвать","ph":"nye MOG-li by VYZ-vat","vi":"làm ơn gọi","hl":["не могли бы"]},{"t":"Вы не могли бы вызвать такси?","ph":"vy nye MOG-li by VYZ-vat tak-SI","vi":"Làm ơn gọi giúp tôi taxi được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","вызвать","такси"]}]}],"formula":[{"k":"S","t":"Anh/chị"},{"k":"P","t":"не могли бы"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Tân ngữ)"}],"points":["\"Вы не могли бы + động từ nguyên mẫu?\" là cách nhờ rất lịch sự, nghĩa đen 'Anh/chị không thể... được sao?'.","Động từ theo sau thường ở thể hoàn thành: показать, повторить, помочь.","Cách ngắn hơn: động từ mệnh lệnh + пожалуйста, có dấu phẩy ngăn cách: \"Повторите, пожалуйста\".","Với bạn bè dùng \"Ты не мог бы...\" (nói với nam) / \"Ты не могла бы...\" (nói với nữ)."],"mistakes":[{"wrong":"Вы не могли бы показываете дорогу?","right":"Вы не могли бы показать дорогу?","why":"Sau не могли бы động từ phải ở nguyên mẫu, không chia."},{"wrong":"Ты не могли бы помочь?","right":"Ты не мог бы помочь?","why":"Với ты dùng мог бы (nói với nam) hoặc могла бы (nói với nữ); могли бы chỉ đi với вы."}],"compare":"Tiếng Việt nhờ bằng 'làm ơn ... được không?', tiếng Nga lịch sự bằng câu hỏi phủ định 'Вы не могли бы...?': có chữ не mà không hề mang nghĩa phủ định.","tip":"Có 'не' mà vẫn là nhờ: người Nga hỏi vòng 'anh không thể... sao?' cho thật lịch sự, cứ thuộc lòng cả cụm \"nye MOG-li by\".","how":["Đặt не могли бы trước показать (chỉ cho xem) → не могли бы показать, thêm Вы ở đầu và дорогу (đường) ở cuối → Вы не могли бы показать дорогу?","Đặt не могли бы trước повторить (nhắc lại) → не могли бы повторить, thêm Вы ở đầu và lên giọng → Вы не могли бы повторить?","Đặt не могли бы trước вызвать (gọi đến) → не могли бы вызвать, thêm Вы ở đầu và такси ở cuối → Вы не могли бы вызвать такси?"],"dialog":[{"who":"A","t":"Извините, вы не могли бы нас сфотографировать?","ph":"iz-vi-NI-te vy nye MOG-li by nas sfa-ta-gra-FI-ra-vat","vi":"Xin lỗi, anh/chị chụp giúp chúng tôi một tấm được không?","hl":["не могли бы"]},{"who":"B","t":"Конечно! Встаньте ближе.","ph":"ka-NYESH-na FSTAN-te BLI-zhe","vi":"Tất nhiên! Mọi người đứng gần vào.","hl":[]},{"who":"A","t":"А вы не могли бы ещё раз?","ph":"a vy nye MOG-li by i-SHCHO RAS","vi":"Anh/chị chụp thêm một tấm nữa được không?","hl":["не могли бы"]},{"who":"B","t":"Без проблем. Улыбайтесь!","ph":"bes prab-LYEM u-ly-BAY-tes","vi":"Không vấn đề gì. Cười lên nào!","hl":[]}],"more":[{"t":"Вы не могли бы помочь?","ph":"vy nye MOG-li by pa-MOCH","vi":"Anh/chị giúp tôi được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","помочь"]},{"t":"Вы не могли бы написать адрес?","ph":"vy nye MOG-li by na-pi-SAT AD-ris","vi":"Anh/chị viết giúp địa chỉ được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","написать","адрес"]},{"t":"Ты не мог бы открыть окно?","ph":"ty nye MOK by at-KRYT ak-NO","vi":"Bạn mở cửa sổ giúp mình được không?","hl":["не мог бы"],"tokens":["Ты","не","мог","бы","открыть","окно"]},{"t":"Ты не могла бы купить хлеба?","ph":"ty nye MOG-la by ku-PIT KHLYE-ba","vi":"Bạn mua giúp mình ít bánh mì được không?","hl":["не могла бы"],"tokens":["Ты","не","могла","бы","купить","хлеба"]},{"t":"Вы не могли бы говорить медленнее?","ph":"vy nye MOG-li by ga-va-RIT MYED-li-nye-ye","vi":"Anh/chị nói chậm hơn được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","говорить","медленнее"]},{"t":"Вы не могли бы поменять мне номер?","ph":"vy nye MOG-li by pa-mi-NYAT mnye NO-mir","vi":"Anh/chị đổi phòng khác cho tôi được không?","hl":["не могли бы"],"tokens":["Вы","не","могли","бы","поменять","мне","номер"]}]},{"id":16,"vi":"đừng","note":"'Đừng' = 'не' + động từ mệnh lệnh, thường ở thể chưa hoàn thành (не опаздывай, не волнуйтесь); dạng lịch sự/số nhiều thêm '-те'. Riêng lời nhắc 'đừng quên' dùng thể hoàn thành: не забудь(те).","pivot":{"t":"не","ph":"nye"},"branches":[{"steps":[{"t":"волнуйтесь","ph":"val-NUY-tes","vi":"(hãy) lo lắng","hl":[]},{"t":"не волнуйтесь","ph":"nye val-NUY-tes","vi":"đừng lo","hl":["не"]},{"t":"Вы не волнуйтесь.","ph":"vy nye val-NUY-tes","vi":"Anh/chị đừng lo.","hl":["не"],"tokens":["Вы","не","волнуйтесь"]}]},{"steps":[{"t":"забудь","ph":"za-BUT","vi":"(hãy) quên","hl":[]},{"t":"не забудь","ph":"nye za-BUT","vi":"đừng quên","hl":["не"]},{"t":"Только не забудь паспорт!","ph":"TOL-ka nye za-BUT PAS-part","vi":"Nhớ đừng quên hộ chiếu nhé!","hl":["не"],"tokens":["Только","не","забудь","паспорт"]}]},{"steps":[{"t":"опаздывай","ph":"a-PAZ-dy-vay","vi":"(hãy) đến muộn","hl":[]},{"t":"не опаздывай","ph":"nye a-PAZ-dy-vay","vi":"đừng đến muộn","hl":["не"]},{"t":"Завтра не опаздывай!","ph":"ZAF-tra nye a-PAZ-dy-vay","vi":"Ngày mai đừng đến muộn nhé!","hl":["не"],"tokens":["Завтра","не","опаздывай"]}]}],"formula":[{"k":"S","t":"(Anh/chị / Bạn)"},{"k":"P","t":"не"},{"k":"V","t":"Động từ mệnh lệnh"}],"points":["'Đừng' = не + động từ mệnh lệnh: \"Не волнуйся\" (đừng lo, nói với bạn), \"Не волнуйтесь\" (nói với anh/chị hoặc nhiều người).","Lời khuyên 'đừng làm' thường dùng thể chưa hoàn thành: не опаздывай, не кури, не трогай.","Nhắc 'đừng quên' dùng thể hoàn thành: \"Не забудь!\", \"Не забудьте ключ!\".","Thêm \"только\" (chỉ cần) hoặc \"пожалуйста\" để giọng nhẹ nhàng hơn: \"Только не опаздывай!\"."],"mistakes":[{"wrong":"Нет волнуйтесь!","right":"Не волнуйтесь!","why":"'Đừng' là не; нет chỉ là 'không' dùng để trả lời."},{"wrong":"Вы не волнуйся.","right":"Вы не волнуйтесь.","why":"Nói với вы thì động từ mệnh lệnh phải có đuôi -те: волнуйтесь."}],"compare":"Giống tiếng Việt: 'đừng' đứng trước động từ (đừng lo = не волнуйтесь). Khác: tiếng Nga dùng chung chữ не với 'không', động từ phải ở dạng mệnh lệnh và thêm -те khi lịch sự.","tip":"не + mệnh lệnh = biển cấm biết nói: Не курите! Не трогайте! Thêm -те là biển cấm lịch sự.","how":["Lấy mệnh lệnh lịch sự волнуйтесь (hãy lo lắng), đặt не trước → не волнуйтесь (đừng lo), thêm Вы ở đầu cho thân thiện → Вы не волнуйтесь.","Lấy забудь (quên, thể hoàn thành), đặt не trước → не забудь, thêm Только (chỉ cần) ở đầu và паспорт ở cuối → Только не забудь паспорт!","Lấy опаздывай (đến muộn, thể chưa hoàn thành), đặt не trước → не опаздывай, thêm Завтра (ngày mai) ở đầu → Завтра не опаздывай!"],"dialog":[{"who":"A","t":"Не забудь зонт, будет дождь.","ph":"nye za-BUT ZONT BU-dit DOZHT","vi":"Đừng quên ô nhé, trời sắp mưa đấy.","hl":["Не"]},{"who":"B","t":"Хорошо. Не волнуйся, мама.","ph":"kha-ra-SHO nye val-NUY-sya MA-ma","vi":"Vâng ạ. Mẹ đừng lo.","hl":["Не"]},{"who":"A","t":"И не гуляй слишком поздно!","ph":"i nye gu-LYAY SLISH-kam POZ-na","vi":"Và đừng đi chơi khuya quá!","hl":["не"]},{"who":"B","t":"Ладно, я вернусь к десяти.","ph":"LAD-na ya vir-NUS k di-si-TI","vi":"Vâng, con sẽ về trước mười giờ.","hl":[]}],"more":[{"t":"Не кури здесь!","ph":"nye ku-RI zdyes","vi":"Đừng hút thuốc ở đây!","hl":["Не"],"tokens":["Не","кури","здесь"]},{"t":"Не трогайте экспонаты!","ph":"nye TRO-gay-te eks-pa-NA-ty","vi":"Đừng chạm vào hiện vật!","hl":["Не"],"tokens":["Не","трогайте","экспонаты"]},{"t":"Пожалуйста, не шумите.","ph":"pa-ZHA-lus-ta nye shu-MI-te","vi":"Làm ơn đừng làm ồn.","hl":["не"],"tokens":["Пожалуйста,","не","шумите"]},{"t":"Не забудьте ключ от номера!","ph":"nye za-BUT-te KLYUCH at NO-mi-ra","vi":"Đừng quên chìa khóa phòng nhé!","hl":["Не"],"tokens":["Не","забудьте","ключ","от","номера"]},{"t":"Не пей воду из-под крана.","ph":"nye PYEY VO-du iz-pad KRA-na","vi":"Đừng uống nước máy trực tiếp từ vòi.","hl":["Не"],"tokens":["Не","пей","воду","из-под","крана"]},{"t":"Не оставляйте вещи без присмотра в аэропорту.","ph":"nye a-stav-LYAY-te VYE-shchi bis pri-SMOT-ra v a-e-ra-par-TU","vi":"Đừng để đồ đạc không người trông ở sân bay.","hl":["Не"],"tokens":["Не","оставляйте","вещи","без","присмотра","в","аэропорту"]}]},{"id":17,"vi":"đã","note":"Tiếng Nga không có từ riêng cho 'đã': thì quá khứ tạo bằng đuôi động từ -л (nam), -ла (nữ), -ли (số nhiều), ví dụ я поел / я поела; 'уже' = 'đã ... rồi', hay đi kèm để nhấn mạnh.","pivot":{"t":"уже","ph":"u-ZHE"},"branches":[{"steps":[{"t":"поел","ph":"pa-YEL","vi":"(đã) ăn","hl":[]},{"t":"уже поел","ph":"u-ZHE pa-YEL","vi":"đã ăn rồi","hl":["уже"]},{"t":"Я уже поел.","ph":"ya u-ZHE pa-YEL","vi":"Tôi ăn rồi.","hl":["уже"],"tokens":["Я","уже","поел"]}]},{"steps":[{"t":"был","ph":"BYL","vi":"(đã) ở / đến","hl":[]},{"t":"уже был","ph":"u-ZHE BYL","vi":"đã từng đến","hl":["уже"]},{"t":"Я уже был в Москве.","ph":"ya u-ZHE byl v mask-VYE","vi":"Tôi đã từng đến Moscow rồi.","hl":["уже"],"tokens":["Я","уже","был","в","Москве"]}]},{"steps":[{"t":"купила","ph":"ku-PI-la","vi":"(cô ấy đã) mua","hl":[]},{"t":"уже купила","ph":"u-ZHE ku-PI-la","vi":"đã mua rồi","hl":["уже"]},{"t":"Она уже купила билеты.","ph":"a-NA u-ZHE ku-PI-la bi-LYE-ty","vi":"Cô ấy đã mua vé rồi.","hl":["уже"],"tokens":["Она","уже","купила","билеты"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"уже"},{"k":"V","t":"Động từ quá khứ (-л/-ла/-ли)"},{"k":"O","t":"(Tân ngữ)"}],"points":["Quá khứ tạo bằng đuôi động từ: -л (nam), -ла (nữ), -ли (số nhiều hoặc вы): он купил, она купила, мы купили.","\"уже\" = đã ... rồi, thường đứng ngay trước động từ: \"Я уже поел\".","Đuôi quá khứ theo giới tính người nói: nam nói \"я устал\", nữ nói \"я устала\".","'Chưa' là \"ещё не\": \"Я ещё не поел\" (Tôi chưa ăn)."],"mistakes":[{"wrong":"Она уже купил билеты.","right":"Она уже купила билеты.","why":"Chủ ngữ nữ (она) thì động từ quá khứ phải có đuôi -ла."},{"wrong":"Я уже не поел.","right":"Я ещё не поел.","why":"'Chưa' là ещё не; уже не lại có nghĩa 'không còn ... nữa'."}],"compare":"Tiếng Việt thêm chữ 'đã/rồi' còn động từ giữ nguyên; tiếng Nga đổi đuôi động từ sang quá khứ, còn уже chỉ thêm ý 'rồi' để nhấn mạnh.","tip":"Quá khứ tiếng Nga 'lè lưỡi' chữ L: был, была, были; thêm уже là chắc chắn 'xong rồi'.","how":["Lấy поел (đã ăn, người nói là nam), đặt уже trước → уже поел, thêm Я ở đầu → Я уже поел.","Lấy был (đã ở/đã đến, nam), đặt уже trước → уже был, thêm Я ở đầu và в Москве (ở Moscow) ở cuối → Я уже был в Москве.","Lấy купила (đã mua, nữ), đặt уже trước → уже купила, thêm Она ở đầu và билеты (vé) ở cuối → Она уже купила билеты."],"dialog":[{"who":"A","t":"Ты уже был в Кремле?","ph":"ty u-ZHE byl f krim-LYE","vi":"Bạn đã đến điện Kremlin chưa?","hl":["уже"]},{"who":"B","t":"Да, уже был вчера.","ph":"da u-ZHE byl FCHE-ra","vi":"Rồi, hôm qua mình đến rồi.","hl":["уже"]},{"who":"A","t":"А билеты на балет ты уже купил?","ph":"a bi-LYE-ty na ba-LYET ty u-ZHE ku-PIL","vi":"Thế vé xem ba lê bạn mua chưa?","hl":["уже"]},{"who":"B","t":"Нет, ещё не купил.","ph":"nyet i-SHCHO nye ku-PIL","vi":"Chưa, mình chưa mua.","hl":[]}],"more":[{"t":"Мы уже пришли.","ph":"my u-ZHE pri-SHLI","vi":"Chúng ta đến nơi rồi.","hl":["уже"],"tokens":["Мы","уже","пришли"]},{"t":"Автобус уже ушёл.","ph":"af-TO-bus u-ZHE u-SHOL","vi":"Xe buýt đi mất rồi.","hl":["уже"],"tokens":["Автобус","уже","ушёл"]},{"t":"Я уже заказала такси.","ph":"ya u-ZHE za-ka-ZA-la tak-SI","vi":"Tôi đã gọi taxi rồi.","hl":["уже"],"tokens":["Я","уже","заказала","такси"]},{"t":"Вы уже видели Эрмитаж?","ph":"vy u-ZHE VI-di-li er-mi-TASH","vi":"Anh/chị đã xem bảo tàng Hermitage chưa?","hl":["уже"],"tokens":["Вы","уже","видели","Эрмитаж"]},{"t":"Магазин уже закрылся, приходите завтра.","ph":"ma-ga-ZIN u-ZHE za-KRYL-sya pri-kha-DI-te ZAF-tra","vi":"Cửa hàng đóng cửa rồi, mai quay lại nhé.","hl":["уже"],"tokens":["Магазин","уже","закрылся,","приходите","завтра"]},{"t":"Мы уже три дня живём в Москве.","ph":"my u-ZHE tri DNYA zhi-VYOM v mask-VYE","vi":"Chúng tôi đã ở Moscow được ba ngày rồi.","hl":["уже"],"tokens":["Мы","уже","три","дня","живём","в","Москве"]}]},{"id":18,"vi":"sẽ","note":"Tương lai = 'быть' chia (я буду, ты будешь, мы будем) + động từ chưa hoàn thành ở nguyên mẫu; động từ hoàn thành chia như hiện tại sẽ mang nghĩa tương lai (Я позвоню = Tôi sẽ gọi).","pivot":{"t":"буду","ph":"BU-du"},"branches":[{"steps":[{"t":"ждать","ph":"ZHDAT","vi":"đợi","hl":[]},{"t":"буду ждать","ph":"BU-du ZHDAT","vi":"sẽ đợi","hl":["буду"]},{"t":"Я буду ждать здесь.","ph":"ya BU-du ZHDAT zdyes","vi":"Tôi sẽ đợi ở đây.","hl":["буду"],"tokens":["Я","буду","ждать","здесь"]}]},{"steps":[{"t":"дома","ph":"DO-ma","vi":"ở nhà","hl":[]},{"t":"буду дома","ph":"BU-du DO-ma","vi":"sẽ ở nhà","hl":["буду"]},{"t":"Завтра я буду дома.","ph":"ZAF-tra ya BU-du DO-ma","vi":"Ngày mai tôi sẽ ở nhà.","hl":["буду"],"tokens":["Завтра","я","буду","дома"]}]},{"steps":[{"t":"жить","ph":"ZHIT","vi":"sống / ở","hl":[]},{"t":"будем жить","ph":"BU-dim ZHIT","vi":"sẽ ở","hl":["будем"]},{"t":"Мы будем жить в центре.","ph":"my BU-dim zhit f TSEN-tre","vi":"Chúng tôi sẽ ở khu trung tâm.","hl":["будем"],"tokens":["Мы","будем","жить","в","центре"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"буду"},{"k":"V","t":"Động từ nguyên mẫu (chưa hoàn thành)"}],"points":["Tương lai = быть chia (я буду, ты будешь, он будет, мы будем, вы будете, они будут) + động từ chưa hoàn thành ở nguyên mẫu: \"Я буду ждать\".","буду cũng đi một mình với nơi chốn/trạng thái, nghĩa là 'sẽ ở / sẽ là': \"Я буду дома\".","Động từ thể hoàn thành không đi với буду; chỉ cần chia như hiện tại là đã mang nghĩa tương lai: \"Я позвоню\" (Tôi sẽ gọi).","Khi gọi món có thể nói \"Я буду борщ\" = Tôi sẽ dùng súp borsch."],"mistakes":[{"wrong":"Я буду позвонить.","right":"Я позвоню.","why":"Động từ hoàn thành (позвонить) không đi với буду; chỉ cần chia nó: позвоню = tôi sẽ gọi."},{"wrong":"Мы буду жить в центре.","right":"Мы будем жить в центре.","why":"буду phải chia theo chủ ngữ: мы → будем."}],"compare":"Tiếng Việt chỉ thêm 'sẽ' trước động từ cho mọi người; tiếng Nga 'sẽ' (быть) chia theo người: я буду, мы будем, còn động từ sau giữ nguyên mẫu.","tip":"\"BU-du\" như tiếng trống báo trước: bu-du... chuyện sắp tới đây!","how":["Đặt буду trước nguyên mẫu ждать (đợi) → буду ждать, thêm Я ở đầu và здесь (ở đây) ở cuối → Я буду ждать здесь.","Đặt буду trước дома (ở nhà) → буду дома (sẽ ở nhà), thêm Завтра я (ngày mai tôi) ở đầu → Завтра я буду дома.","Chủ ngữ мы nên chia будем, đặt trước жить (sống) → будем жить, thêm Мы ở đầu và в центре (ở trung tâm) ở cuối → Мы будем жить в центре."],"dialog":[{"who":"A","t":"Что вы будете заказывать?","ph":"shto vy BU-di-te za-KA-zy-vat","vi":"Anh/chị gọi món gì ạ?","hl":["будете"]},{"who":"B","t":"Я буду пельмени и чай.","ph":"ya BU-du pil-MYE-ni i CHAY","vi":"Tôi sẽ dùng bánh pelmeni và trà.","hl":["буду"]},{"who":"A","t":"Чай будете с сахаром?","ph":"CHAY BU-di-te s SA-kha-ram","vi":"Trà anh/chị dùng với đường không?","hl":["будете"]},{"who":"B","t":"Нет, спасибо, без сахара.","ph":"nyet spa-SI-ba bis SA-kha-ra","vi":"Không, cảm ơn, không đường.","hl":[]}],"more":[{"t":"Я буду через час.","ph":"ya BU-du CHE-ris CHAS","vi":"Một tiếng nữa tôi sẽ đến.","hl":["буду"],"tokens":["Я","буду","через","час"]},{"t":"Завтра будет холодно.","ph":"ZAF-tra BU-dit KHO-lad-na","vi":"Mai trời sẽ lạnh.","hl":["будет"],"tokens":["Завтра","будет","холодно"]},{"t":"Ты будешь чай или кофе?","ph":"ty BU-dish CHAY I-li KO-fe","vi":"Bạn uống trà hay cà phê?","hl":["будешь"],"tokens":["Ты","будешь","чай","или","кофе"]},{"t":"Мы будем ужинать в отеле.","ph":"my BU-dim U-zhi-nat v a-TE-le","vi":"Chúng tôi sẽ ăn tối ở khách sạn.","hl":["будем"],"tokens":["Мы","будем","ужинать","в","отеле"]},{"t":"Я буду звонить тебе каждый вечер.","ph":"ya BU-du zva-NIT ti-BYE KAZH-dy VYE-chir","vi":"Tối nào tôi cũng sẽ gọi cho bạn.","hl":["буду"],"tokens":["Я","буду","звонить","тебе","каждый","вечер"]},{"t":"В следующем году я буду учиться в Москве.","ph":"f SLYE-du-yu-shchim ga-DU ya BU-du u-CHIT-sya v mask-VYE","vi":"Năm sau tôi sẽ học ở Moscow.","hl":["буду"],"tokens":["В","следующем","году","я","буду","учиться","в","Москве"]}]},{"id":19,"vi":"đang","note":"Tiếng Nga không có thì tiếp diễn riêng: dùng động từ thể chưa hoàn thành (imperfective) ở thì hiện tại, thường thêm сейчас (bây giờ) để nhấn mạnh 'đang'.","pivot":{"t":"сейчас","ph":"sey-CHAS"},"branches":[{"steps":[{"t":"работаю","ph":"ra-BO-ta-yu","vi":"làm việc","hl":[]},{"t":"сейчас работаю","ph":"sey-CHAS ra-BO-ta-yu","vi":"đang làm việc","hl":["сейчас"]},{"t":"Я сейчас работаю.","ph":"YA sey-CHAS ra-BO-ta-yu","vi":"Tôi đang làm việc.","hl":["сейчас"],"tokens":["Я","сейчас","работаю"]}]},{"steps":[{"t":"едем","ph":"YE-dyem","vi":"đi (bằng xe)","hl":[]},{"t":"сейчас едем","ph":"sey-CHAS YE-dyem","vi":"đang đi","hl":["сейчас"]},{"t":"Мы сейчас едем в отель.","ph":"MY sey-CHAS YE-dyem v a-TEL'","vi":"Chúng tôi đang đi về khách sạn.","hl":["сейчас"],"tokens":["Мы","сейчас","едем","в","отель"]}]},{"steps":[{"t":"спит","ph":"SPIT","vi":"ngủ","hl":[]},{"t":"сейчас спит","ph":"sey-CHAS SPIT","vi":"đang ngủ","hl":["сейчас"]},{"t":"Ребёнок сейчас спит.","ph":"ri-BYO-nak sey-CHAS SPIT","vi":"Em bé đang ngủ.","hl":["сейчас"],"tokens":["Ребёнок","сейчас","спит"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"сейчас"},{"k":"V","t":"Động từ (hiện tại)"},{"k":"O","t":"(Tân ngữ / Nơi chốn)"}],"points":["Tiếng Nga không có thì tiếp diễn riêng: thì hiện tại của động từ chưa hoàn thành vừa là 'làm' vừa là 'đang làm'.","Thêm сейчас (bây giờ) để nhấn mạnh hành động đang diễn ra ngay lúc nói (\"Я сейчас работаю\").","Сейчас thường đứng sau chủ ngữ, trước động từ, nhưng cũng có thể đứng đầu câu (\"Сейчас идёт дождь\").","Động từ phải chia theo chủ ngữ: я работаю, мы едем, он спит."],"mistakes":[{"wrong":"Я сейчас работать.","right":"Я сейчас работаю.","why":"Không để động từ ở dạng nguyên mẫu sau chủ ngữ; phải chia theo ngôi: я работаю."},{"wrong":"Ребёнок сейчас спать.","right":"Ребёнок сейчас спит.","why":"Chủ ngữ ngôi thứ ba số ít thì động từ chia là спит, không dùng nguyên mẫu спать."}],"compare":"Giống tiếng Việt, сейчас đứng trước động từ ở đúng chỗ của 'đang'; khác ở chỗ động từ tiếng Nga phải chia theo chủ ngữ, và kể cả không có сейчас câu vẫn có thể mang nghĩa 'đang'.","tip":"Thấy 'đang' thì nghĩ ngay 'xây-CHÁT' (сейчас) — ngay bây giờ, ngay lúc này!","how":["Lấy động từ работаю (tôi làm việc), thêm сейчас phía trước → сейчас работаю, rồi đặt chủ ngữ Я lên đầu → Я сейчас работаю.","Thêm сейчас trước động từ едем → сейчас едем, đặt chủ ngữ Мы lên đầu và nơi đến в отель ở cuối → Мы сейчас едем в отель.","Thêm сейчас trước động từ спит → сейчас спит, rồi đặt chủ ngữ Ребёнок lên đầu → Ребёнок сейчас спит."],"dialog":[{"who":"A","t":"Что ты сейчас делаешь?","ph":"SHTO ty sey-CHAS DYE-la-yesh","vi":"Bạn đang làm gì thế?","hl":["сейчас"]},{"who":"B","t":"Я сейчас обедаю.","ph":"YA sey-CHAS a-BYE-da-yu","vi":"Tôi đang ăn trưa.","hl":["сейчас"]},{"who":"A","t":"А где Анна?","ph":"a GDYE AN-na","vi":"Còn Anna đâu?","hl":[]},{"who":"B","t":"Она сейчас в магазине.","ph":"a-NA sey-CHAS v ma-ga-ZI-ne","vi":"Cô ấy đang ở cửa hàng.","hl":["сейчас"]}],"more":[{"t":"Я сейчас читаю.","ph":"YA sey-CHAS chi-TA-yu","vi":"Tôi đang đọc sách.","hl":["сейчас"],"tokens":["Я","сейчас","читаю"]},{"t":"Сейчас идёт дождь.","ph":"sey-CHAS i-DYOT DOZHT'","vi":"Trời đang mưa.","hl":["Сейчас"],"tokens":["Сейчас","идёт","дождь"]},{"t":"Мы сейчас ждём такси.","ph":"MY sey-CHAS ZHDYOM tak-SI","vi":"Chúng tôi đang chờ taxi.","hl":["сейчас"],"tokens":["Мы","сейчас","ждём","такси"]},{"t":"Он сейчас говорит по телефону.","ph":"ON sey-CHAS ga-va-RIT pa ti-li-FO-nu","vi":"Anh ấy đang nói chuyện điện thoại.","hl":["сейчас"],"tokens":["Он","сейчас","говорит","по","телефону"]},{"t":"Мама сейчас готовит ужин.","ph":"MA-ma sey-CHAS ga-TO-vit U-zhin","vi":"Mẹ đang nấu bữa tối.","hl":["сейчас"],"tokens":["Мама","сейчас","готовит","ужин"]},{"t":"Извините, я сейчас очень занят.","ph":"iz-vi-NI-te YA sey-CHAS O-chen ZA-nyat","vi":"Xin lỗi, bây giờ tôi đang rất bận.","hl":["сейчас"],"tokens":["Извините,","я","сейчас","очень","занят"]}]},{"id":20,"vi":"rồi","note":"'Rồi' (đã xong) dịch bằng уже (đã, rồi) đi với động từ thì quá khứ thể hoàn thành (perfective) như поел, купил; động từ quá khứ chia theo giống: поел (nam) / поела (nữ).","pivot":{"t":"уже","ph":"u-ZHE"},"branches":[{"steps":[{"t":"поел","ph":"pa-YEL","vi":"đã ăn","hl":[]},{"t":"уже поел","ph":"u-ZHE pa-YEL","vi":"ăn rồi","hl":["уже"]},{"t":"Я уже поел.","ph":"YA u-ZHE pa-YEL","vi":"Tôi ăn rồi.","hl":["уже"],"tokens":["Я","уже","поел"]}]},{"steps":[{"t":"пришли","ph":"prish-LI","vi":"đã đến","hl":[]},{"t":"уже пришли","ph":"u-ZHE prish-LI","vi":"đến rồi","hl":["уже"]},{"t":"Мы уже пришли.","ph":"MY u-ZHE prish-LI","vi":"Chúng ta đến nơi rồi.","hl":["уже"],"tokens":["Мы","уже","пришли"]}]},{"steps":[{"t":"купил","ph":"ku-PIL","vi":"đã mua","hl":[]},{"t":"уже купил","ph":"u-ZHE ku-PIL","vi":"mua rồi","hl":["уже"]},{"t":"Я уже купил билеты.","ph":"YA u-ZHE ku-PIL bi-LYE-ty","vi":"Tôi mua vé rồi.","hl":["уже"],"tokens":["Я","уже","купил","билеты"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"уже"},{"k":"V","t":"Động từ quá khứ"},{"k":"O","t":"(Tân ngữ)"}],"points":["Уже nghĩa là 'đã, rồi', đứng trước động từ: \"Я уже поел\" = Tôi ăn rồi.","Động từ thường ở thì quá khứ thể hoàn thành (поел, купил, пришли) để chỉ việc đã xong.","Động từ quá khứ đổi đuôi theo chủ ngữ: он купил, она купила, мы купили.","Hỏi 'đã... chưa?' chỉ cần lên giọng: \"Вы уже поели?\"; trả lời 'chưa' là \"Ещё нет\"."],"mistakes":[{"wrong":"Она уже купил билеты.","right":"Она уже купила билеты.","why":"Chủ ngữ là nữ thì động từ quá khứ phải thêm -а: купила."},{"wrong":"Мы уже пришёл.","right":"Мы уже пришли.","why":"Chủ ngữ số nhiều (мы, вы, они) thì động từ quá khứ có đuôi -ли."}],"compare":"Tiếng Việt đặt 'rồi' cuối câu (Tôi ăn rồi), còn tiếng Nga đặt уже trước động từ (Я уже поел); động từ quá khứ còn phải đổi đuôi theo giống và số.","tip":"'Rồi' ở cuối câu tiếng Việt → nhảy lên thành уже ('u-GIÊ') đứng ngay trước động từ.","how":["Thêm уже trước động từ quá khứ поел → уже поел, rồi đặt chủ ngữ Я lên đầu → Я уже поел.","Thêm уже trước động từ số nhiều пришли → уже пришли, rồi đặt chủ ngữ Мы lên đầu → Мы уже пришли.","Thêm уже trước купил → уже купил, đặt Я lên đầu và tân ngữ билеты ở cuối → Я уже купил билеты."],"dialog":[{"who":"A","t":"Вы уже поели?","ph":"VY u-ZHE pa-YE-li","vi":"Anh ăn chưa?","hl":["уже"]},{"who":"B","t":"Да, я уже поел. А вы?","ph":"DA YA u-ZHE pa-YEL a VY","vi":"Rồi, tôi ăn rồi. Còn anh?","hl":["уже"]},{"who":"A","t":"Ещё нет. Я очень голодный.","ph":"ye-SHCHO NYET YA O-chen ga-LOD-niy","vi":"Chưa. Tôi đói lắm.","hl":[]},{"who":"B","t":"Ресторан уже открыт.","ph":"ris-ta-RAN u-ZHE at-KRYT","vi":"Nhà hàng mở cửa rồi đấy.","hl":["уже"]}],"more":[{"t":"Он уже спит.","ph":"ON u-ZHE SPIT","vi":"Anh ấy ngủ rồi.","hl":["уже"],"tokens":["Он","уже","спит"]},{"t":"Такси уже приехало.","ph":"tak-SI u-ZHE pri-YE-kha-la","vi":"Taxi đến rồi.","hl":["уже"],"tokens":["Такси","уже","приехало"]},{"t":"Она уже купила подарок.","ph":"a-NA u-ZHE ku-PI-la pa-DA-rak","vi":"Cô ấy mua quà rồi.","hl":["уже"],"tokens":["Она","уже","купила","подарок"]},{"t":"Магазин уже закрылся.","ph":"ma-ga-ZIN u-ZHE za-KRYL-sya","vi":"Cửa hàng đóng cửa rồi.","hl":["уже"],"tokens":["Магазин","уже","закрылся"]},{"t":"Вы уже заказали ужин?","ph":"VY u-ZHE za-ka-ZA-li U-zhin","vi":"Anh chị gọi món bữa tối chưa?","hl":["уже"],"tokens":["Вы","уже","заказали","ужин"]},{"t":"Мы уже были в Петербурге.","ph":"MY u-ZHE BY-li f pi-tir-BUR-ge","vi":"Chúng tôi từng đến Petersburg rồi.","hl":["уже"],"tokens":["Мы","уже","были","в","Петербурге"]}]},{"id":21,"vi":"chưa","note":"'Chưa' là ещё не (vẫn chưa) đặt trước động từ hoặc tính từ; câu hỏi 'đã ... chưa?' dùng уже ...? và trả lời Ещё нет (chưa).","pivot":{"t":"ещё не","ph":"ye-SHCHO ne"},"branches":[{"steps":[{"t":"был","ph":"BYL","vi":"đã ở, đã đến","hl":[]},{"t":"ещё не был","ph":"ye-SHCHO NYE byl","vi":"chưa từng đến","hl":["ещё не"]},{"t":"Я ещё не был в Москве.","ph":"YA ye-SHCHO NYE byl v mask-VYE","vi":"Tôi chưa từng đến Moskva.","hl":["ещё не"],"tokens":["Я","ещё","не","был","в","Москве"]}]},{"steps":[{"t":"готов","ph":"ga-TOF","vi":"sẵn sàng, xong","hl":[]},{"t":"ещё не готов","ph":"ye-SHCHO ne ga-TOF","vi":"chưa xong","hl":["ещё не"]},{"t":"Ужин ещё не готов.","ph":"U-zhin ye-SHCHO ne ga-TOF","vi":"Bữa tối chưa xong.","hl":["ещё не"],"tokens":["Ужин","ещё","не","готов"]}]},{"steps":[{"t":"решили","ph":"ri-SHI-li","vi":"đã quyết định","hl":[]},{"t":"ещё не решили","ph":"ye-SHCHO ne ri-SHI-li","vi":"chưa quyết định","hl":["ещё не"]},{"t":"Вы ещё не решили?","ph":"VY ye-SHCHO ne ri-SHI-li","vi":"Anh chị chưa chọn xong à?","hl":["ещё не"],"tokens":["Вы","ещё","не","решили"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"ещё не"},{"k":"V","t":"Động từ / Tính từ"},{"k":"O","t":"(Bổ ngữ)"}],"points":["'Chưa' = ещё не (vẫn chưa), đặt ngay trước động từ hoặc tính từ: \"Ужин ещё не готов\".","Trả lời ngắn 'Chưa' thì nói \"Ещё нет\", không dùng ещё не đứng một mình.","Hỏi 'đã... chưa?' dùng уже: \"Вы уже поели?\" — trả lời Да, уже hoặc Ещё нет.","Với был, trọng âm chuyển lên не: не был đọc là NYE byl."],"mistakes":[{"wrong":"Я не ещё поел.","right":"Я ещё не поел.","why":"Trật tự cố định là ещё не, không đảo thành не ещё."},{"wrong":"Ещё не.","right":"Ещё нет.","why":"Khi trả lời trống không 'Chưa' phải dùng Ещё нет; ещё не luôn cần động từ hoặc tính từ theo sau."}],"compare":"Giống tiếng Việt: 'chưa' đứng trước động từ (chưa đến → ещё не был); khác ở chỗ tiếng Nga dùng hai từ ещё (vẫn) + не (không), và câu trả lời ngắn đổi thành Ещё нет.","tip":"Ещё не = 'vẫn không' = 'chưa'. Trả lời cụt lủn thì đổi не thành нет: Ещё нет!","how":["Thêm ещё не trước động từ quá khứ был → ещё не был, đặt Я lên đầu và nơi chốn в Москве ở cuối → Я ещё не был в Москве.","Thêm ещё не trước tính từ ngắn готов → ещё не готов, rồi đặt chủ ngữ Ужин lên đầu → Ужин ещё не готов.","Thêm ещё не trước động từ решили → ещё не решили, đặt Вы lên đầu và lên giọng hỏi → Вы ещё не решили?"],"dialog":[{"who":"A","t":"Вы уже заказали?","ph":"VY u-ZHE za-ka-ZA-li","vi":"Anh chị gọi món chưa?","hl":[]},{"who":"B","t":"Ещё нет. Мы ещё не решили.","ph":"ye-SHCHO NYET MY ye-SHCHO ne ri-SHI-li","vi":"Chưa. Chúng tôi chưa chọn xong.","hl":["ещё не"]},{"who":"A","t":"Хорошо. Вы ещё не были у нас?","ph":"kha-ra-SHO VY ye-SHCHO NYE by-li u NAS","vi":"Vâng. Anh chị chưa đến quán chúng tôi lần nào à?","hl":["ещё не"]},{"who":"B","t":"Нет, мы здесь первый раз.","ph":"NYET MY ZDES' PYER-viy RAS","vi":"Chưa, đây là lần đầu chúng tôi đến.","hl":[]}],"more":[{"t":"Он ещё не пришёл.","ph":"ON ye-SHCHO ne pri-SHOL","vi":"Anh ấy chưa đến.","hl":["ещё не"],"tokens":["Он","ещё","не","пришёл"]},{"t":"Я ещё не знаю.","ph":"YA ye-SHCHO ne ZNA-yu","vi":"Tôi chưa biết.","hl":["ещё не"],"tokens":["Я","ещё","не","знаю"]},{"t":"Номер ещё не готов.","ph":"NO-mir ye-SHCHO ne ga-TOF","vi":"Phòng chưa sẵn sàng.","hl":["ещё не"],"tokens":["Номер","ещё","не","готов"]},{"t":"Мы ещё не купили билеты.","ph":"MY ye-SHCHO ne ku-PI-li bi-LYE-ty","vi":"Chúng tôi chưa mua vé.","hl":["ещё не"],"tokens":["Мы","ещё","не","купили","билеты"]},{"t":"Она ещё не видела Красную площадь.","ph":"a-NA ye-SHCHO ne VI-de-la KRAS-nu-yu PLO-shchat'","vi":"Cô ấy chưa từng thấy Quảng trường Đỏ.","hl":["ещё не"],"tokens":["Она","ещё","не","видела","Красную","площадь"]},{"t":"Поезд ещё не ушёл, мы успеем.","ph":"PO-ist ye-SHCHO ne u-SHOL MY us-PYE-yem","vi":"Tàu chưa chạy, chúng ta kịp mà.","hl":["ещё не"],"tokens":["Поезд","ещё","не","ушёл,","мы","успеем"]}]},{"id":22,"vi":"rất","note":"Очень (rất) đứng trước tính từ hoặc trạng từ, không đổi hình thức; tính từ vẫn hợp giống với danh từ (дорогой отель).","pivot":{"t":"очень","ph":"O-chen"},"branches":[{"steps":[{"t":"вкусно","ph":"FKUS-na","vi":"ngon","hl":[]},{"t":"очень вкусно","ph":"O-chen FKUS-na","vi":"rất ngon","hl":["очень"]},{"t":"Это очень вкусно.","ph":"E-ta O-chen FKUS-na","vi":"Cái này rất ngon.","hl":["очень"],"tokens":["Это","очень","вкусно"]}]},{"steps":[{"t":"красиво","ph":"kra-SI-va","vi":"đẹp","hl":[]},{"t":"очень красиво","ph":"O-chen kra-SI-va","vi":"rất đẹp","hl":["очень"]},{"t":"Здесь очень красиво.","ph":"ZDES' O-chen kra-SI-va","vi":"Ở đây rất đẹp.","hl":["очень"],"tokens":["Здесь","очень","красиво"]}]},{"steps":[{"t":"дорогой","ph":"da-ra-GOY","vi":"đắt","hl":[]},{"t":"очень дорогой","ph":"O-chen da-ra-GOY","vi":"rất đắt","hl":["очень"]},{"t":"Этот отель очень дорогой.","ph":"E-tat a-TEL' O-chen da-ra-GOY","vi":"Khách sạn này rất đắt.","hl":["очень"],"tokens":["Этот","отель","очень","дорогой"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"очень"},{"k":"A","t":"Tính từ / Trạng từ"}],"points":["Очень đứng trước tính từ hoặc trạng từ: очень вкусно, очень красивый.","Очень không đổi hình thức, nhưng tính từ sau nó phải hợp giống với danh từ (очень дорогой отель, очень дорогая сумка).","Trạng từ đuôi -о (вкусно, красиво) dùng sau Это / Здесь để nhận xét chung.","Очень còn đứng trước động từ: \"Я очень люблю чай\" = Tôi rất thích trà."],"mistakes":[{"wrong":"Это вкусно очень.","right":"Это очень вкусно.","why":"Очень luôn đứng trước tính từ, không đặt sau như 'ngon lắm' trong tiếng Việt."},{"wrong":"Эта сумка очень дорогой.","right":"Эта сумка очень дорогая.","why":"Сумка là danh từ giống cái nên tính từ phải có đuôi -ая."}],"compare":"Giống 'rất' tiếng Việt: đứng trước tính từ (rất ngon = очень вкусно); khác với 'lắm' đứng sau — tiếng Nga luôn đặt очень phía trước.","tip":"Очень đọc 'Ô-chần' — 'Ô' lên vì quá đẹp, quá ngon! Và luôn 'Ô' trước từ mình khen.","how":["Thêm очень trước trạng từ вкусно → очень вкусно, rồi đặt Это lên đầu → Это очень вкусно.","Thêm очень trước trạng từ красиво → очень красиво, rồi đặt Здесь (ở đây) lên đầu → Здесь очень красиво.","Thêm очень trước tính từ giống đực дорогой → очень дорогой, rồi đặt chủ ngữ Этот отель lên đầu → Этот отель очень дорогой."],"dialog":[{"who":"A","t":"Как вам Москва?","ph":"KAK VAM mask-VA","vi":"Anh thấy Moskva thế nào?","hl":[]},{"who":"B","t":"Очень красивый город!","ph":"O-chen kra-SI-viy GO-rat","vi":"Thành phố rất đẹp!","hl":["Очень"]},{"who":"A","t":"А погода?","ph":"a pa-GO-da","vi":"Còn thời tiết?","hl":[]},{"who":"B","t":"Очень холодно, но мне нравится.","ph":"O-chen KHO-lad-na no MNYE NRA-vit-sa","vi":"Rất lạnh, nhưng tôi thích.","hl":["Очень"]}],"more":[{"t":"Чай очень горячий.","ph":"CHAY O-chen ga-RYA-chiy","vi":"Trà rất nóng.","hl":["очень"],"tokens":["Чай","очень","горячий"]},{"t":"Вы очень добрый.","ph":"VY O-chen DOB-riy","vi":"Anh rất tốt bụng.","hl":["очень"],"tokens":["Вы","очень","добрый"]},{"t":"Я очень устал.","ph":"YA O-chen us-TAL","vi":"Tôi rất mệt.","hl":["очень"],"tokens":["Я","очень","устал"]},{"t":"Эта улица очень длинная.","ph":"E-ta U-li-tsa O-chen DLIN-na-ya","vi":"Con phố này rất dài.","hl":["очень"],"tokens":["Эта","улица","очень","длинная"]},{"t":"Мне очень нравится этот город.","ph":"MNYE O-chen NRA-vit-sa E-tat GO-rat","vi":"Tôi rất thích thành phố này.","hl":["очень"],"tokens":["Мне","очень","нравится","этот","город"]},{"t":"Спасибо, вы нам очень помогли.","ph":"spa-SI-ba VY NAM O-chen pa-mag-LI","vi":"Cảm ơn, anh đã giúp chúng tôi rất nhiều.","hl":["очень"],"tokens":["Спасибо,","вы","нам","очень","помогли"]}]},{"id":23,"vi":"quá","note":"'Quá' (vượt mức) là слишком, đứng trước tính từ/trạng từ; khác với очень (rất), слишком mang ý chê, không mong muốn.","pivot":{"t":"слишком","ph":"SLISH-kam"},"branches":[{"steps":[{"t":"дорого","ph":"DO-ra-ga","vi":"đắt","hl":[]},{"t":"слишком дорого","ph":"SLISH-kam DO-ra-ga","vi":"đắt quá","hl":["слишком"]},{"t":"Это слишком дорого.","ph":"E-ta SLISH-kam DO-ra-ga","vi":"Cái này đắt quá.","hl":["слишком"],"tokens":["Это","слишком","дорого"]}]},{"steps":[{"t":"быстро","ph":"BYS-tra","vi":"nhanh","hl":[]},{"t":"слишком быстро","ph":"SLISH-kam BYS-tra","vi":"nhanh quá","hl":["слишком"]},{"t":"Вы говорите слишком быстро.","ph":"VY ga-va-RI-te SLISH-kam BYS-tra","vi":"Anh nói nhanh quá.","hl":["слишком"],"tokens":["Вы","говорите","слишком","быстро"]}]},{"steps":[{"t":"жарко","ph":"ZHAR-ka","vi":"nóng","hl":[]},{"t":"слишком жарко","ph":"SLISH-kam ZHAR-ka","vi":"nóng quá","hl":["слишком"]},{"t":"Сегодня слишком жарко.","ph":"si-VOD-nya SLISH-kam ZHAR-ka","vi":"Hôm nay nóng quá.","hl":["слишком"],"tokens":["Сегодня","слишком","жарко"]}]}],"formula":[{"k":"S","t":"(Chủ ngữ)"},{"k":"P","t":"слишком"},{"k":"A","t":"Tính từ / Trạng từ"}],"points":["Слишком = quá (vượt mức mong muốn), đứng trước tính từ hoặc trạng từ: слишком дорого.","Слишком mang ý chê, không hài lòng; khen 'ngon quá!' thì dùng очень: \"Очень вкусно!\".","'Quá nhiều' là слишком много: \"Здесь слишком много людей\".","Câu về thời tiết, cảm giác không cần chủ ngữ: \"Слишком жарко\" = Nóng quá."],"mistakes":[{"wrong":"Это слишком вкусно!","right":"Это очень вкусно!","why":"Khen 'ngon quá' không dùng слишком, vì слишком nghĩa là 'quá mức, không tốt'."},{"wrong":"Это дорого слишком.","right":"Это слишком дорого.","why":"Слишком phải đứng trước tính từ/trạng từ, không đặt sau như 'đắt quá' tiếng Việt."}],"compare":"Tiếng Việt đặt 'quá' sau tính từ (đắt quá), tiếng Nga đặt слишком trước (слишком дорого); 'quá' tiếng Việt có thể là lời khen, còn слишком gần như luôn là lời chê.","tip":"Слишком đọc 'SLÍT-cầm' — nghe như 'xin lỗi, quá mức rồi'! Chê thì слишком, khen thì очень.","how":["Thêm слишком trước trạng từ дорого → слишком дорого, rồi đặt Это lên đầu → Это слишком дорого.","Thêm слишком trước trạng từ быстро → слишком быстро, rồi đặt chủ ngữ và động từ Вы говорите lên trước → Вы говорите слишком быстро.","Thêm слишком trước trạng từ жарко → слишком жарко, rồi đặt Сегодня (hôm nay) lên đầu → Сегодня слишком жарко."],"dialog":[{"who":"A","t":"Сколько стоит эта сумка?","ph":"SKOL'-ka STO-it E-ta SUM-ka","vi":"Cái túi này bao nhiêu tiền?","hl":[]},{"who":"B","t":"Пять тысяч рублей.","ph":"PYAT' TY-syach rub-LYEY","vi":"Năm nghìn rúp.","hl":[]},{"who":"A","t":"Это слишком дорого для меня.","ph":"E-ta SLISH-kam DO-ra-ga DLYA mi-NYA","vi":"Đắt quá đối với tôi.","hl":["слишком"]},{"who":"B","t":"Вот эта не слишком дорогая.","ph":"VOT E-ta ne SLISH-kam da-ra-GA-ya","vi":"Cái này thì không đắt quá đâu.","hl":["слишком"]}],"more":[{"t":"Суп слишком солёный.","ph":"SUP SLISH-kam sa-LYO-niy","vi":"Súp mặn quá.","hl":["слишком"],"tokens":["Суп","слишком","солёный"]},{"t":"Здесь слишком шумно.","ph":"ZDES' SLISH-kam SHUM-na","vi":"Ở đây ồn quá.","hl":["слишком"],"tokens":["Здесь","слишком","шумно"]},{"t":"Музыка слишком громкая.","ph":"MU-zy-ka SLISH-kam GROM-ka-ya","vi":"Nhạc to quá.","hl":["слишком"],"tokens":["Музыка","слишком","громкая"]},{"t":"Эти туфли слишком маленькие.","ph":"E-ti TUF-li SLISH-kam MA-lin'-ki-ye","vi":"Đôi giày này nhỏ quá.","hl":["слишком"],"tokens":["Эти","туфли","слишком","маленькие"]},{"t":"Сегодня я слишком устал.","ph":"si-VOD-nya YA SLISH-kam us-TAL","vi":"Hôm nay tôi mệt quá.","hl":["слишком"],"tokens":["Сегодня","я","слишком","устал"]},{"t":"В автобусе слишком много людей.","ph":"f af-TO-bu-se SLISH-kam MNO-ga lyu-DYEY","vi":"Trên xe buýt đông người quá.","hl":["слишком"],"tokens":["В","автобусе","слишком","много","людей"]}]},{"id":24,"vi":"hơn","note":"So sánh hơn thường thêm đuôi -ее vào tính từ (быстрый → быстрее), một số từ bất quy tắc (хорошо → лучше, дёшево → дешевле, много → больше); vật so sánh để ở cách sở hữu (быстрее автобуса) hoặc sau чем.","pivot":{"t":"больше","ph":"BOL'-she"},"branches":[{"steps":[{"t":"быстро","ph":"BYS-tra","vi":"nhanh","hl":[]},{"t":"быстрее автобуса","ph":"byst-RYE-ye af-TO-bu-sa","vi":"nhanh hơn xe buýt","hl":["быстрее"]},{"t":"Поезд быстрее автобуса.","ph":"PO-ist byst-RYE-ye af-TO-bu-sa","vi":"Tàu hỏa nhanh hơn xe buýt.","hl":["быстрее"],"tokens":["Поезд","быстрее","автобуса"]}]},{"steps":[{"t":"дёшево","ph":"DYO-she-va","vi":"rẻ","hl":[]},{"t":"что-нибудь дешевле","ph":"SHTO-ni-bud' di-SHEV-lye","vi":"cái gì rẻ hơn","hl":["дешевле"]},{"t":"Есть что-нибудь дешевле?","ph":"YEST' SHTO-ni-bud' di-SHEV-lye","vi":"Có cái nào rẻ hơn không?","hl":["дешевле"],"tokens":["Есть","что-нибудь","дешевле"]}]},{"steps":[{"t":"нравится","ph":"NRA-vit-sa","vi":"thích","hl":[]},{"t":"больше нравится","ph":"BOL'-she NRA-vit-sa","vi":"thích hơn","hl":["больше"]},{"t":"Мне больше нравится чай.","ph":"MNYE BOL'-she NRA-vit-sa CHAY","vi":"Tôi thích trà hơn.","hl":["больше"],"tokens":["Мне","больше","нравится","чай"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"больше / -ее"},{"k":"O","t":"(чем) Vật được so sánh"}],"points":["So sánh hơn của tính từ: thêm đuôi -ее vào gốc (быстрый → быстрее, интересный → интереснее).","Một số từ bất quy tắc cần học thuộc: хорошо → лучше, плохо → хуже, дёшево → дешевле, дорого → дороже, много → больше.","Vật bị so sánh đặt ngay sau ở cách sở hữu (быстрее автобуса) hoặc sau чем, có dấu phẩy (быстрее, чем автобус).","Больше còn nghĩa 'nhiều hơn / thích hơn' khi đứng trước động từ: \"Мне больше нравится чай\"."],"mistakes":[{"wrong":"Поезд больше быстро автобуса.","right":"Поезд быстрее автобуса.","why":"Không ghép больше + tính từ như 'nhanh hơn' tiếng Việt; dùng luôn dạng so sánh быстрее."},{"wrong":"Это более хорошо.","right":"Это лучше.","why":"Хорошо là từ bất quy tắc: 'tốt hơn' là лучше."}],"compare":"Tiếng Việt thêm 'hơn' sau tính từ (nhanh hơn), tiếng Nga đổi luôn đuôi tính từ (быстрее); vật so sánh đứng ngay sau ở cách sở hữu mà không cần từ 'hơn' riêng.","tip":"Học thuộc nhóm bất quy tắc 'Lút-Hu-Đề': лучше (tốt hơn), хуже (tệ hơn), дешевле (rẻ hơn) — còn lại cứ gắn -ее!","how":["Đổi быстро thành dạng so sánh быстрее, thêm vật so sánh ở cách sở hữu автобуса → быстрее автобуса, rồi đặt Поезд lên đầu → Поезд быстрее автобуса.","Đổi дёшево thành dạng bất quy tắc дешевле, thêm что-нибудь (cái gì đó) phía trước → что-нибудь дешевле, rồi mở đầu bằng Есть để hỏi → Есть что-нибудь дешевле?","Thêm больше trước нравится → больше нравится (thích hơn), rồi đặt Мне lên đầu và thứ được thích чай ở cuối → Мне больше нравится чай."],"dialog":[{"who":"A","t":"Как лучше ехать в центр?","ph":"KAK LUCH-she YE-khat' f TSENTR","vi":"Đi vào trung tâm bằng gì thì tốt hơn?","hl":["лучше"]},{"who":"B","t":"На метро, это быстрее и дешевле.","ph":"na mit-RO E-ta byst-RYE-ye i di-SHEV-lye","vi":"Đi tàu điện ngầm, vừa nhanh hơn vừa rẻ hơn.","hl":["быстрее","дешевле"]},{"who":"A","t":"Я больше люблю такси.","ph":"YA BOL'-she lyub-LYU tak-SI","vi":"Tôi thích đi taxi hơn.","hl":["больше"]},{"who":"B","t":"Такси удобнее, но дороже.","ph":"tak-SI u-DOB-nye-ye no da-RO-zhe","vi":"Taxi tiện hơn nhưng đắt hơn.","hl":["удобнее","дороже"]}],"more":[{"t":"Этот номер больше.","ph":"E-tat NO-mir BOL'-she","vi":"Phòng này rộng hơn.","hl":["больше"],"tokens":["Этот","номер","больше"]},{"t":"Мой брат старше меня.","ph":"MOY BRAT STAR-she mi-NYA","vi":"Anh trai tôi lớn tuổi hơn tôi.","hl":["старше"],"tokens":["Мой","брат","старше","меня"]},{"t":"Говорите, пожалуйста, медленнее.","ph":"ga-va-RI-te pa-ZHA-lus-ta MYED-li-nye-ye","vi":"Làm ơn nói chậm hơn.","hl":["медленнее"],"tokens":["Говорите,","пожалуйста,","медленнее"]},{"t":"Сегодня теплее, чем вчера.","ph":"si-VOD-nya tip-LYE-ye chem fchi-RA","vi":"Hôm nay ấm hơn hôm qua.","hl":["теплее"],"tokens":["Сегодня","теплее,","чем","вчера"]},{"t":"Здесь дешевле, чем в центре.","ph":"ZDES' di-SHEV-lye chem f TSENT-re","vi":"Ở đây rẻ hơn ở trung tâm.","hl":["дешевле"],"tokens":["Здесь","дешевле,","чем","в","центре"]},{"t":"Летом в Сочи жарче, чем в Москве.","ph":"LYE-tam f SO-chi ZHAR-che chem v mask-VYE","vi":"Mùa hè ở Sochi nóng hơn ở Moskva.","hl":["жарче"],"tokens":["Летом","в","Сочи","жарче,","чем","в","Москве"]}]},{"id":25,"vi":"nhất","note":"So sánh nhất dùng самый + tính từ, và самый phải hợp giống, số, cách với danh từ: самый (đực), самая (cái), самое (trung).","pivot":{"t":"самый","ph":"SA-miy"},"branches":[{"steps":[{"t":"вкусный","ph":"FKUS-niy","vi":"ngon","hl":[]},{"t":"самый вкусный","ph":"SA-miy FKUS-niy","vi":"ngon nhất","hl":["самый"]},{"t":"Это самый вкусный суп.","ph":"E-ta SA-miy FKUS-niy SUP","vi":"Đây là món súp ngon nhất.","hl":["самый"],"tokens":["Это","самый","вкусный","суп"]}]},{"steps":[{"t":"дешёвая","ph":"di-SHO-va-ya","vi":"rẻ","hl":[]},{"t":"самая дешёвая","ph":"SA-ma-ya di-SHO-va-ya","vi":"rẻ nhất","hl":["самая"]},{"t":"Мне нужна самая дешёвая комната.","ph":"MNYE nuzh-NA SA-ma-ya di-SHO-va-ya KOM-na-ta","vi":"Tôi cần phòng rẻ nhất.","hl":["самая"],"tokens":["Мне","нужна","самая","дешёвая","комната"]}]},{"steps":[{"t":"красивое","ph":"kra-SI-va-ye","vi":"đẹp","hl":[]},{"t":"самое красивое","ph":"SA-ma-ye kra-SI-va-ye","vi":"đẹp nhất","hl":["самое"]},{"t":"Это самое красивое место.","ph":"E-ta SA-ma-ye kra-SI-va-ye MYES-ta","vi":"Đây là nơi đẹp nhất.","hl":["самое"],"tokens":["Это","самое","красивое","место"]}]}],"formula":[{"k":"P","t":"самый / самая / самое"},{"k":"A","t":"Tính từ (cùng giống)"},{"k":"O","t":"Danh từ"}],"points":["So sánh nhất = самый + tính từ: самый вкусный (ngon nhất).","Самый và tính từ đều hợp giống, số với danh từ: самый (đực), самая (cái), самое (trung), самые (số nhiều).","Cụm самый + tính từ đứng trước danh từ: самая дешёвая комната (phòng rẻ nhất).","'... nhất ở đâu' thêm в + cách giới từ: \"самый большой город в России\"."],"mistakes":[{"wrong":"Это самый красивое место.","right":"Это самое красивое место.","why":"Место là danh từ giống trung nên самый cũng phải đổi thành самое."},{"wrong":"Это вкусный самый суп.","right":"Это самый вкусный суп.","why":"Самый đứng trước tính từ, không đặt sau như 'ngon nhất' tiếng Việt."}],"compare":"Tiếng Việt đặt danh từ trước rồi mới đến 'ngon nhất' (món súp ngon nhất), tiếng Nga đặt самый + tính từ trước danh từ (самый вкусный суп) và phải hợp giống.","tip":"Самый đọc 'XA-mưi' — 'nhất' phải đứng trước! Đuôi của самый luôn 'bắt chước' đuôi tính từ: -ый/-ая/-ое.","how":["Thêm самый trước tính từ giống đực вкусный → самый вкусный, rồi đặt Это lên đầu và danh từ суп ở cuối → Это самый вкусный суп.","Thêm самая (giống cái) trước дешёвая → самая дешёвая, rồi mở đầu bằng Мне нужна và đặt комната ở cuối → Мне нужна самая дешёвая комната.","Thêm самое (giống trung) trước красивое → самое красивое, rồi đặt Это lên đầu và место ở cuối → Это самое красивое место."],"dialog":[{"who":"A","t":"Какой ресторан здесь самый хороший?","ph":"ka-KOY ris-ta-RAN ZDES' SA-miy kha-RO-shiy","vi":"Nhà hàng nào ở đây ngon nhất?","hl":["самый"]},{"who":"B","t":"Вот этот. Он самый популярный.","ph":"VOT E-tat ON SA-miy pa-pu-LYAR-niy","vi":"Quán này đây. Nó nổi tiếng nhất.","hl":["самый"]},{"who":"A","t":"А какое блюдо самое вкусное?","ph":"a ka-KO-ye BLYU-da SA-ma-ye FKUS-na-ye","vi":"Còn món nào ngon nhất?","hl":["самое"]},{"who":"B","t":"Пельмени, конечно.","ph":"pil'-MYE-ni ka-NYESH-na","vi":"Pelmeni, tất nhiên rồi.","hl":[]}],"more":[{"t":"Это самая длинная река.","ph":"E-ta SA-ma-ya DLIN-na-ya ri-KA","vi":"Đây là con sông dài nhất.","hl":["самая"],"tokens":["Это","самая","длинная","река"]},{"t":"Он самый умный в классе.","ph":"ON SA-miy UM-niy f KLA-se","vi":"Cậu ấy thông minh nhất lớp.","hl":["самый"],"tokens":["Он","самый","умный","в","классе"]},{"t":"Где самый близкий банкомат?","ph":"GDYE SA-miy BLIS-kiy ban-ka-MAT","vi":"Cây ATM gần nhất ở đâu?","hl":["самый"],"tokens":["Где","самый","близкий","банкомат"]},{"t":"Мы купили самые дешёвые билеты.","ph":"MY ku-PI-li SA-my-ye di-SHO-vy-ye bi-LYE-ty","vi":"Chúng tôi đã mua vé rẻ nhất.","hl":["самые"],"tokens":["Мы","купили","самые","дешёвые","билеты"]},{"t":"Сегодня самый холодный день года.","ph":"si-VOD-nya SA-miy kha-LOD-niy DYEN' GO-da","vi":"Hôm nay là ngày lạnh nhất trong năm.","hl":["самый"],"tokens":["Сегодня","самый","холодный","день","года"]},{"t":"Это самое старое здание в городе.","ph":"E-ta SA-ma-ye STA-ra-ye ZDA-ni-ye v GO-ra-de","vi":"Đây là tòa nhà cổ nhất trong thành phố.","hl":["самое"],"tokens":["Это","самое","старое","здание","в","городе"]}]},{"id":26,"vi":"cũng","note":"Тоже (cũng) đứng sau chủ ngữ, trước động từ hoặc vị ngữ, không biến đổi: Я тоже... = Tôi cũng...","pivot":{"t":"тоже","ph":"TO-zhe"},"branches":[{"steps":[{"t":"хочу","ph":"ha-CHU","vi":"muốn","hl":[]},{"t":"тоже хочу","ph":"TO-zhe ha-CHU","vi":"cũng muốn","hl":["тоже"]},{"t":"Я тоже хочу кофе.","ph":"YA TO-zhe ha-CHU KO-fe","vi":"Tôi cũng muốn uống cà phê.","hl":["тоже"],"tokens":["Я","тоже","хочу","кофе"]}]},{"steps":[{"t":"студент","ph":"stu-DYENT","vi":"sinh viên","hl":[]},{"t":"тоже студент","ph":"TO-zhe stu-DYENT","vi":"cũng là sinh viên","hl":["тоже"]},{"t":"Мой друг тоже студент.","ph":"MOY DRUK TO-zhe stu-DYENT","vi":"Bạn tôi cũng là sinh viên.","hl":["тоже"],"tokens":["Мой","друг","тоже","студент"]}]},{"steps":[{"t":"устал","ph":"us-TAL","vi":"mệt","hl":[]},{"t":"тоже устал","ph":"TO-zhe us-TAL","vi":"cũng mệt","hl":["тоже"]},{"t":"Я тоже устал.","ph":"YA TO-zhe us-TAL","vi":"Tôi cũng mệt.","hl":["тоже"],"tokens":["Я","тоже","устал"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"P","t":"тоже"},{"k":"V","t":"Động từ / Vị ngữ"},{"k":"O","t":"(Tân ngữ)"}],"points":["Тоже (cũng) đứng ngay sau chủ ngữ, trước động từ hoặc vị ngữ: \"Я тоже хочу\".","Тоже không biến đổi theo giống, số hay ngôi.","Trả lời ngắn 'Tôi cũng vậy' chỉ cần nói \"Я тоже\".","Câu 'Tôi cũng là sinh viên' không cần động từ 'là': \"Я тоже студент\"."],"mistakes":[{"wrong":"Я тоже есть студент.","right":"Я тоже студент.","why":"Ở thì hiện tại tiếng Nga bỏ động từ 'là', không dịch 'là' thành есть."},{"wrong":"Тоже я хочу кофе.","right":"Я тоже хочу кофе.","why":"Тоже đứng sau chủ ngữ giống 'cũng' tiếng Việt, không đặt ở đầu câu."}],"compare":"Rất giống tiếng Việt: тоже nằm đúng chỗ của 'cũng' (Tôi cũng muốn = Я тоже хочу); khác ở chỗ tiếng Nga bỏ chữ 'là'.","tip":"Тоже đọc 'TÔ-giê' và nằm đúng chỗ chữ 'cũng' — dịch từng chữ mà vẫn đúng: Tôi cũng mệt = Я тоже устал!","how":["Thêm тоже trước động từ хочу → тоже хочу, đặt Я lên đầu và кофе ở cuối → Я тоже хочу кофе.","Thêm тоже trước danh từ студент → тоже студент, rồi đặt chủ ngữ Мой друг lên đầu (không cần 'là') → Мой друг тоже студент.","Thêm тоже trước устал → тоже устал, rồi đặt chủ ngữ Я lên đầu → Я тоже устал."],"dialog":[{"who":"A","t":"Я иду в кафе.","ph":"YA i-DU f ka-FE","vi":"Tôi đi quán cà phê đây.","hl":[]},{"who":"B","t":"Я тоже! Пойдём вместе.","ph":"YA TO-zhe pa-DYOM VMYES-te","vi":"Tôi cũng vậy! Đi cùng nhau đi.","hl":["тоже"]},{"who":"A","t":"Ты будешь капучино?","ph":"TY BU-dish' ka-pu-CHI-na","vi":"Bạn uống cappuccino không?","hl":[]},{"who":"B","t":"Да, и мой брат тоже будет.","ph":"DA i MOY BRAT TO-zhe BU-dit","vi":"Có, em trai tôi cũng uống.","hl":["тоже"]}],"more":[{"t":"Мне тоже холодно.","ph":"MNYE TO-zhe KHO-lad-na","vi":"Tôi cũng thấy lạnh.","hl":["тоже"],"tokens":["Мне","тоже","холодно"]},{"t":"Мы тоже из Вьетнама.","ph":"MY TO-zhe iz vyet-NA-ma","vi":"Chúng tôi cũng đến từ Việt Nam.","hl":["тоже"],"tokens":["Мы","тоже","из","Вьетнама"]},{"t":"Моя сестра тоже врач.","ph":"ma-YA sist-RA TO-zhe VRACH","vi":"Chị tôi cũng là bác sĩ.","hl":["тоже"],"tokens":["Моя","сестра","тоже","врач"]},{"t":"Она тоже говорит по-русски.","ph":"a-NA TO-zhe ga-va-RIT pa-RUS-ki","vi":"Cô ấy cũng nói tiếng Nga.","hl":["тоже"],"tokens":["Она","тоже","говорит","по-русски"]},{"t":"Я тоже люблю русскую кухню.","ph":"YA TO-zhe lyub-LYU RUS-ku-yu KUKH-nyu","vi":"Tôi cũng thích ẩm thực Nga.","hl":["тоже"],"tokens":["Я","тоже","люблю","русскую","кухню"]},{"t":"Мы тоже хотим поехать на экскурсию.","ph":"MY TO-zhe kha-TIM pa-YE-khat' na eks-KUR-si-yu","vi":"Chúng tôi cũng muốn đi tham quan.","hl":["тоже"],"tokens":["Мы","тоже","хотим","поехать","на","экскурсию"]}]},{"id":27,"vi":"và","note":"И (và) nối hai từ hoặc hai vế cùng loại, không cần dấu phẩy khi nối hai từ; hai danh từ nối bằng и làm chủ ngữ thì động từ/tính từ đi kèm chia số nhiều (нужны).","pivot":{"t":"и","ph":"I"},"branches":[{"steps":[{"t":"чай","ph":"CHAY","vi":"trà","hl":[]},{"t":"чай и кофе","ph":"CHAY i KO-fe","vi":"trà và cà phê","hl":["и"]},{"t":"Я люблю чай и кофе.","ph":"YA lyub-LYU CHAY i KO-fe","vi":"Tôi thích trà và cà phê.","hl":["и"],"tokens":["Я","люблю","чай","и","кофе"]}]},{"steps":[{"t":"мама","ph":"MA-ma","vi":"mẹ","hl":[]},{"t":"мама и папа","ph":"MA-ma i PA-pa","vi":"mẹ và bố","hl":["и"]},{"t":"Это мои мама и папа.","ph":"E-ta ma-I MA-ma i PA-pa","vi":"Đây là mẹ và bố của tôi.","hl":["и"],"tokens":["Это","мои","мама","и","папа"]}]},{"steps":[{"t":"хлеб","ph":"KHLYEP","vi":"bánh mì","hl":[]},{"t":"хлеб и вода","ph":"KHLYEP i va-DA","vi":"bánh mì và nước","hl":["и"]},{"t":"Нам нужны хлеб и вода.","ph":"NAM nuzh-NY KHLYEP i va-DA","vi":"Chúng ta cần bánh mì và nước.","hl":["и"],"tokens":["Нам","нужны","хлеб","и","вода"]}]}],"formula":[{"k":"O","t":"Từ / Vế 1"},{"k":"P","t":"и"},{"k":"O","t":"Từ / Vế 2"}],"points":["И nối hai từ hoặc hai vế cùng loại, giống 'và': чай и кофе.","Khi и nối hai từ đơn thì không có dấu phẩy trước и.","Hai danh từ nối bằng и làm chủ ngữ thì động từ/tính từ đi kèm chia số nhiều: \"Нам нужны хлеб и вода\".","И còn nối hai động từ cùng chủ ngữ: \"Мы гуляли и фотографировали\"."],"mistakes":[{"wrong":"Я люблю чай, и кофе.","right":"Я люблю чай и кофе.","why":"Khi и nối hai từ đơn thì không đặt dấu phẩy trước и."},{"wrong":"Это мой мама и папа.","right":"Это мои мама и папа.","why":"Nói về hai người (mẹ và bố) thì đại từ sở hữu phải ở số nhiều: мои."}],"compare":"Giống hệt 'và' tiếng Việt: и đứng giữa hai từ cần nối (trà và cà phê = чай и кофе); khác ở chỗ từ đi kèm phải chia số nhiều (мои, нужны).","tip":"И chỉ có một chữ cái, đọc 'i' — gọn như chữ 'và' viết tắt trong tin nhắn!","how":["Bắt đầu từ чай, thêm и кофе → чай и кофе, rồi đặt Я люблю lên trước → Я люблю чай и кофе.","Bắt đầu từ мама, thêm и папа → мама и папа, rồi đặt Это мои (đây là ... của tôi, số nhiều) lên trước → Это мои мама и папа.","Bắt đầu từ хлеб, thêm и вода → хлеб и вода, rồi đặt Нам нужны (số nhiều vì có hai thứ) lên trước → Нам нужны хлеб и вода."],"dialog":[{"who":"A","t":"Что вы будете заказывать?","ph":"SHTO vy BU-di-te za-KA-zy-vat'","vi":"Anh chị gọi món gì ạ?","hl":[]},{"who":"B","t":"Борщ и салат, пожалуйста.","ph":"BORSHCH i sa-LAT pa-ZHA-lus-ta","vi":"Cho tôi súp borscht và salad.","hl":["и"]},{"who":"A","t":"А пить?","ph":"a PIT'","vi":"Còn đồ uống?","hl":[]},{"who":"B","t":"Чай и воду без газа.","ph":"CHAY i VO-du bis GA-za","vi":"Trà và nước không ga.","hl":["и"]}],"more":[{"t":"Анна и Иван дома.","ph":"AN-na i i-VAN DO-ma","vi":"Anna và Ivan đang ở nhà.","hl":["и"],"tokens":["Анна","и","Иван","дома"]},{"t":"Здесь тихо и чисто.","ph":"ZDES' TI-kha i CHIS-ta","vi":"Ở đây yên tĩnh và sạch sẽ.","hl":["и"],"tokens":["Здесь","тихо","и","чисто"]},{"t":"Купите хлеб и молоко.","ph":"ku-PI-te KHLYEP i ma-la-KO","vi":"Hãy mua bánh mì và sữa.","hl":["и"],"tokens":["Купите","хлеб","и","молоко"]},{"t":"Мы гуляли и фотографировали.","ph":"MY gu-LYA-li i fa-ta-gra-FI-ra-va-li","vi":"Chúng tôi đi dạo và chụp ảnh.","hl":["и"],"tokens":["Мы","гуляли","и","фотографировали"]},{"t":"Я говорю по-английски и по-русски.","ph":"YA ga-va-RYU pa-ang-LIY-ski i pa-RUS-ki","vi":"Tôi nói tiếng Anh và tiếng Nga.","hl":["и"],"tokens":["Я","говорю","по-английски","и","по-русски"]},{"t":"Я принял душ и пошёл спать.","ph":"YA PRI-nyal DUSH i pa-SHOL SPAT'","vi":"Tôi tắm xong rồi đi ngủ.","hl":["и"],"tokens":["Я","принял","душ","и","пошёл","спать"]}]},{"id":28,"vi":"nhưng","note":"Но (nhưng) nối hai ý trái ngược; trong tiếng Nga bắt buộc có dấu phẩy trước но.","pivot":{"t":"но","ph":"NO"},"branches":[{"steps":[{"t":"дорого","ph":"DO-ra-ga","vi":"đắt","hl":[]},{"t":"но дорого","ph":"no DO-ra-ga","vi":"nhưng đắt","hl":["но"]},{"t":"Здесь вкусно, но дорого.","ph":"ZDES' FKUS-na no DO-ra-ga","vi":"Ở đây ngon nhưng đắt.","hl":["но"],"tokens":["Здесь","вкусно,","но","дорого"]}]},{"steps":[{"t":"уютный","ph":"u-YUT-niy","vi":"ấm cúng","hl":[]},{"t":"но уютный","ph":"no u-YUT-niy","vi":"nhưng ấm cúng","hl":["но"]},{"t":"Номер маленький, но уютный.","ph":"NO-mir MA-lin'-kiy no u-YUT-niy","vi":"Phòng nhỏ nhưng ấm cúng.","hl":["но"],"tokens":["Номер","маленький,","но","уютный"]}]},{"steps":[{"t":"понимаю","ph":"pa-ni-MA-yu","vi":"hiểu","hl":[]},{"t":"но понимаю","ph":"no pa-ni-MA-yu","vi":"nhưng hiểu","hl":["но"]},{"t":"Я плохо говорю, но понимаю.","ph":"YA PLO-kha ga-va-RYU no pa-ni-MA-yu","vi":"Tôi nói kém nhưng hiểu được.","hl":["но"],"tokens":["Я","плохо","говорю,","но","понимаю"]}]}],"formula":[{"k":"O","t":"Vế 1,"},{"k":"P","t":"но"},{"k":"O","t":"Vế 2 (ý trái ngược)"}],"points":["Но nối hai ý trái ngược, giống 'nhưng': вкусно, но дорого.","Trước но luôn có dấu phẩy, kể cả khi chỉ nối hai tính từ hoặc trạng từ.","Vế sau но có thể rút gọn, không cần lặp lại chủ ngữ: \"Я плохо говорю, но понимаю\".","Đừng nhầm но (nhưng) với а (còn): а chỉ đối chiếu nhẹ hai sự việc (\"Я пью чай, а он кофе\")."],"mistakes":[{"wrong":"Здесь вкусно но дорого.","right":"Здесь вкусно, но дорого.","why":"Tiếng Nga bắt buộc có dấu phẩy trước но."},{"wrong":"Я русский, но он вьетнамец.","right":"Я русский, а он вьетнамец.","why":"Khi chỉ đối chiếu hai người hay hai sự việc (nghĩa 'còn') thì dùng а, không dùng но."}],"compare":"Vị trí giống 'nhưng' tiếng Việt, nằm giữa hai vế (ngon nhưng đắt = вкусно, но дорого); khác ở chỗ tiếng Nga bắt buộc phải có dấu phẩy trước но.","tip":"Но đọc 'nô' giống 'no' tiếng Anh — báo hiệu ý ngược lại sắp tới; và nó luôn 'dắt theo' một dấu phẩy phía trước!","how":["Thêm но trước дорого → но дорого, rồi đặt vế Здесь вкусно kèm dấu phẩy lên trước → Здесь вкусно, но дорого.","Thêm но trước уютный → но уютный, rồi đặt vế Номер маленький kèm dấu phẩy lên trước → Номер маленький, но уютный.","Thêm но trước понимаю → но понимаю, rồi đặt vế Я плохо говорю kèm dấu phẩy lên trước → Я плохо говорю, но понимаю."],"dialog":[{"who":"A","t":"Вы говорите по-русски?","ph":"VY ga-va-RI-te pa-RUS-ki","vi":"Anh nói được tiếng Nga không?","hl":[]},{"who":"B","t":"Немного, но плохо.","ph":"nim-NO-ga no PLO-kha","vi":"Một chút, nhưng kém lắm.","hl":["но"]},{"who":"A","t":"Не страшно. Русский трудный, но интересный.","ph":"ne STRASH-na RUS-kiy TRUD-niy no in-ti-RYES-niy","vi":"Không sao. Tiếng Nga khó nhưng thú vị.","hl":["но"]},{"who":"B","t":"Да, очень интересный!","ph":"DA O-chen in-ti-RYES-niy","vi":"Đúng, rất thú vị!","hl":[]}],"more":[{"t":"Я хочу, но не могу.","ph":"YA kha-CHU no ne ma-GU","vi":"Tôi muốn nhưng không thể.","hl":["но"],"tokens":["Я","хочу,","но","не","могу"]},{"t":"Отель старый, но чистый.","ph":"a-TEL' STA-riy no CHIS-tiy","vi":"Khách sạn cũ nhưng sạch.","hl":["но"],"tokens":["Отель","старый,","но","чистый"]},{"t":"Извините, но я занят.","ph":"iz-vi-NI-te no YA ZA-nyat","vi":"Xin lỗi, nhưng tôi đang bận.","hl":["но"],"tokens":["Извините,","но","я","занят"]},{"t":"Погода хорошая, но холодно.","ph":"pa-GO-da kha-RO-sha-ya no KHO-lad-na","vi":"Thời tiết đẹp nhưng lạnh.","hl":["но"],"tokens":["Погода","хорошая,","но","холодно"]},{"t":"Мы опоздали, но поезд ещё стоял.","ph":"MY a-paz-DA-li no PO-ist ye-SHCHO sta-YAL","vi":"Chúng tôi đến muộn nhưng tàu vẫn còn đỗ.","hl":["но"],"tokens":["Мы","опоздали,","но","поезд","ещё","стоял"]},{"t":"Билеты дорогие, но концерт того стоит.","ph":"bi-LYE-ty da-ra-GI-ye no kan-TSERT ta-VO STO-it","vi":"Vé đắt nhưng buổi hòa nhạc rất đáng tiền.","hl":["но"],"tokens":["Билеты","дорогие,","но","концерт","того","стоит"]}]},{"id":29,"vi":"nếu","note":"Если (nếu) mở đầu mệnh đề điều kiện, luôn ngăn cách bằng dấu phẩy; 'thì' là то nhưng thường lược bỏ. Điều kiện ở tương lai dùng thì tương lai (будет дождь, опоздаю).","pivot":{"t":"если","ph":"YES-li"},"branches":[{"steps":[{"t":"дождь","ph":"DOZHT'","vi":"mưa","hl":[]},{"t":"если будет дождь","ph":"YES-li BU-dit DOZHT'","vi":"nếu trời mưa","hl":["если"]},{"t":"Мы останемся дома, если будет дождь.","ph":"MY as-TA-nim-sya DO-ma YES-li BU-dit DOZHT'","vi":"Nếu trời mưa thì chúng ta sẽ ở nhà.","hl":["если"],"tokens":["Мы","останемся","дома,","если","будет","дождь"]}]},{"steps":[{"t":"можно","ph":"MOZH-na","vi":"được, có thể","hl":[]},{"t":"если можно","ph":"YES-li MOZH-na","vi":"nếu được","hl":["если"]},{"t":"Дайте счёт, если можно.","ph":"DAY-te SHCHOT YES-li MOZH-na","vi":"Nếu được thì cho tôi hóa đơn.","hl":["если"],"tokens":["Дайте","счёт,","если","можно"]}]},{"steps":[{"t":"опоздаю","ph":"a-paz-DA-yu","vi":"đến muộn","hl":[]},{"t":"если опоздаю","ph":"YES-li a-paz-DA-yu","vi":"nếu tôi đến muộn","hl":["если"]},{"t":"Я позвоню, если опоздаю.","ph":"YA pa-zva-NYU YES-li a-paz-DA-yu","vi":"Nếu tôi đến muộn thì tôi sẽ gọi.","hl":["если"],"tokens":["Я","позвоню,","если","опоздаю"]}]}],"formula":[{"k":"P","t":"если"},{"k":"O","t":"Điều kiện,"},{"k":"O","t":"(то) Kết quả"}],"points":["Если (nếu) mở đầu mệnh đề điều kiện; mệnh đề này có thể đứng đầu hoặc cuối câu.","Luôn có dấu phẩy ngăn cách mệnh đề если với mệnh đề chính.","'Thì' là то, có thể dùng khi если đứng đầu câu nhưng thường được lược bỏ: \"Если будет дождь, (то) мы останемся дома\".","Điều kiện ở tương lai thì động từ sau если cũng chia ở tương lai (если будет дождь, если опоздаю)."],"mistakes":[{"wrong":"Если есть дождь, мы останемся дома.","right":"Если будет дождь, мы останемся дома.","why":"Nói về tương lai thì mệnh đề если cũng phải ở thì tương lai (будет)."},{"wrong":"Я позвоню если опоздаю.","right":"Я позвоню, если опоздаю.","why":"Phải có dấu phẩy trước если khi nó nối hai mệnh đề."}],"compare":"Giống 'nếu... thì...' tiếng Việt; khác ở chỗ 'thì' (то) thường bị lược bỏ, bắt buộc có dấu phẩy, và chuyện tương lai phải chia tương lai ở cả hai vế.","tip":"Если đọc 'DÉ-xli'. Mẹo: 'nếu' đi đâu, dấu phẩy theo đó — если không bao giờ đi một mình!","how":["Từ дождь, thêm если будет (nếu sẽ có) phía trước → если будет дождь, rồi đặt vế kết quả Мы останемся дома kèm dấu phẩy lên trước → Мы останемся дома, если будет дождь.","Thêm если trước можно → если можно (nếu được), rồi đặt lời đề nghị Дайте счёт kèm dấu phẩy lên trước → Дайте счёт, если можно.","Thêm если trước động từ tương lai опоздаю → если опоздаю, rồi đặt vế Я позвоню kèm dấu phẩy lên trước → Я позвоню, если опоздаю."],"dialog":[{"who":"A","t":"Если будет время, пойдём в музей?","ph":"YES-li BU-dit VRYE-mya pa-DYOM v mu-ZYEY","vi":"Nếu có thời gian thì mình đi bảo tàng nhé?","hl":["Если"]},{"who":"B","t":"Да, если не будет дождя.","ph":"DA YES-li ne BU-dit dazh-DYA","vi":"Ừ, nếu trời không mưa.","hl":["если"]},{"who":"A","t":"Отлично! Я куплю билеты.","ph":"at-LICH-na YA kup-LYU bi-LYE-ty","vi":"Tuyệt! Tôi sẽ mua vé.","hl":[]}],"more":[{"t":"Если хотите, я помогу.","ph":"YES-li kha-TI-te YA pa-ma-GU","vi":"Nếu anh muốn, tôi sẽ giúp.","hl":["Если"],"tokens":["Если","хотите,","я","помогу"]},{"t":"Если можно, говорите медленнее.","ph":"YES-li MOZH-na ga-va-RI-te MYED-li-nye-ye","vi":"Nếu được thì anh nói chậm hơn nhé.","hl":["Если"],"tokens":["Если","можно,","говорите","медленнее"]},{"t":"Если будет холодно, возьми куртку.","ph":"YES-li BU-dit KHO-lad-na vaz'-MI KURT-ku","vi":"Nếu trời lạnh thì mang theo áo khoác.","hl":["Если"],"tokens":["Если","будет","холодно,","возьми","куртку"]},{"t":"Если вы устали, давайте отдохнём.","ph":"YES-li vy us-TA-li da-VAY-te at-dakh-NYOM","vi":"Nếu anh mệt thì chúng ta nghỉ một chút.","hl":["Если"],"tokens":["Если","вы","устали,","давайте","отдохнём"]},{"t":"Мы пойдём на пляж, если будет солнце.","ph":"MY pa-DYOM na PLYASH YES-li BU-dit SON-tse","vi":"Chúng ta sẽ ra biển nếu trời nắng.","hl":["если"],"tokens":["Мы","пойдём","на","пляж,","если","будет","солнце"]},{"t":"Если поезд опоздает, мы возьмём такси.","ph":"YES-li PO-ist a-paz-DA-yet MY vaz'-MYOM tak-SI","vi":"Nếu tàu đến muộn, chúng ta sẽ đi taxi.","hl":["Если"],"tokens":["Если","поезд","опоздает,","мы","возьмём","такси"]}]},{"id":30,"vi":"này / kia","note":"Этот (này) và тот (kia) đứng trước danh từ và hợp giống: этот/эта/это, тот/та/то; riêng это đứng một mình nghĩa là 'đây là, cái này'.","pivot":{"t":"этот","ph":"E-tat"},"branches":[{"steps":[{"t":"автобус","ph":"af-TO-bus","vi":"xe buýt","hl":[]},{"t":"этот автобус","ph":"E-tat af-TO-bus","vi":"xe buýt này","hl":["этот"]},{"t":"Куда идёт этот автобус?","ph":"ku-DA i-DYOT E-tat af-TO-bus","vi":"Xe buýt này đi đâu?","hl":["этот"],"tokens":["Куда","идёт","этот","автобус"]}]},{"steps":[{"t":"платье","ph":"PLAT-ye","vi":"cái váy","hl":[]},{"t":"это платье","ph":"E-ta PLAT-ye","vi":"cái váy này","hl":["это"]},{"t":"Сколько стоит это платье?","ph":"SKOL'-ka STO-it E-ta PLAT-ye","vi":"Cái váy này giá bao nhiêu?","hl":["это"],"tokens":["Сколько","стоит","это","платье"]}]},{"steps":[{"t":"торт","ph":"TORT","vi":"bánh ngọt","hl":[]},{"t":"тот торт","ph":"TOT TORT","vi":"cái bánh kia","hl":["тот"]},{"t":"Дайте мне тот торт.","ph":"DAY-te MNYE TOT TORT","vi":"Cho tôi cái bánh kia.","hl":["тот"],"tokens":["Дайте","мне","тот","торт"]}]}],"formula":[{"k":"P","t":"этот / эта / это (тот)"},{"k":"O","t":"Danh từ"},{"k":"V","t":"(Vị ngữ)"}],"points":["Этот (này) đứng trước danh từ và hợp giống: этот автобус (đực), эта сумка (cái), это платье (trung), эти билеты (số nhiều).","Тот (kia) cũng đổi theo giống: тот, та, то, те.","Это đứng một mình đầu câu nghĩa là 'đây là / cái này': \"Это мой паспорт\".","Sau động từ, этот/тот đổi cách theo danh từ: \"Я возьму эту сумку\"."],"mistakes":[{"wrong":"Сколько стоит этот платье?","right":"Сколько стоит это платье?","why":"Платье là danh từ giống trung nên phải dùng это, không phải этот."},{"wrong":"Автобус этот идёт в центр?","right":"Этот автобус идёт в центр?","why":"Этот đứng trước danh từ, không đặt sau như 'xe buýt này' tiếng Việt."}],"compare":"Tiếng Việt đặt 'này/kia' sau danh từ (xe buýt này), tiếng Nga đặt этот/тот trước danh từ (этот автобус) và phải hợp giống.","tip":"Этот = 'này' ở gần, тот = 'kia' ở xa — bỏ chữ 'э' đi là đẩy đồ vật ra xa!","how":["Thêm этот (giống đực) trước автобус → этот автобус, rồi đặt Куда идёт (đi đâu) lên trước → Куда идёт этот автобус?","Thêm это (giống trung) trước платье → это платье, rồi đặt Сколько стоит (giá bao nhiêu) lên trước → Сколько стоит это платье?","Thêm тот (kia, giống đực) trước торт → тот торт, rồi đặt Дайте мне (cho tôi) lên trước → Дайте мне тот торт."],"dialog":[{"who":"A","t":"Это место свободно?","ph":"E-ta MYES-ta sa-BOD-na","vi":"Chỗ này còn trống không?","hl":["Это"]},{"who":"B","t":"Нет, это место занято. Но то свободно.","ph":"NYET E-ta MYES-ta ZA-nya-ta no TO sa-BOD-na","vi":"Không, chỗ này có người rồi. Nhưng chỗ kia trống.","hl":["это","то"]},{"who":"A","t":"Спасибо! А этот рюкзак ваш?","ph":"spa-SI-ba a E-tat ryuk-ZAK VASH","vi":"Cảm ơn! Thế cái ba lô này của anh à?","hl":["этот"]},{"who":"B","t":"Да, мой. Сейчас уберу.","ph":"DA MOY sey-CHAS u-bi-RU","vi":"Vâng, của tôi. Để tôi cất ngay.","hl":[]}],"more":[{"t":"Я возьму эту сумку.","ph":"YA vaz'-MU E-tu SUM-ku","vi":"Tôi lấy cái túi này.","hl":["эту"],"tokens":["Я","возьму","эту","сумку"]},{"t":"Тот дом очень старый.","ph":"TOT DOM O-chen STA-riy","vi":"Ngôi nhà kia rất cũ.","hl":["Тот"],"tokens":["Тот","дом","очень","старый"]},{"t":"Эти билеты на завтра.","ph":"E-ti bi-LYE-ty na ZAF-tra","vi":"Những vé này là cho ngày mai.","hl":["Эти"],"tokens":["Эти","билеты","на","завтра"]},{"t":"Эта комната очень светлая.","ph":"E-ta KOM-na-ta O-chen SVYET-la-ya","vi":"Căn phòng này rất sáng.","hl":["Эта"],"tokens":["Эта","комната","очень","светлая"]},{"t":"Как называется эта улица?","ph":"KAK na-zy-VA-yet-sya E-ta U-li-tsa","vi":"Con phố này tên là gì?","hl":["эта"],"tokens":["Как","называется","эта","улица"]},{"t":"Вы видите ту большую церковь?","ph":"VY VI-di-te TU bal'-SHU-yu TSER-kaf'","vi":"Anh có thấy nhà thờ lớn kia không?","hl":["ту"],"tokens":["Вы","видите","ту","большую","церковь"]}]},{"id":31,"vi":"của","note":"'Của tôi/bạn' dùng đại từ sở hữu đứng trước danh từ và hợp giống: мой/моя/моё, твой, ваш/ваша; 'của người khác' thì đặt danh từ ở cách sở hữu sau (машина брата).","pivot":{"t":"мой","ph":"MOY"},"branches":[{"steps":[{"t":"паспорт","ph":"PAS-part","vi":"hộ chiếu","hl":[]},{"t":"мой паспорт","ph":"MOY PAS-part","vi":"hộ chiếu của tôi","hl":["мой"]},{"t":"Где мой паспорт?","ph":"GDYE MOY PAS-part","vi":"Hộ chiếu của tôi đâu?","hl":["мой"],"tokens":["Где","мой","паспорт"]}]},{"steps":[{"t":"сумка","ph":"SUM-ka","vi":"cái túi","hl":[]},{"t":"ваша сумка","ph":"VA-sha SUM-ka","vi":"túi của anh chị","hl":["ваша"]},{"t":"Это ваша сумка?","ph":"E-ta VA-sha SUM-ka","vi":"Đây là túi của anh chị phải không?","hl":["ваша"],"tokens":["Это","ваша","сумка"]}]},{"steps":[{"t":"номер","ph":"NO-mir","vi":"số","hl":[]},{"t":"твой номер","ph":"TVOY NO-mir","vi":"số của bạn","hl":["твой"]},{"t":"Какой твой номер телефона?","ph":"ka-KOY TVOY NO-mir ti-li-FO-na","vi":"Số điện thoại của bạn là gì?","hl":["твой"],"tokens":["Какой","твой","номер","телефона"]}]}],"formula":[{"k":"P","t":"мой / ваш / твой"},{"k":"O","t":"Danh từ"}],"points":["Đại từ sở hữu đứng trước danh từ: мой паспорт = hộ chiếu của tôi.","Nó hợp giống với vật được sở hữu, không phải người sở hữu: мой паспорт, моя сумка, моё место, мои вещи.","Ваш/ваша (của anh chị, lịch sự) và твой/твоя (của bạn, thân mật) cũng đổi đuôi như vậy.","'Của người khác' thì đặt người đó ở cách sở hữu sau danh từ: машина брата (xe của anh trai)."],"mistakes":[{"wrong":"Где паспорт я?","right":"Где мой паспорт?","why":"Không dịch 'của tôi' bằng я đặt sau; dùng мой đứng trước danh từ."},{"wrong":"Это мой сумка.","right":"Это моя сумка.","why":"Сумка là danh từ giống cái nên phải dùng моя."}],"compare":"Tiếng Việt đặt 'của tôi' sau danh từ (hộ chiếu của tôi), tiếng Nga đặt мой trước (мой паспорт) và không cần từ 'của'.","tip":"Мой đọc 'MOI' như 'mới' — đồ của tôi luôn mới! Đuôi đổi theo đồ vật: мой / моя / моё.","how":["Thêm мой trước паспорт (giống đực) → мой паспорт, rồi đặt Где (ở đâu) lên đầu → Где мой паспорт?","Thêm ваша (giống cái, lịch sự) trước сумка → ваша сумка, rồi đặt Это lên đầu và lên giọng hỏi → Это ваша сумка?","Thêm твой trước номер → твой номер, đặt Какой (gì, nào) lên đầu và телефона ở cuối → Какой твой номер телефона?"],"dialog":[{"who":"A","t":"Извините, это ваше место?","ph":"iz-vi-NI-te E-ta VA-she MYES-ta","vi":"Xin lỗi, đây là chỗ của anh à?","hl":["ваше"]},{"who":"B","t":"Нет, моё место у окна.","ph":"NYET ma-YO MYES-ta u ak-NA","vi":"Không, chỗ của tôi ở cạnh cửa sổ.","hl":["моё"]},{"who":"A","t":"Хорошо. А это ваш чемодан?","ph":"kha-ra-SHO a E-ta VASH chi-ma-DAN","vi":"Vâng. Còn đây là va li của anh à?","hl":["ваш"]},{"who":"B","t":"Да, мой. Спасибо!","ph":"DA MOY spa-SI-ba","vi":"Vâng, của tôi. Cảm ơn!","hl":["мой"]}],"more":[{"t":"Это моя жена.","ph":"E-ta ma-YA zhi-NA","vi":"Đây là vợ tôi.","hl":["моя"],"tokens":["Это","моя","жена"]},{"t":"Где ваш багаж?","ph":"GDYE VASH ba-GASH","vi":"Hành lý của anh đâu?","hl":["ваш"],"tokens":["Где","ваш","багаж"]},{"t":"Мой телефон не работает.","ph":"MOY ti-li-FON ne ra-BO-ta-yet","vi":"Điện thoại của tôi bị hỏng.","hl":["Мой"],"tokens":["Мой","телефон","не","работает"]},{"t":"Твоя сестра очень красивая.","ph":"tva-YA sist-RA O-chen kra-SI-va-ya","vi":"Em gái bạn rất xinh.","hl":["Твоя"],"tokens":["Твоя","сестра","очень","красивая"]},{"t":"Мои друзья живут в Москве.","ph":"ma-I druz'-YA zhi-VUT v mask-VYE","vi":"Bạn bè tôi sống ở Moskva.","hl":["Мои"],"tokens":["Мои","друзья","живут","в","Москве"]},{"t":"Это машина моего брата.","ph":"E-ta ma-SHI-na ma-ye-VO BRA-ta","vi":"Đây là xe của anh trai tôi.","hl":["моего"],"tokens":["Это","машина","моего","брата"]}]},{"id":32,"vi":"ở / tại","note":"'Ở, tại' là в (trong) hoặc на (trên, ở nơi mở/sự kiện như вокзал, работа), danh từ sau đó chuyển sang cách giới từ, thường đuôi -е (гостиница → в гостинице).","pivot":{"t":"в","ph":"V"},"branches":[{"steps":[{"t":"гостинице","ph":"ga-STI-ni-tse","vi":"khách sạn","hl":[]},{"t":"в гостинице","ph":"v ga-STI-ni-tse","vi":"ở khách sạn","hl":["в"]},{"t":"Я живу в гостинице.","ph":"YA zhi-VU v ga-STI-ni-tse","vi":"Tôi ở khách sạn.","hl":["в"],"tokens":["Я","живу","в","гостинице"]}]},{"steps":[{"t":"вокзале","ph":"vag-ZA-le","vi":"nhà ga","hl":[]},{"t":"на вокзале","ph":"na vag-ZA-le","vi":"ở nhà ga","hl":["на"]},{"t":"Мы встретимся на вокзале.","ph":"MY VSTRYE-tim-sya na vag-ZA-le","vi":"Chúng ta sẽ gặp nhau ở nhà ga.","hl":["на"],"tokens":["Мы","встретимся","на","вокзале"]}]},{"steps":[{"t":"работе","ph":"ra-BO-te","vi":"chỗ làm","hl":[]},{"t":"на работе","ph":"na ra-BO-te","vi":"ở chỗ làm","hl":["на"]},{"t":"Папа сейчас на работе.","ph":"PA-pa sey-CHAS na ra-BO-te","vi":"Bố đang ở chỗ làm.","hl":["на"],"tokens":["Папа","сейчас","на","работе"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"в / на"},{"k":"O","t":"Nơi chốn (đuôi -е)"}],"points":["'Ở, tại' dùng в cho nơi kín, có ranh giới: в гостинице, в Москве, в магазине.","Dùng на cho nơi mở hoặc sự kiện, hoạt động: на вокзале, на работе, на концерте, на улице.","Danh từ sau в/на chuyển sang cách giới từ, thường đổi đuôi thành -е: Москва → в Москве, банк → в банке.","Hỏi 'ở đâu' dùng Где: \"Где вы живёте?\" — trả lời bằng в hoặc на."],"mistakes":[{"wrong":"Я живу в гостиница.","right":"Я живу в гостинице.","why":"Sau в chỉ nơi chốn, danh từ phải đổi đuôi sang cách giới từ (-е)."},{"wrong":"Он сейчас в работе.","right":"Он сейчас на работе.","why":"Работа (chỗ làm) đi với на, không đi với в — cần học thuộc những từ đi với на."}],"compare":"Tiếng Việt chỉ cần 'ở' + nơi chốn (ở khách sạn), còn tiếng Nga phải chọn в hay на và đổi đuôi danh từ (в гостинице).","tip":"В = 'vào trong' (trong nhà, trong thành phố); на = 'nằm trên' (sân ga, đường phố, buổi hòa nhạc).","how":["Đổi гостиница sang cách giới từ гостинице, thêm в phía trước → в гостинице, rồi đặt Я живу lên trước → Я живу в гостинице.","Đổi вокзал thành вокзале, thêm на (nơi công cộng mở) → на вокзале, rồi đặt Мы встретимся lên trước → Мы встретимся на вокзале.","Đổi работа thành работе, thêm на → на работе, rồi đặt Папа сейчас lên trước → Папа сейчас на работе."],"dialog":[{"who":"A","t":"Где ты сейчас?","ph":"GDYE ty sey-CHAS","vi":"Bạn đang ở đâu?","hl":[]},{"who":"B","t":"Я в кафе на Арбате.","ph":"YA f ka-FE na ar-BA-te","vi":"Tôi ở quán cà phê trên phố Arbat.","hl":["в","на"]},{"who":"A","t":"Отлично, я рядом, в магазине.","ph":"at-LICH-na YA RYA-dam v ma-ga-ZI-ne","vi":"Tuyệt, tôi ở gần đó, trong cửa hàng.","hl":["в"]},{"who":"B","t":"Тогда встретимся на площади.","ph":"tag-DA VSTRYE-tim-sya na PLO-shcha-di","vi":"Vậy hẹn gặp ở quảng trường nhé.","hl":["на"]}],"more":[{"t":"Мама на кухне.","ph":"MA-ma na KUKH-nye","vi":"Mẹ ở trong bếp.","hl":["на"],"tokens":["Мама","на","кухне"]},{"t":"Он работает в банке.","ph":"ON ra-BO-ta-yet v BAN-ke","vi":"Anh ấy làm việc ở ngân hàng.","hl":["в"],"tokens":["Он","работает","в","банке"]},{"t":"Дети играют на улице.","ph":"DYE-ti ig-RA-yut na U-li-tse","vi":"Bọn trẻ chơi ngoài đường.","hl":["на"],"tokens":["Дети","играют","на","улице"]},{"t":"Мы обедали в ресторане.","ph":"MY a-BYE-da-li v ris-ta-RA-ne","vi":"Chúng tôi ăn trưa ở nhà hàng.","hl":["в"],"tokens":["Мы","обедали","в","ресторане"]},{"t":"Вчера я был на концерте.","ph":"fchi-RA YA BYL na kan-TSER-te","vi":"Hôm qua tôi đi xem hòa nhạc.","hl":["на"],"tokens":["Вчера","я","был","на","концерте"]},{"t":"Моя сестра учится в университете.","ph":"ma-YA sist-RA U-chit-sya v u-ni-vir-si-TYE-te","vi":"Em gái tôi học ở trường đại học.","hl":["в"],"tokens":["Моя","сестра","учится","в","университете"]}]},{"id":33,"vi":"với","note":"'Với, cùng' là с (trước một số cụm phụ âm thành со) + danh từ/đại từ ở cách công cụ: друг → с другом, я → со мной, молоко → с молоком.","pivot":{"t":"с","ph":"S"},"branches":[{"steps":[{"t":"другом","ph":"DRU-gam","vi":"bạn","hl":[]},{"t":"с другом","ph":"z DRU-gam","vi":"với bạn","hl":["с"]},{"t":"Я путешествую с другом.","ph":"YA pu-ti-SHEST-vu-yu z DRU-gam","vi":"Tôi đi du lịch với bạn.","hl":["с"],"tokens":["Я","путешествую","с","другом"]}]},{"steps":[{"t":"мной","ph":"MNOY","vi":"tôi","hl":[]},{"t":"со мной","ph":"sa MNOY","vi":"với tôi","hl":["со"]},{"t":"Пойдёмте со мной.","ph":"pa-DYOM-te sa MNOY","vi":"Hãy đi với tôi.","hl":["со"],"tokens":["Пойдёмте","со","мной"]}]},{"steps":[{"t":"молоком","ph":"ma-la-KOM","vi":"sữa","hl":[]},{"t":"с молоком","ph":"s ma-la-KOM","vi":"với sữa","hl":["с"]},{"t":"Мне кофе с молоком.","ph":"MNYE KO-fe s ma-la-KOM","vi":"Cho tôi cà phê sữa.","hl":["с"],"tokens":["Мне","кофе","с","молоком"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"Động từ"},{"k":"P","t":"с / со"},{"k":"O","t":"Người / Vật (cách công cụ)"}],"points":["'Với, cùng' = с + danh từ/đại từ ở cách công cụ: с другом, с мамой.","Đuôi cách công cụ: giống đực/trung thêm -ом/-ем (друг → другом), giống cái đổi thành -ой (мама → мамой).","Đại từ đổi dạng: я → со мной, ты → с тобой, он → с ним, она → с ней, мы → с нами, вы → с вами.","Với đồ ăn uống, с nghĩa là 'có kèm': кофе с молоком (cà phê sữa), чай с лимоном (trà chanh)."],"mistakes":[{"wrong":"Пойдёмте с я.","right":"Пойдёмте со мной.","why":"Đại từ sau с phải ở cách công cụ: я → мной, và с đổi thành со cho dễ đọc."},{"wrong":"Я путешествую с друг.","right":"Я путешествую с другом.","why":"Danh từ sau с phải thêm đuôi cách công cụ: друг → другом."}],"compare":"Vị trí giống 'với' tiếng Việt, đứng trước người/vật đi kèm (với bạn = с другом); khác ở chỗ danh từ sau с phải đổi đuôi.","tip":"Nhớ qua món quen: 'cà phê sữa' = кофе с молоком — sau с là đuôi -ом / -ой!","how":["Đổi друг sang cách công cụ другом, thêm с → с другом, rồi đặt Я путешествую lên trước → Я путешествую с другом.","Đổi я thành мной, thêm со (с thêm o cho dễ đọc) → со мной, rồi đặt Пойдёмте (hãy đi) lên trước → Пойдёмте со мной.","Đổi молоко thành молоком, thêm с → с молоком, rồi đặt Мне кофе (cho tôi cà phê) lên trước → Мне кофе с молоком."],"dialog":[{"who":"A","t":"Ты едешь один?","ph":"TY YE-dish' a-DIN","vi":"Bạn đi một mình à?","hl":[]},{"who":"B","t":"Нет, с женой и детьми.","ph":"NYET z zhi-NOY i dit'-MI","vi":"Không, đi với vợ và các con.","hl":["с"]},{"who":"A","t":"Можно с вами?","ph":"MOZH-na s VA-mi","vi":"Tôi đi cùng được không?","hl":["с"]},{"who":"B","t":"Конечно, поехали с нами!","ph":"ka-NYESH-na pa-YE-kha-li s NA-mi","vi":"Tất nhiên, đi với chúng tôi nào!","hl":["с"]}],"more":[{"t":"Чай с лимоном, пожалуйста.","ph":"CHAY s li-MO-nam pa-ZHA-lus-ta","vi":"Cho tôi trà chanh.","hl":["с"],"tokens":["Чай","с","лимоном,","пожалуйста"]},{"t":"Я живу с родителями.","ph":"YA zhi-VU s ra-DI-ti-lya-mi","vi":"Tôi sống với bố mẹ.","hl":["с"],"tokens":["Я","живу","с","родителями"]},{"t":"Мы ужинали с друзьями.","ph":"MY U-zhi-na-li z druz'-YA-mi","vi":"Chúng tôi ăn tối với bạn bè.","hl":["с"],"tokens":["Мы","ужинали","с","друзьями"]},{"t":"Можно поговорить с вами?","ph":"MOZH-na pa-ga-va-RIT' s VA-mi","vi":"Tôi nói chuyện với anh được không?","hl":["с"],"tokens":["Можно","поговорить","с","вами"]},{"t":"Я хочу номер с балконом.","ph":"YA kha-CHU NO-mir z bal-KO-nam","vi":"Tôi muốn phòng có ban công.","hl":["с"],"tokens":["Я","хочу","номер","с","балконом"]},{"t":"Она приехала в Москву с сестрой.","ph":"a-NA pri-YE-kha-la v mask-VU s sist-ROY","vi":"Cô ấy đến Moskva cùng em gái.","hl":["с"],"tokens":["Она","приехала","в","Москву","с","сестрой"]}]},{"id":34,"vi":"cho","note":"'Cho ai' có hai cách: для + cách sở hữu (dành cho: для мамы) hoặc đại từ/danh từ ở cách tặng cách sau động từ 'đưa' дать (дать вам = đưa cho anh).","pivot":{"t":"для","ph":"DLYA"},"branches":[{"steps":[{"t":"мамы","ph":"MA-my","vi":"mẹ","hl":[]},{"t":"для мамы","ph":"DLYA MA-my","vi":"cho mẹ","hl":["для"]},{"t":"Это подарок для мамы.","ph":"E-ta pa-DA-rak DLYA MA-my","vi":"Đây là quà cho mẹ.","hl":["для"],"tokens":["Это","подарок","для","мамы"]}]},{"steps":[{"t":"детей","ph":"di-TYEY","vi":"trẻ em","hl":[]},{"t":"для детей","ph":"DLYA di-TYEY","vi":"cho trẻ em","hl":["для"]},{"t":"Есть меню для детей?","ph":"YEST' mi-NYU DLYA di-TYEY","vi":"Có thực đơn cho trẻ em không?","hl":["для"],"tokens":["Есть","меню","для","детей"]}]},{"steps":[{"t":"вам","ph":"VAM","vi":"anh, chị (cách tặng)","hl":[]},{"t":"дать вам","ph":"DAT' VAM","vi":"đưa cho anh","hl":["дать"]},{"t":"Я могу дать вам карту.","ph":"YA ma-GU DAT' VAM KAR-tu","vi":"Tôi có thể đưa cho anh tấm bản đồ.","hl":["дать"],"tokens":["Я","могу","дать","вам","карту"]}]}],"formula":[{"k":"O","t":"Vật"},{"k":"P","t":"для"},{"k":"O","t":"Người nhận (cách sở hữu)"}],"points":["'Dành cho ai/cái gì' = для + cách sở hữu: для мамы, для детей.","Đại từ sau для cũng đổi dạng: я → для меня, ты → для тебя, мы → для нас, вы → для вас.","'Đưa, cho ai' sau động từ дать không dùng для mà đặt người nhận ở cách tặng: дать вам, дать маме.","Для còn chỉ mục đích, công dụng: \"сумка для ноутбука\" = túi đựng laptop."],"mistakes":[{"wrong":"Это подарок для мама.","right":"Это подарок для мамы.","why":"Danh từ sau для phải ở cách sở hữu: мама → мамы."},{"wrong":"Я дам для вас карту.","right":"Я дам вам карту.","why":"Với động từ 'đưa, cho' (дать) người nhận dùng cách tặng (вам), không dùng для."}],"compare":"Giống 'cho / dành cho' tiếng Việt, đứng trước người nhận (quà cho mẹ = подарок для мамы); khác ở chỗ danh từ phải đổi đuôi, và sau 'đưa' tiếng Nga bỏ luôn giới từ (дать вам).","tip":"Quà tặng, đồ dành riêng thì для; đưa tận tay (дать) thì chỉ cần đổi đuôi người nhận: вам, маме.","how":["Đổi мама sang cách sở hữu мамы, thêm для → для мамы, rồi đặt Это подарок (đây là quà) lên trước → Это подарок для мамы.","Đổi дети sang cách sở hữu детей, thêm для → для детей, rồi đặt Есть меню (có thực đơn) lên trước để hỏi → Есть меню для детей?","Đặt вам (cho anh, cách tặng) sau động từ дать → дать вам, rồi thêm Я могу phía trước và карту ở cuối → Я могу дать вам карту."],"dialog":[{"who":"A","t":"Я ищу подарок для друга.","ph":"YA i-SHCHU pa-DA-rak DLYA DRU-ga","vi":"Tôi đang tìm quà cho bạn.","hl":["для"]},{"who":"B","t":"Может быть, эта матрёшка?","ph":"MO-zhet BYT' E-ta mat-RYOSH-ka","vi":"Có lẽ con búp bê matryoshka này?","hl":[]},{"who":"A","t":"Отлично! А что-нибудь для сына?","ph":"at-LICH-na a SHTO-ni-bud' DLYA SY-na","vi":"Tuyệt! Còn có gì cho con trai tôi không?","hl":["для"]},{"who":"B","t":"Да, вот эта игрушка.","ph":"DA VOT E-ta ig-RUSH-ka","vi":"Có, món đồ chơi này đây.","hl":[]}],"more":[{"t":"Это для меня?","ph":"E-ta DLYA mi-NYA","vi":"Cái này cho tôi à?","hl":["для"],"tokens":["Это","для","меня"]},{"t":"Этот стол для нас?","ph":"E-tat STOL DLYA NAS","vi":"Bàn này dành cho chúng tôi à?","hl":["для"],"tokens":["Этот","стол","для","нас"]},{"t":"Я купил цветы для жены.","ph":"YA ku-PIL tsvi-TY DLYA zhi-NY","vi":"Tôi mua hoa cho vợ.","hl":["для"],"tokens":["Я","купил","цветы","для","жены"]},{"t":"У вас есть крем для лица?","ph":"u VAS YEST' KRYEM DLYA li-TSA","vi":"Anh chị có kem dưỡng da mặt không?","hl":["для"],"tokens":["У","вас","есть","крем","для","лица"]},{"t":"Мне нужна сумка для ноутбука.","ph":"MNYE nuzh-NA SUM-ka DLYA na-ut-BU-ka","vi":"Tôi cần một cái túi đựng laptop.","hl":["для"],"tokens":["Мне","нужна","сумка","для","ноутбука"]},{"t":"Мы забронировали номер для всей семьи.","ph":"MY za-bra-NI-ra-va-li NO-mir DLYA VSYEY sim'-YI","vi":"Chúng tôi đã đặt phòng cho cả gia đình.","hl":["для"],"tokens":["Мы","забронировали","номер","для","всей","семьи"]}]},{"id":35,"vi":"phải","note":"'Phải' có ba cách: мне надо/нужно + động từ nguyên mẫu (người ở cách tặng: мне, вам) hoặc я должен (chủ ngữ ở cách chủ, должен hợp giống: должна cho nữ).","pivot":{"t":"надо","ph":"NA-da"},"branches":[{"steps":[{"t":"идти","ph":"it-TI","vi":"đi","hl":[]},{"t":"надо идти","ph":"NA-da it-TI","vi":"phải đi","hl":["надо"]},{"t":"Мне надо идти.","ph":"MNYE NA-da it-TI","vi":"Tôi phải đi rồi.","hl":["надо"],"tokens":["Мне","надо","идти"]}]},{"steps":[{"t":"заплатить","ph":"za-pla-TIT'","vi":"trả tiền","hl":[]},{"t":"должен заплатить","ph":"DOL-zhen za-pla-TIT'","vi":"phải trả tiền","hl":["должен"]},{"t":"Я должен заплатить заранее?","ph":"YA DOL-zhen za-pla-TIT' za-RA-ni-ye","vi":"Tôi phải trả tiền trước à?","hl":["должен"],"tokens":["Я","должен","заплатить","заранее"]}]},{"steps":[{"t":"подождать","ph":"pa-dazh-DAT'","vi":"chờ","hl":[]},{"t":"нужно подождать","ph":"NUZH-na pa-dazh-DAT'","vi":"phải chờ","hl":["нужно"]},{"t":"Вам нужно подождать немного.","ph":"VAM NUZH-na pa-dazh-DAT' nim-NO-ga","vi":"Anh phải chờ một chút.","hl":["нужно"],"tokens":["Вам","нужно","подождать","немного"]}]}],"formula":[{"k":"S","t":"Người (cách tặng: мне, вам)"},{"k":"P","t":"надо / нужно"},{"k":"V","t":"Động từ nguyên mẫu"},{"k":"O","t":"(Bổ ngữ)"}],"points":["Мне надо / нужно + động từ nguyên mẫu = tôi phải/cần làm gì; người ở cách tặng: мне, тебе, нам, вам.","Надо và нужно không đổi hình thức và dùng như nhau trong văn nói.","Cách khác: Я должен + nguyên mẫu (chủ ngữ ở cách chủ); должен hợp giống: должна (nữ), должны (số nhiều).","'Không cần' là не надо / не нужно: \"Вам не надо платить\" = Anh không cần trả tiền."],"mistakes":[{"wrong":"Я надо идти.","right":"Мне надо идти.","why":"Với надо/нужно người phải ở cách tặng (мне), không dùng я."},{"wrong":"Она должен работать.","right":"Она должна работать.","why":"Должен phải hợp giống với chủ ngữ: chủ ngữ nữ thì dùng должна."}],"compare":"Tiếng Việt nói 'Tôi phải đi', còn tiếng Nga nói kiểu 'Với tôi cần đi' (Мне надо идти) — người làm ở cách tặng; chỉ với должен thì trật tự mới giống tiếng Việt (Я должен...).","tip":"'Phải' thì nhớ Мне надо chứ không phải Я надо — 'MNIÊ NA-đa', nghe như 'mê nạp đạn' rồi phải đi!","how":["Thêm надо trước động từ nguyên mẫu идти → надо идти, rồi đặt Мне (cách tặng của я) lên đầu → Мне надо идти.","Thêm должен trước заплатить → должен заплатить, đặt Я lên đầu và заранее (trước) ở cuối, lên giọng hỏi → Я должен заплатить заранее?","Thêm нужно trước подождать → нужно подождать, đặt Вам lên đầu và немного ở cuối → Вам нужно подождать немного."],"dialog":[{"who":"A","t":"Мне надо в аптеку. Где она?","ph":"MNYE NA-da v ap-TYE-ku GDYE a-NA","vi":"Tôi phải đi hiệu thuốc. Nó ở đâu?","hl":["надо"]},{"who":"B","t":"Вам нужно идти прямо, потом налево.","ph":"VAM NUZH-na it-TI PRYA-ma pa-TOM na-LYE-va","vi":"Anh cần đi thẳng, rồi rẽ trái.","hl":["нужно"]},{"who":"A","t":"Далеко?","ph":"da-li-KO","vi":"Có xa không?","hl":[]},{"who":"B","t":"Нет, но вам надо спешить.","ph":"NYET no VAM NA-da spi-SHIT'","vi":"Không xa, nhưng anh phải nhanh lên.","hl":["надо"]}],"more":[{"t":"Мне надо позвонить.","ph":"MNYE NA-da pa-zva-NIT'","vi":"Tôi phải gọi điện.","hl":["надо"],"tokens":["Мне","надо","позвонить"]},{"t":"Тебе нужно отдохнуть.","ph":"ti-BYE NUZH-na at-dakh-NUT'","vi":"Bạn cần nghỉ ngơi.","hl":["нужно"],"tokens":["Тебе","нужно","отдохнуть"]},{"t":"Нам надо купить воду.","ph":"NAM NA-da ku-PIT' VO-du","vi":"Chúng ta phải mua nước.","hl":["надо"],"tokens":["Нам","надо","купить","воду"]},{"t":"Она должна работать завтра.","ph":"a-NA dalzh-NA ra-BO-tat' ZAF-tra","vi":"Ngày mai cô ấy phải làm việc.","hl":["должна"],"tokens":["Она","должна","работать","завтра"]},{"t":"Вам не надо платить за вход.","ph":"VAM ne NA-da pla-TIT' za FKHOT","vi":"Anh không cần trả tiền vào cửa.","hl":["надо"],"tokens":["Вам","не","надо","платить","за","вход"]},{"t":"Мы должны быть в аэропорту в шесть.","ph":"MY dalzh-NY BYT' v a-e-ra-par-TU f SHEST'","vi":"Chúng ta phải có mặt ở sân bay lúc sáu giờ.","hl":["должны"],"tokens":["Мы","должны","быть","в","аэропорту","в","шесть"]}]},{"id":36,"vi":"thử","note":"'Thử' là попробовать + danh từ (nếm thử) hoặc + động từ (thử làm); thử quần áo dùng động từ riêng примерить.","pivot":{"t":"попробовать","ph":"pa-PRO-ba-vat'"},"branches":[{"steps":[{"t":"борщ","ph":"BORSHCH","vi":"món borscht","hl":[]},{"t":"попробовать борщ","ph":"pa-PRO-ba-vat' BORSHCH","vi":"thử món borscht","hl":["попробовать"]},{"t":"Я хочу попробовать борщ.","ph":"YA ha-CHU pa-PRO-ba-vat' BORSHCH","vi":"Tôi muốn ăn thử món borscht.","hl":["попробовать"],"tokens":["Я","хочу","попробовать","борщ"]}]},{"steps":[{"t":"куртку","ph":"KURT-ku","vi":"áo khoác","hl":[]},{"t":"примерить эту куртку","ph":"pri-MYE-rit' E-tu KURT-ku","vi":"thử cái áo khoác này","hl":["примерить"]},{"t":"Можно примерить эту куртку?","ph":"MOZH-na pri-MYE-rit' E-tu KURT-ku","vi":"Tôi mặc thử cái áo khoác này được không?","hl":["примерить"],"tokens":["Можно","примерить","эту","куртку"]}]},{"steps":[{"t":"позвонить","ph":"pa-zva-NIT'","vi":"gọi điện","hl":[]},{"t":"попробую позвонить","ph":"pa-PRO-bu-yu pa-zva-NIT'","vi":"thử gọi điện","hl":["попробую"]},{"t":"Я попробую позвонить ему.","ph":"YA pa-PRO-bu-yu pa-zva-NIT' ye-MU","vi":"Tôi sẽ thử gọi cho anh ấy.","hl":["попробую"],"tokens":["Я","попробую","позвонить","ему"]}]}],"formula":[{"k":"S","t":"Chủ ngữ"},{"k":"V","t":"(Muốn / Có thể)"},{"k":"P","t":"попробовать"},{"k":"O","t":"Món ăn / Động từ"}],"points":["Попробовать + danh từ ở cách đối cách = nếm thử: попробовать борщ.","Попробовать + động từ nguyên mẫu = thử làm gì: \"Я попробую позвонить\".","Chia ở tương lai: я попробую, мы попробуем, вы попробуете; mời ai thử thì nói \"Попробуйте!\".","Thử quần áo, giày dép dùng động từ riêng примерить: \"Можно примерить?\"."],"mistakes":[{"wrong":"Можно попробовать эту куртку?","right":"Можно примерить эту куртку?","why":"Thử đồ để mặc dùng примерить; попробовать chỉ dùng cho đồ ăn uống hoặc thử làm việc gì."},{"wrong":"Я попробовать позвонить ему.","right":"Я попробую позвонить ему.","why":"Sau chủ ngữ phải chia động từ: я попробую, không để nguyên mẫu."}],"compare":"Tiếng Việt dùng 'thử' cho mọi thứ (ăn thử, mặc thử, làm thử), tiếng Nga tách ra: попробовать cho ăn uống và thử làm việc, còn примерить cho quần áo.","tip":"Ăn thử, làm thử: 'pa-PRÔ-ba' (попробовать); mặc thử: 'pri-MIÊ-rit' (примерить) — ăn bằng miệng, mặc bằng người!","how":["Thêm попробовать trước món ăn борщ → попробовать борщ, rồi đặt Я хочу lên trước → Я хочу попробовать борщ.","Vì là quần áo nên dùng примерить: thêm примерить эту trước куртку → примерить эту куртку, rồi mở đầu bằng Можно để xin phép → Можно примерить эту куртку?","Chia попробовать ở ngôi 'tôi' thành попробую, thêm trước позвонить → попробую позвонить, rồi đặt Я lên đầu và ему ở cuối → Я попробую позвонить ему."],"dialog":[{"who":"A","t":"Хотите попробовать пельмени?","ph":"kha-TI-te pa-PRO-ba-vat' pil'-MYE-ni","vi":"Anh muốn ăn thử pelmeni không?","hl":["попробовать"]},{"who":"B","t":"Да, с удовольствием!","ph":"DA s u-da-VOL'-stvi-yem","vi":"Có, rất sẵn lòng!","hl":[]},{"who":"A","t":"Попробуйте со сметаной.","ph":"pa-PRO-buy-te sa smi-TA-noy","vi":"Anh ăn thử với kem chua nhé.","hl":["Попробуйте"]},{"who":"B","t":"Очень вкусно! Я попробую приготовить дома.","ph":"O-chen FKUS-na YA pa-PRO-bu-yu pri-ga-TO-vit' DO-ma","vi":"Ngon quá! Tôi sẽ thử nấu ở nhà.","hl":["попробую"]}],"more":[{"t":"Попробуйте этот торт!","ph":"pa-PRO-buy-te E-tat TORT","vi":"Anh ăn thử bánh này đi!","hl":["Попробуйте"],"tokens":["Попробуйте","этот","торт"]},{"t":"Можно попробовать вино?","ph":"MOZH-na pa-PRO-ba-vat' vi-NO","vi":"Tôi uống thử rượu vang được không?","hl":["попробовать"],"tokens":["Можно","попробовать","вино"]},{"t":"Ты должен попробовать квас.","ph":"TY DOL-zhen pa-PRO-ba-vat' KVAS","vi":"Bạn nhất định phải uống thử kvas.","hl":["попробовать"],"tokens":["Ты","должен","попробовать","квас"]},{"t":"Я попробую говорить по-русски.","ph":"YA pa-PRO-bu-yu ga-va-RIT' pa-RUS-ki","vi":"Tôi sẽ thử nói tiếng Nga.","hl":["попробую"],"tokens":["Я","попробую","говорить","по-русски"]},{"t":"Мы попробуем найти другой отель.","ph":"MY pa-PRO-bu-yem nay-TI dru-GOY a-TEL'","vi":"Chúng tôi sẽ thử tìm khách sạn khác.","hl":["попробуем"],"tokens":["Мы","попробуем","найти","другой","отель"]},{"t":"Давайте попробуем местную кухню сегодня вечером.","ph":"da-VAY-te pa-PRO-bu-yem MYES-nu-yu KUKH-nyu si-VOD-nya VYE-che-ram","vi":"Tối nay chúng ta ăn thử món địa phương nhé.","hl":["попробуем"],"tokens":["Давайте","попробуем","местную","кухню","сегодня","вечером"]}]}];
